#pragma once

#include <iostream>
#include <functional>
#include <map>
#include <memory>
#include <vector>
#include <typeindex>

#include "Event.h"

class EventBus {
    using SubscriberList = std::vector<std::function<void(EventBase&)>>;
    using SubscribersMap = std::map<std::type_index, std::shared_ptr<void>>;

public:
    EventBus() = default;
    virtual ~EventBus() = default;

    template<typename EventType>
    void Subscribe(std::function<void(EventType&)> handler);

    template<typename EventType>
    void Unsubscribe(std::function<void(EventType&)> handler);

    void ClearSubscribers() {
        subscribersMap_.clear();
    }

    template<typename EventType>
    void Publish(EventType event_data);

    template <typename EventType>
    bool postpone(EventType event_data);

private:

    template<typename EventType>
    std::shared_ptr<SubscriberList> GetSubscribersForEvent();

    SubscribersMap subscribersMap_;
};

template<typename EventType>
void EventBus::Subscribe(std::function<void(EventType&)> handler) {
    auto subscriberList = GetSubscribersForEvent<EventType>();
    subscriberList->push_back([handler](EventBase& e) {
        handler(static_cast<Event<EventType>&>(e).data_);
        });
}

template<typename EventType>
void EventBus::Unsubscribe(std::function<void(EventType&)> handler) {
    auto subscribers = GetSubscribersForEvent<EventType>();
    auto& subscriberList = *subscribers;

    auto it = std::find_if(subscriberList.begin(), subscriberList.end(), [&handler](const std::function<void(EventBase&)>& subscriber) {
        auto typedSubscriber = static_cast<std::function<void(EventType&)>>(subscriber);
        return typedSubscriber.target<void(EventType&)>() == handler.target<void(EventType&)>();
        });

    if (it != subscriberList.end()) {
        subscriberList.erase(it);
    }
}


template<typename EventType>
void EventBus::Publish(EventType event_data) {
    Event<EventType> event(event_data);
    auto subscribers = GetSubscribersForEvent<EventType>();
    for (const auto& subscriber : *subscribers) {
        subscriber(event);
    }
}

template <typename EventType>
bool EventBus::postpone(EventType event_data)
{
    Event<EventType> event(event_data);

    auto subscribers = GetSubscribersForEvent<EventType>();
    if (subscribers->empty()) {
        return false;
    }

    for (const auto& subscriber : *subscribers) {
        subscriber(event);
    }
    return true;
}

template<typename EventType>
std::shared_ptr<typename EventBus::SubscriberList> EventBus::GetSubscribersForEvent() {
    std::type_index eventTypeIndex(typeid(EventType));
    if (subscribersMap_.find(eventTypeIndex) == subscribersMap_.end()) {
        subscribersMap_[eventTypeIndex] = std::make_shared<SubscriberList>();
    }

    return std::static_pointer_cast<SubscriberList>(subscribersMap_[eventTypeIndex]);
