        private void AddNewDocument(Items item)
        {
            var borderPanel = CreateBorderPanel(item);
            var mainGrid = CreateMainGrid(item);
            var bottomDarkeningBorder = CreateBottomDarkeningBorder(item);
            var itemName = CreateItemName(item);
            var contextMenu = (ContextMenu)this.FindResource("MyContextMenu");

            borderPanel.Child = mainGrid;
            mainGrid.Children.Add(bottomDarkeningBorder);
            mainGrid.Children.Add(itemName);
            borderPanel.Tag = item;
            contextMenu.Tag = item;
            bottomDarkeningBorder.Tag = item;
            itemName.Tag = item;
            borderPanel.MouseLeftButtonUp += ChangeItemButton_Click;

            if (!SystemContext.isFromFolder)
                borderPanel.ContextMenu = contextMenu;

            bottomDarkeningBorder.MouseLeftButtonUp += ChangeTitleNameButton_Click;
            itemName.MouseLeftButtonUp += ChangeTitleNameButton_Click;

            DocumentsViewGrid.Children.Add(borderPanel);
        }

        private Border CreateBorderPanel(Items item)
        {
            return new Border()
            {
                BorderBrush = Brushes.LightGray,
                BorderThickness = new Thickness(2),
                Style = (Style)DocumentsViewGrid.Resources["ContentBorderStyle"],
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#8a8eab"))
            };
        }

        private Grid CreateMainGrid(Items item)
        {
            var mainGrid = new Grid()
            {
                Name = "mainGrid",
                Resources = (ResourceDictionary)DocumentsViewGrid.Resources["CornerRadiusSetter"]
            };
            SetItemImage(mainGrid, item);
            AddLockImage(mainGrid, item);

            if (SystemContext.isFromFolder)
                AddSelectionImages(mainGrid, item);

            return mainGrid;
        }

        private void SetItemImage(Grid mainGrid, Items item)
        {
            ImageBrush imageBrush = new ImageBrush();
            Image image = new Image()
            {
                Resources = (ResourceDictionary)DocumentsViewGrid.Resources["CornerRadiusSetter"]
            };
            // Set image source
            imageBrush.Stretch = SetImageSource(image, item);
            imageBrush.ImageSource = image.Source;
            mainGrid.Background = imageBrush;
        }

        private void AddLockImage(Grid mainGrid, Items item)
        {
            Image LockImage = new Image()
            {
                Name = "LockImage",
                VerticalAlignment = VerticalAlignment.Top,
                HorizontalAlignment = HorizontalAlignment.Left,
                Margin = new Thickness(5, 5, 0, 0),
                Height = 25,
                Width = 25
            };
            LockImage.Source = new BitmapImage(new Uri("pack://application:,,,/Resources/LockImage.png"));
            mainGrid.Children.Add(LockImage);
            if (item.IPriority == 0)
                LockImage.Visibility = Visibility.Hidden;
        }

        private void AddSelectionImages(Grid mainGrid, Items item)
        {
            Image unselectedImage = CreateUnselectedImage();
            Image selectedImage = CreateSelectedImage();
            mainGrid.Children.Add(unselectedImage);
            mainGrid.Children.Add(selectedImage);

            if (item.IsSelected == 1)
                unselectedImage.Visibility = Visibility.Hidden;
            else
                selectedImage.Visibility = Visibility.Hidden;
        }

        private Image CreateUnselectedImage()
        {
            Image unselectedImage = new Image()
            {
                Name = "unselectedImage",
                VerticalAlignment = VerticalAlignment.Top,
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 5, 5, 0),
                Height = 25,
                Width = 25
            };
            unselectedImage.Source = new BitmapImage(new Uri("pack://application:,,,/Resources/unselected_circle.png"));
            return unselectedImage;
        }

        private Image CreateSelectedImage()
        {
            Image selectedImage = new Image()
            {
                Name = "selectedImage",
                VerticalAlignment = VerticalAlignment.Top,
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 5, 5, 0),
                Height = 25,
                Width = 25
            };
            selectedImage.Source = new BitmapImage(new Uri("pack://application:,,,/Resources/selected_circle.png"));
            return selectedImage;
        }

        private Border CreateBottomDarkeningBorder(Items item)
        {
            return new Border()
            {
                Style = (Style)DocumentsViewGrid.Resources["BottomBorderProperties"],
                VerticalAlignment = VerticalAlignment.Bottom
            };
        }

        private TextBlock CreateItemName(Items item)
        {
            return new TextBlock()
            {
                Text = item.Title,
                Style = (Style)DocumentsViewGrid.Resources["DocumentTextBlockPropeties"]
            };
        }

        // Other methods remain the same
    }
}
```

