You can move these checks into the Yup validation schema, making use of custom validation functions. Here's how you can refactor your schema to include these checks:

```javascript
import { MAX_DATE, MIN_DATE } from 'constants/manualActions';
import * as Yup from 'yup';

const ActivityLogSearchFormValidationSchema = Yup.object().shape({
  startTime: Yup.date()
    .required()
    .min(MIN_DATE, 'validations.fromMinMessage') // error message should be translated
    .test(
      'isBefore',
      'validations.dateOrderMessage', // error message should be translated
      function (startTime) {
        const endTime = this.resolve(Yup.ref('endTime'));
        if (!startTime || !endTime) return true;
        return startTime <= endTime;
      },
    ),
  endTime: Yup.date()
    .required()
    .max(MAX_DATE, 'validations.toMaxMessage') // error message should be translated
    .test(
      'isAfter',
      'validations.dateOrderMessage', // error message should be translated
      function (endTime) {
        const startTime = this.resolve(Yup.ref('startTime'));
        if (!endTime || !startTime) return true;
        return endTime >= startTime;
      },
    ),
  username: Yup.string(),
  idType: Yup.string(),
  id: Yup.string().when('idType', {
    is: (idType) => !!idType,
    then: Yup.string()
      .matches(noSpaces, 'validations.cannotContainSpaces') // error message should be translated
      .required(),
    otherwise: Yup.string(),
  }),
  action: Yup.string(),
});
```

With this new schema in place, the `isBefore`, `isAfter`, and `!isFormValid` checks have been moved into the schema. This will reduce the `disabled` prop for the submit button to:

```javascript
