        }
      })
      .catch((error) => {
        console.error("Error:", error);
        alert("Error uploading track");
      });
  }

  document
    .getElementById("upload-form")
    .addEventListener("submit", submitForm);
}

window.addEventListener("DOMContentLoaded", init);
```

Этот код добавляет обработчик событий для формы с идентификатором "upload-form". Обработчик отменяет стандартное поведение формы (обычная отправка HTTP-запроса) и отправляет данные формы асинхронно с использованием fetch API.

Таким образом, файлы (музыка и изображение) должны быть успешно загружены на сервер и отображаться в профиле пользователя.

