#include <ifaddrs.h>
#include <sys/ioctl.h>
#include <linux/ethtool.h>
#include <linux/sockios.h>
#include <net/if.h>
#include <arpa/inet.h>
#include <unistd.h>

// Function to get SQI information from the PHY of an Ethernet interface
int getSQI(const std::string &iface, int &sqi) {
    // Create a socket for interfacing with the kernel
    int sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_IP);
    if (sock < 0) {
        perror("socket");
        return -errno;
    }

    struct ifreq ifr;
    struct ethtool_value edata;

    // Set the interface name to use with the ioctl calls
    strncpy(ifr.ifr_name, iface.c_str(), IF_NAMESIZE - 1);
    ifr.ifr_data = (char *)&edata;

    // Get the SQI value using the appropriate ethtool command
    edata.cmd = ETHTOOL_GSQI;
    int err = ioctl(sock, SIOCETHTOOL, &ifr);
    if (err < 0) {
        perror("ioctl (SIOCETHTOOL, GSQI)");
        close(sock);
        return -errno;
    }

    sqi = edata.data;

    close(sock);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    std::string iface(argv[1]);
    int sqi;

    int err = getSQI(iface, sqi);
    if (err) {
        std::cerr << "Error getting SQI for " << iface << ": " << strerror(-err) << "\n";
        return 1;
    }

    std::cout << "SQI for " << iface << ": " << sqi << "\n";

    return 0;
}
```

