// Создаем объект PropertyValue для каждого свойства таблицы и добавляем его в массив.

PropertyValue tableBorderProperty;
tableBorderProperty.Name = "Border";
tableBorderProperty.Value <<= 1; // толщина линии границ таблицы равна 1 пикселю.

PropertyValue tableWidthProperty;
tableWidthProperty.Name = "Width";
tableWidthProperty.Value <<= 2000; // ширина таблицы равна 2000 тысячитысячных дюйма.

