function countSubstrings(s, t) {
  let count = 0;
  const n = s.length;
  const m = t.length;

  // For each substring of s, check if it can be formed from
  // the letters in t after discarding some characters.
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      const sSubstring = s.slice(i, j + 1);
      if (sSubstring.length > m) {
        // sSubstring is longer than t, so it can't be formed
        // from the letters in t.
        continue;
      }
      const tSubstringCounts = {};
      for (let k = 0; k < sSubstring.length; k++) {
        const char = sSubstring[k];
        if (!tSubstringCounts[char]) {
          tSubstringCounts[char] = 0;
        }
        tSubstringCounts[char]++;
      }

      let validSubstring = true;
      for (let k = 0; k < m; k++) {
        const char = t[k];
        if (!tSubstringCounts[char]) {
          // char is not present in sSubstring.
          validSubstring = false;
          break;
        }
        tSubstringCounts[char]--;
        if (tSubstringCounts[char] < 0) {
          // More occurrences of char in t than in sSubstring.
          validSubstring = false;
          break;
        }
      }

      if (validSubstring) {
        count++;
      }
    }
  }

  return count;
}
```

You can call this function with two arguments: the string `s` and the string `t`. It returns the number of substrings of `s` that can be formed by discarding some characters and rearranging the remaining ones to form a substring of `t`.

Here's an example of how to use the function:

```js
