        res.status(400).send("No track file was uploaded.");
        return;
    }

	if (trackFile && !trackFile.name.endsWith(".mp3")) {
res.status(400).send("Only .mp3 files can be uploaded.");
return;
}

// Set a maximum file size of 10MB for uploaded files
const maxSizeInBytes = 10000000; // 10MB
if (trackFile && trackFile.size > maxSizeInBytes) {
res.status(400).send("File size exceeds 10MB limit.");
return;
}
    const trackFilename = "track_" + musicianId + "" + trackFile.name;
	const tmpPath = './public/tracks/tmp_' + trackFilename;
