В методе handleRead следует изменить обработку запросов так, чтобы она пользовалась экземпляром класса ConnectionContext. Теперь, код будет восстанавливаться с последнего сохраненного состояния, и не будет останавливаться ни на какой из стадий передачи файла.

```java
private void handleRead(SelectionKey key) throws IOException {
    SocketChannel clientSocketChannel = (SocketChannel) key.channel();
    ConnectionContext context = (ConnectionContext) key.attachment();
    ByteBuffer buffer = context.getBuffer();

    int bytesRead;
    while ((bytesRead = clientSocketChannel.read(buffer)) > 0) {

        buffer.flip();

        while (buffer.hasRemaining()) {
            switch (context.getState()) {

                case FILE_NAME_LENGTH:
                    if (buffer.remaining() < Integer.BYTES) {
                        buffer.compact();
                        return;
                    }
                    int nameLength = buffer.getInt();
                    context.setFileNameLength(nameLength);
                    context.setState(ConnectionState.FILE_NAME);

                case FILE_NAME:
                    if (buffer.remaining() < context.getFileNameLength()) {
                        buffer.compact();
                        return;
                    }
                    byte[] nameBytes = new byte[context.getFileNameLength()];
                    buffer.get(nameBytes);
                    String fileName = new String(nameBytes, StandardCharsets.UTF_8);
                    context.setFileName(fileName);
                    context.setState(ConnectionState.FILE_LENGTH);

                case FILE_LENGTH:
                    if (buffer.remaining() < Integer.BYTES) {
                        buffer.compact();
                        return;
                    }
                    int fileLength = buffer.getInt();
                    context.setFileLength(fileLength);
                    context.setState(ConnectionState.FILE_CONTENT);

                case FILE_CONTENT:
                    if (buffer.remaining() < context.getFileLength()) {
                        buffer.compact();
                        return;
                    }
                    byte[] fileContent = new byte[context.getFileLength()];
                    buffer.get(fileContent, 0, context.getFileLength());
                    saveFile(context.getFileName(), fileContent);
                    context.setState(ConnectionState.SEPARATOR);

                case SEPARATOR:
                    if (buffer.remaining() < Long.BYTES) {
                        buffer.compact();
                        return;
                    }
                    long separator = buffer.getLong();
                    if (separator != 0) {
                        throw new RuntimeException("Invalid separator");
                    }
                    sendAck(clientSocketChannel, context.getFileName());
                    context.setState(ConnectionState.ACK);

                case ACK:
                    break;
            }
        }

        buffer.clear();
    }

    if (bytesRead == -1) {
        System.out.println("Closed connection with " + clientSocketChannel.getRemoteAddress());
        clientSocketChannel.close();
        key.cancel();
        System.out.println("============ * ============");
    }
}
```

С использованием ConnectionContext ваш сервер теперь сможет обрабатывать несколько клиентов одновременно, и, если передача файла замедлена или остановлена, сервер будет продолжать обрабатывать запросы других клиентов.

