Developing a full, working program from scratch is beyond the scope of this platform. However, I can extend the code provided earlier to include .wav file reading & writing using libsndfile, allowing you to process and apply the moving average filter to .wav files.

Make sure you have libsndfile installed before attempting to use this code.

```cpp
#include <iostream>
#include <vector>
#include <sndfile.h>

std::vector<double> moving_average_filter(const std::vector<double>& input, int window_size) {
    std::vector<double> output;
    int input_size = input.size();

    for (int i = 0; i < input_size; i++) {
        double sum = 0.0;
        int count = 0;
        for (int j = i - window_size; j <= i + window_size; j++) {
            if (j >= 0 && j < input_size) {
                sum += input[j];
                count++;
            }
        }
        output.push_back(sum / count);
    }

    return output;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " input.wav output.wav" << std::endl;
        return 1;
    }

    SF_INFO sf_info;
    SNDFILE* in_file = sf_open(argv[1], SFM_READ, &sf_info);
    if (!in_file) {
        std::cerr << "Error: failed to open input file!" << std::endl;
        return 1;
    }

    if (sf_info.channels != 1) {
        std::cerr << "Error: only mono files are supported!" << std::endl;
        sf_close(in_file);
        return 1;
    }

    int num_samples = sf_info.frames * sf_info.channels;
    std::vector<double> samples(num_samples);
    sf_readf_double(in_file, samples.data(), sf_info.frames);

    int window_size = 10;  // The size of the moving average window
    std::vector<double> filtered_samples = moving_average_filter(samples, window_size);

    sf_close(in_file);

    SNDFILE* out_file = sf_open(argv[2], SFM_WRITE, &sf_info);
    if (!out_file) {
        std::cerr << "Error: failed to open output file!" << std::endl;
        return 1;
    }

    sf_writef_double(out_file, filtered_samples.data(), sf_info.frames);

    sf_close(out_file);

    return 0;
}
```

