const express = require('express');
const bodyParser = require('body-parser');
const { Pool } = require('pg');

const app = express();
const port = process.env.PORT || 3000;

app.use(express.static(__dirname));
app.use(bodyParser.urlencoded({ extended: true }));
app.use(bodyParser.json());

const pool = new Pool({
    connectionString: process.env.DATABASE_URL || "postgres://username:password@localhost:5432/database_name",
});

app.post('/submit_contact', async (req, res) => {
    try {
        const { name, email, message } = req.body;
        const query = "INSERT INTO contacts (name, email, message) VALUES ($1, $2, $3)";
        await pool.query(query, [name, email, message]);
        res.sendStatus(200);
    } catch (error) {
        console.error(error);
        res.sendStatus(500);
    }
});

