#include <com/sun/star/awt/FontDescriptor.hpp>

using namespace com::sun::star::uno;
using namespace com::sun::star::awt;

int main(int argc, char** argv)
{
    // Определение пути к файлу OpenOffice/LibreOffice
    osl::FileBase::RC eRC;
    OUString sOfficePath = osl::FileBase::getSystemPathFromFileURL(
        Reference<XComponentContext>::create(
            comphelper::getProcessServiceFactory()
        )->getURLResolver()->resolve(
            OUString("vnd.sun.star.expand:$LO_USER_PROGRAM_PATH")
        )
    , eRC);

    // Инициализация структуры FontDescriptor
    FontDescriptor aFontDesc;
    aFontDesc.Name = OUString::createFromAscii("Calibri"); // задаем имя шрифта
    aFontDesc.Height = 14; // задаем размер шрифта
    aFontDesc.Weight = 100; // задаем жирность шрифта
