#include <com/sun/star/style/XStyleLoader.hpp>

using namespace com::sun::star::lang;
using namespace com::sun::star::text;
using namespace com::sun::star::style;

// ...

// создание нового текстового документа
Reference<XMultiServiceFactory> xFactory = 
    Reference<XMultiServiceFactory>::create(
        comphelper::getProcessServiceFactory()
    );

Reference<XInterface> xTextDocument = 
    xFactory->createInstance(
        OUString("com.sun.star.text.TextDocument")
    );

Reference<XText> xText = 
    Reference<XTextDocument>(xTextDocument, UNO_QUERY_THROW)
        ->getText();

// задание стиля документа
Reference<XStyleFamiliesSupplier> xSupplier = 
    Reference<XStyleFamiliesSupplier>(xTextDocument, UNO_QUERY_THROW);

Reference<XNameAccess> xStyles = 
    xSupplier->getStyleFamilies();

Reference<XStyle> xStyle = 
    Reference<XStyle>(xStyles->getByName(
        OUString::createFromAscii("PageStyles")
    ), UNO_QUERY_THROW);

