// Создаем объект PropertyValue для задания значения свойства шрифта
PropertyValue aFontProp;
aFontProp.Name = "CharFontName"; // Имя свойства шрифта

// Создаем объект FontDescriptor для задания имени шрифта
FontDescriptor aFontDesc;
aFontDesc.Name = "Calibri"; // Имя шрифта
