To draw a rectangle with rounded corners, you can modify the `drawRoundedRect` function with an additional background color parameter. Then, you can fill the outer rounded rectangle with the background color and the inner rectangle with the desired fill color. Here's the updated code:

```javascript
export const drawRoundedRect = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  radius: number,
  fillColor: string,
  bgColor: string,
): void => {
  // Draw outer rounded rectangle with background color
  ctx.beginPath();
  ctx.fillStyle = bgColor;
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + width - radius, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
  ctx.lineTo(x + width, y + height - radius);
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
  ctx.lineTo(x + radius, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
  ctx.fill();

  // Draw inner rectangle with fill color
  ctx.beginPath();
  ctx.fillStyle = fillColor;
  ctx.rect(x + 1, y + 1, width - 2, height - 2);
  ctx.fill();
};
```

