rapidjson::Document load_json(const std::string &filename) {
    using namespace rapidjson;
    FILE *file = std::fopen(filename.c_str(), "r");

    char buffer[65536];
    FileReadStream is(file, buffer, sizeof(buffer));
    Document document;
    document.ParseStream(is);
    fclose(file);

    return document;
}
