const messageList = document.getElementById("messageList");
const messageInput = document.getElementById("messageInput");
const sendButton = document.getElementById("sendButton");

const firestore = firebase.firestore();

// Load messages from Firestore
firestore.collection("messages").orderBy("timestamp").onSnapshot((snapshot) => {
    messageList.innerHTML = "";
    snapshot.forEach((doc) => {
        const message = doc.data();
        const messageElement = document.createElement("div");
        messageElement.textContent = `${message.username}: ${message.text}`;
        messageList.appendChild(messageElement);
    });
});

// Send message
sendButton.addEventListener("click", () => {
    const text = messageInput.value.trim();

    if (text.length === 0) {
        return;
    }

    const username = "AnonymousUser"; // You can add user authentication to get user-specific details.
    const message = {
        username: username,
        text: text,
        timestamp: firebase.firestore.FieldValue.serverTimestamp()
    };

    firestore.collection("messages").add(message).then(() => {
        messageInput.value = "";
    });
});
```

