const certificateController = require('../controllers/certificateController');

router.route('/').post(certificateController.generateCertificate);

module.exports = router;
```

This file defines the `/api/certificate` route with a POST method, which triggers the `certificateController` to generate dynamic PDF certificates.

`certificateController.js`:

```javascript
const Certificate = require('../models/certificate');
const pdf = require('html-pdf');
const certificateTemplate = require('../pdf_templates/certificate_template');
const options = { format: 'Letter' };

exports.generateCertificate = async (req, res) => {
  const { name, award, eventDate } = req.body;
  const certificate = new Certificate({
    name,
    award,
    eventDate,
  });

  await certificate.save();

  pdf.create(certificateTemplate(certificate), options).toBuffer((err, buffer) => {
    if (err) {
      return res.status(500).send({ error: 'Error while generating PDF' });
    }

    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', 'attachment; filename="certificate.pdf"');

    return res.send(buffer);
  });
};
```

This file exports the `generateCertificate` function that receives the HTTP POST request from the front-end, creates a new instance of the `Certificate` model and saves it in the database. It then generates dynamic PDF certificates using a PDF library `html-pdf` by calling the `certificateTemplate` function that generates HTML using a Pug templating engine from `views/certificate.pug` instead of HTML. The certificate data is passed to the function in the form of a `certificate` object. Finally, the generated PDF is returned to the user using the `res.send(buffer)` property.

