A better approach to load and create entities would be to use the previously created Factory class to streamline the JSON parsing process. The updated function would look like:

```cpp
void Scene::Load(const std::string& filename)
{
    std::ifstream file(filename);

    if (!file.is_open())
    {
        std::cout << "Failed to open file: " << filename << std::endl;
        return;
    }

    rapidjson::IStreamWrapper isw(file);
    rapidjson::Document document;
    document.ParseStream(isw);

    // Check if parsing was successful
    if (document.HasParseError())
    {
        std::cout << "Failed to parse JSON file: " << filename << std::endl;
        return;
    }

    const rapidjson::Value& entitiesArray = document["Scene"]["entities"];

    // Initialize the Factory for component creation
    Factory factory;
    factory.RegisterComponent<Position>();
    factory.RegisterComponent<Name>();
    factory.RegisterComponent<Size>();
    factory.RegisterComponent<Velocity>();
    factory.RegisterName<Position>("Position");
    factory.RegisterName<Name>("Name");
    factory.RegisterName<Size>("Size");
    factory.RegisterName<Velocity>("Velocity");

    for (rapidjson::SizeType i = 0; i < entitiesArray.Size(); ++i) {
        const rapidjson::Value& entity = entitiesArray[i];

        // Create the entity in your ECS system (assuming you have an ECS instance called "ecs")
        Entity newEntity(entityComponentSystem_);

        // Iterate through each component of the entity
        for (auto componentIter = entity.MemberBegin(); componentIter != entity.MemberEnd(); ++componentIter)
        {
            std::string componentName = componentIter->name.GetString();

            std::unique_ptr<ComponentBase> newComponent = factory.CreateComponentFromJson(componentName, componentIter->value);
            newEntity.AddComponent(std::move(newComponent));
        }
    }
}
```

In this updated version of `Scene::Load`, you would use the `Factory` class to manage component registration and creation from JSON data, making the code cleaner and easier to maintain. The factory reads the component name from the JSON and creates the corresponding components based on their registered names.

