```solidity
pragma solidity ^0.4.24;

contract SimpleMultiSigWallet {
    address[] public owners;
    uint256 public required;

    mapping(address => bool) public isOwner;

    // Modifiers
    modifier onlyOwner() {
        require(isOwner[msg.sender], "Not an owner");
        _;
    }

    event Deposit(address indexed sender, uint256 amount);
    event Executed(address indexed destination, uint256 value, bytes data);

    constructor(address[] _signers, uint256 _required) public {
        require(_signers.length >= _required && _required != 0 && _signers.length != 0, "Invalid parameters");

        for (uint256 i = 0; i < _signers.length; i++) {
            require(!isOwner[_signers[i]] && _signers[i] != address(0), "Invalid signer");
            isOwner[_signers[i]] = true;
        }
        owners = _signers;
        required = _required;
    }

    function() external payable {
        if (msg.value > 0) emit Deposit(msg.sender, msg.value);
    }

    function execute(address destination, uint256 value, bytes data, uint8[] sigV, bytes32[] sigR, bytes32[] sigS)
        external onlyOwner
    {
        require(sigR.length == required && sigR.length == sigS.length && sigR.length == sigV.length, "Invalid signatures");

        bytes32 txHash = keccak256(abi.encodePacked(destination, value, data));

        address[] memory seenAddresses = new address[](required);

        for (uint256 i = 0; i < required; i++) {
            address recoveredAddress = ecrecover(txHash, sigV[i], sigR[i], sigS[i]);
            require(isOwner[recoveredAddress], "Invalid signature, signer must be an owner");

            // Avoid duplicate signer
            for (uint256 j = 0; j < i; j++) {
                require(recoveredAddress != seenAddresses[j], "Duplicate signer");
            }
            seenAddresses[i] = recoveredAddress;
        }

        bool success;
        assembly {
            success := call(gas, destination, value, add(data, 0x20), mload(data), 0, 0)
        }
        require(success, "Transaction failed");

        emit Executed(destination, value, data);
    }

    function getOwners() public view returns (address[]) {
        return owners;
    }
}
```

