template<class C>
void ECS::RegisterComponent()
{
	size_t componentTypeId = Component<C>::GetTypeID();

	if (componentMap.contains(componentTypeId))
		return; // can't re-register a type

	componentMap.emplace(componentTypeId, new Component<C>);
