// AddComponents for multiple components (more than 1)
template <typename... Components, typename... Args,
          std::enable_if_t<(sizeof...(Components) != 1)>* = nullptr>
void ECS::AddComponents(const EntityId entityId, Args&&... args) {
    UpdateComponentMasks<Components...>(entityId);
    AddComponentsInternal<Components...>(entityId, std::tuple<Args...>(std::forward<Args>(args)...));

    Archetype* newArchetype = GetArchetype(componentMasks[entityId]);
    Record& record = entityArchetypeMap[entityId];
    UpdateRecord(entityId, newArchetype, record);
