// AddComponentsInternal function processing the tuple
template <typename... Components, typename... Args>
void ECS::AddComponentsInternal(const EntityId entityId, const std::tuple<Args...>& args) {
    AddComponentsInternal<Components...>(entityId, args, std::index_sequence_for<Args...>());
