const express = require('express');
const mongoose = require('mongoose');
const bodyParser = require('body-parser');
const cors = require('cors');
const dotenv = require('dotenv');

dotenv.config(); // Load environment variables from a .env file

const app = express();
const port = process.env.PORT || 3000;

// Connect to MongoDB database
mongoose.connect(process.env.MONGO_URI, {
    useNewUrlParser: true,
    useCreateIndex: true,
    useUnifiedTopology: true
})
.then(() => console.log('MongoDB connected'))
.catch((err) => console.log(err));

// Register middleware
app.use(cors());
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

// Define forecast schema and model
const forecastSchema = new mongoose.Schema({
    data: {
        type: String,
        required: true
    },
    predictedValue: {
        type: Number,
        required: true
    },
    confidence: {
        type: Number,
        required: true
    }
});

const Forecast = mongoose.model('forecast', forecastSchema);

// Define API endpoints
app.get('/forecast', (req, res) => {
    const { data } = req.query;

    // TODO: Use data to perform forecasting here

    const forecast = { predictedValue: 50, confidence: 0.9 };

    // Save the forecast to the MongoDB database
    const newForecast = new Forecast({ data, ...forecast });
    newForecast.save()
        .then(() => console.log('Forecast saved to database'))
        .catch((err) => console.log(err));

    res.send(forecast);
});

// Start the server
app.listen(port, () => {
    console.log(`Server listening at http://localhost:${port}`);
});
```

The above code defines a `server.js` file that connects to the MongoDB database, creates a `Forecast` model, and defines the `/forecast` endpoint to perform forecasting and saving forecast data to the database.

