      <form onSubmit={handleFormSubmit}>
        <input type="text" onChange={handleInputChange} />
        <button type="submit">Predict</button>
      </form>
      <h1>Predicted Value: {forecast.predictedValue}</h1>
      <h2>Confidence: {forecast.confidence}</h2>
    </div>
  );
}

export default App;
```

