Конечно, сделаем брокер сообщений на основе TCP. В этом случае, вам не понадобится библиотека `ws`. Вместо этого используем модуль `net`, встроенный в Node.js.

Создайте файл `tcpMessageBroker.js` и вставьте следующий код:

```javascript
const net = require('net');
const { v4: uuidv4 } = require('uuid');

const server = net.createServer();

const clients = new Set();

server.on('connection', (socket) => {
  const client = {
    id: uuidv4(),
    socket,
  };

  clients.add(client);

  console.log(`Client connected: ${client.id}`);

  socket.on('data', (data) => {
    const messageString = data.toString();
    const eventData = JSON.parse(messageString);
    brodcast(eventData, client.id);
  });

  socket.on('end', () => {
    console.log(`Client disconnected: ${client.id}`);
    clients.delete(client);
  });

  socket.on('error', (error) => {
    console.error(`Client error: ${client.id}`, error);
  });
});

function brodcast(eventData, senderId) {
  clients.forEach((client) => {
    if (client.id === senderId) {
      return;
    }

    try {
      client.socket.write(JSON.stringify(eventData));
    } catch (error) {
      console.error(`Error sending message to ${client.id}`, error);
    }
  });
}

const port = 8080;
server.listen(port, () => {
  console.log(`Message broker is running on port ${port}`);
});
```

Теперь у вас есть TCP-брокер сообщений. Запустите его, выполнив команду `node tcpMessageBroker.js`.

