      data: Date.now(),
    };

    client.write(JSON.stringify(message));
    console.log('Message sent:', message);
  }, 1000);
});

client.on('data', (data) => {
  console.log('Message received:', JSON.parse(data));
});

client.on('error', (error) => {
  console.error('Connection error:', error);
});

client.on('end', () => {
  console.log('Disconnected from the message broker');
});
```

Запустите клиента, выполнив команду `node tcpClient.js`. Подобно предыдущему примеру, вы можете запустить несколько копий этого клиента, и они будут обмениваться сообщениями через TCP-брокер. Важно отметить, что этот код не является production-ready, и его следует дальше развивать и адаптировать под вашу конкретную задачу.

