I see, you want the main content to stay in place (or move aside) while the sider is visible on mobile screens. To achieve this, you can change the CSS styles of the Layout components.

Add a new state variable, `isMobile`, which is initialized to false and will be set to true when the screen size is less than the breakpoint. Then use the value of `isMobile` to conditionally apply styles to the Layout components.

Here's the updated code for your App component:

```javascript
import './App.css'; // Import a separate CSS file for these custom styles

const App = () => {
  // ...
  // Add a new state variable 'isMobile'
  const [isMobile, setIsMobile] = useState(false);

  // Add an effect to update 'isMobile'
  useEffect(() => {
    const handleResize = () => {
      window.innerWidth <= 576 ? setIsMobile(true) : setIsMobile(false);
    };

    handleResize(); // Call on initial render
    window.addEventListener('resize', handleResize); // Update on window resize
    return () => window.removeEventListener('resize', handleResize); // Cleanup event listener
  }, []);

  //....

  return (
    <ConfigProvider
      //...
    >
      <Layout>
        <Sider
          breakpoint="sm"
          collapsedWidth="0"
          onBreakpoint={setIsMobile} // <-- Update the 'isMobile' state
          trigger={null}
          collapsible
          collapsed={collapsed}
          style={{ border: '0', backgroundColor: '#000000' }}
        >
        //...
        </Sider>
        <Layout
          className={isMobile && !collapsed ? 'layout main-content-shifted' : 'layout'}
          direction="rtl"
        >
        //...
        </Layout>
      </Layout>
      //...
    </ConfigProvider>
  );
};
```

