import {CanvasSize} from "./Cup";
import cupOptions, {drawRoundedRect} from "./Cup.options";
import cupTools from "./Cup.tools";
import {CupItem} from "../../../hooks/rustWsServer";

const cupDrawer = {
  clear: (ctx: CanvasRenderingContext2D, size: CanvasSize) => {
    ctx.clearRect(0, 0, size.width, size.height);
  },
  drawCell: (
    ctx: CanvasRenderingContext2D,
    cupItem: CupItem,
    maxVolume: number,
    isBestPrice: boolean,
    yPosition: number,
    cellHeight: number,
    fullWidth: number,
    dpiScale: number,
    darkMode: boolean,
  ) => {
    ctx.beginPath();
    ctx.strokeStyle = cupOptions(darkMode).border.color;
    ctx.lineWidth = cupOptions(darkMode).border.width;
    ctx.fillStyle = cupTools.getCellBackground(cupItem.side, isBestPrice, darkMode);
    // @ts-ignore
    ctx.roundRect(
      0,
      yPosition,
      cupTools.getCellWidth(fullWidth, cupItem.quantity, maxVolume, isBestPrice),
      cellHeight,
      cupOptions(darkMode).border.radius * dpiScale,
    );
    ctx.fill();
    ctx.stroke();
  },
  drawFill: (
    ctx: CanvasRenderingContext2D,
    cupItem: CupItem,
    maxVolume: number,
    yPosition: number,
    cellHeight: number,
    fullWidth: number,
    dpiScale: number,
    darkMode: boolean,
  ) => {
    ctx.beginPath();
    ctx.strokeStyle = "#ffffff00";
    ctx.lineWidth = cupOptions().border.width;
    ctx.fillStyle = cupItem.side === "Buy"
      ? cupOptions(darkMode).bestBuy.fillColor
      : cupOptions(darkMode).bestSell.fillColor;
    ctx.roundRect(
      0,
      yPosition,
      cupTools.getCellWidth(fullWidth, cupItem.quantity, maxVolume, false),
      cellHeight,
      cupOptions().border.radius * dpiScale,
    );
    ctx.fill();
    ctx.stroke();
  },
  drawPrice: (
    ctx: CanvasRenderingContext2D,
    price: string,
    side: string,
    isBestPrice: boolean,
    yPosition: number,
    cellHeight: number,
    fullWidth: number,
    dpiScale: number,
    darkMode: boolean,
  ) => {
    const {width: textWidth} = ctx.measureText(price);
    ctx.textBaseline = "middle";
    ctx.font = `${cupOptions().font.weight} ${cupOptions().font.sizePx * dpiScale}px ${cupOptions().font.family}`;
    ctx.fillStyle = cupTools.getPriceColor(side, isBestPrice, darkMode);
    ctx.fillText(
      price,
      fullWidth - cupOptions().cell.paddingX * dpiScale - textWidth,
      yPosition + cellHeight / 2,
    );
  },
  drawQuantity: (
    ctx: CanvasRenderingContext2D,
    quantity: string,
    side: string,
    isBestPrice: boolean,
    yPosition: number,
    cellHeight: number,
    fullWidth: number,
    dpiScale: number,
    darkMode: boolean,
  ) => {
    ctx.textBaseline = "middle";
    ctx.fillStyle = cupTools.getQuantityColor(side, isBestPrice, darkMode);
    ctx.fillText(
      quantity,
      cupOptions().cell.paddingX * dpiScale,
      yPosition + cellHeight / 2,
    );
  },
};

export default cupDrawer;

