        #pragma omp for private(i) 
        for (i = 0; i < len; i++) {
            char ch = essay[i];
            if (isalpha(ch) || ch == '-') {
                essay[i] = tolower(ch);
            } else {
                essay[i] = ' ';
            }
        }

        // 处理单词
        #pragma omp for private(i) reduction(+:num_words)
        for (i = 0; i < len; i += WORD_LENGTH + 1) {
            char *word_end = essay + i + WORD_LENGTH;
            if (word_end >= essay + len) {
                word_end = essay + len;
            }

            // 找到下一个单词的开头
            while (*essay != '\0' && !isalpha(*essay)) {
                essay ++;//essay单词
            }

            // 处理单词
            if (*essay != '\0') {
