                    *word_end = tolower(*essay);
                    word_end++;
                    essay++;
                } while (word_end < essay + WORD_LENGTH && word_end < essay + len && isalpha(*essay));

                // 将单词记录到 wordcount 数组中
                char word[WORD_LENGTH + 1] = {0};
                memcpy(word, essay - word_len, word_len);
