  ctx.lineWidth = cupOptions(darkMode).border.width;
  ctx.fillStyle = cupTools.getCellBackground(cupItem.side, isBestPrice, darkMode);

  drawRoundedRect(
    ctx,
    0,
    yPosition,
    cupTools.getCellWidth(fullWidth, cupItem.quantity, maxVolume, isBestPrice),
    cellHeight,
    cupOptions(darkMode).border.radius * dpiScale,
  );

  ctx.fill();
  ctx.stroke();

  drawCorners(
    ctx,
    0,
    yPosition,
    cupTools.getCellWidth(fullWidth, cupItem.quantity, maxVolume, isBestPrice),
    cellHeight,
    cupOptions(darkMode).border.radius * dpiScale,
    darkMode
  );
},

drawCorners: (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  radius: number,
  darkMode: boolean,
) => {
  ctx.beginPath();

  // Draw top left corner
  ctx.arc(x + radius, y + radius, radius, Math.PI, (3 * Math.PI) / 2);
  ctx.lineTo(x, y + height);
  ctx.lineTo(x + radius, y + height);
  ctx.closePath();

  // Draw top right corner
  ctx.moveTo(x + width - radius, y + radius);
  ctx.arc(x + width - radius, y + radius, radius, (3 * Math.PI) / 2, 0);
  ctx.lineTo(x + width, y + height);
  ctx.lineTo(x + width - radius, y + height);
  ctx.closePath();

  // Draw bottom left corner
  ctx.moveTo(x + radius, y + height - radius);
  ctx.arc(x + radius, y + height - radius, radius, Math.PI / 2, Math.PI);
  ctx.lineTo(x, y);
  ctx.lineTo(x + radius, y);
  ctx.closePath();

  // Draw bottom right corner
  ctx.moveTo(x + width - radius, y + height - radius);
  ctx.arc(x + width - radius, y + height - radius, radius, 0, Math.PI / 2);
  ctx.lineTo(x + width, y);
  ctx.lineTo(x + width - radius, y);
  ctx.closePath();

  ctx.fillStyle = darkMode ? "#191919" : "#ffffff";
  ctx.fill();
},
```

This modified version of the `drawCell` function first draws a rounded rectangle as before, and then calls the new `drawCorners` function to draw the rounded corners of the rectangle. The `drawCorners` function simply draws four arcs and lines to create the required corner shapes, filling them with the appropriate color for the current theme mode (light or dark).

