```javascript
import React, { useContext, useState, createContext } from "react";
import OtherComponent from "./OtherComponent"; // Assuming you have a separate file for the other component
import { ConfigProvider, Modal, Button } from "antd";

// Define ModalContext directly in the App.js
export const ModalContext = createContext({
  showModal: () => {},
});

const App = () => {
  const [visible, setVisible] = useState(false);

  const showModal = () => {
    setVisible(true);
  };

  const handleCancel = () => {
    setVisible(false);
  };

  return (
    <ConfigProvider>
      <ModalContext.Provider value={{ showModal }}>
        <OtherComponent />
        <Modal
          title="Sample Modal"
          visible={visible}
          onCancel={handleCancel}
          footer={null}
        >
          <p>Sample modal content</p>
        </Modal>
      </ModalContext.Provider>
    </ConfigProvider>
  );
};

export default App;
```

