void Mesh::Initialize(std::vector<Vertex> vertices, std::vector<uint32_t> indices, vk::Device device, vk::PhysicalDevice physicalDevice, vk::CommandPool commandPool, vk::Queue graphicsQueue)
{
	this->vertices = vertices;
	this->indices = indices;
	this->device = device;

	Initialize(device, physicalDevice, commandPool, graphicsQueue);
}

void Mesh::Initialize(vk::Device device, vk::PhysicalDevice physicalDevice, vk::CommandPool commandPool, vk::Queue graphicsQueue)
{
	this->device = device;

	vk::DeviceSize bufferSize = sizeof(vertices[0]) * vertices.size();

	// Create vertex buffer
	{
		vk::Buffer stagingBuffer;
		vk::DeviceMemory stagingBufferMemory;

		BufferUtils::CreateBuffer(device, physicalDevice, bufferSize,
			vk::BufferUsageFlagBits::eTransferSrc, vk::MemoryPropertyFlagBits::eHostVisible | vk::MemoryPropertyFlagBits::eHostCoherent,
			stagingBuffer, stagingBufferMemory);

		void* data;
		device.mapMemory(stagingBufferMemory, 0, bufferSize, vk::MemoryMapFlags(), &data);
		memcpy(data, vertices.data(), static_cast<size_t>(bufferSize));
		device.unmapMemory(stagingBufferMemory);

		BufferUtils::CreateBuffer(device, physicalDevice, bufferSize,
			vk::BufferUsageFlagBits::eVertexBuffer | vk::BufferUsageFlagBits::eTransferDst, vk::MemoryPropertyFlagBits::eDeviceLocal,
			vertexBuffer, vertexBufferMemory);

		BufferUtils::CopyBuffer(device, commandPool, graphicsQueue, stagingBuffer, vertexBuffer, bufferSize);

		device.destroyBuffer(stagingBuffer);
		device.freeMemory(stagingBufferMemory);
	}

	// Create index buffer
	{
		vk::Buffer stagingIndexBuffer;
		vk::DeviceMemory stagingIndexBufferMemory;

		bufferSize = sizeof(indices[0]) * indices.size();

		BufferUtils::CreateBuffer(device, physicalDevice, bufferSize,
			vk::BufferUsageFlagBits::eTransferSrc, vk::MemoryPropertyFlagBits::eHostVisible | vk::MemoryPropertyFlagBits::eHostCoherent,
			stagingIndexBuffer, stagingIndexBufferMemory);

		void* data;
		device.mapMemory(stagingIndexBufferMemory, 0, bufferSize, vk::MemoryMapFlags(), &data);
		memcpy(data, indices.data(), static_cast<size_t>(bufferSize));
		device.unmapMemory(stagingIndexBufferMemory);

		BufferUtils::CreateBuffer(device, physicalDevice, bufferSize,
			vk::BufferUsageFlagBits::eIndexBuffer | vk::BufferUsageFlagBits::eTransferDst, vk::MemoryPropertyFlagBits::eDeviceLocal,
			indexBuffer, indexBufferMemory);

		BufferUtils::CopyBuffer(device, commandPool, graphicsQueue, stagingIndexBuffer, indexBuffer, bufferSize);

		device.destroyBuffer(stagingIndexBuffer);
		device.freeMemory(stagingIndexBufferMemory);
	}
}

void Mesh::Cleanup()
{
	if (device)
	{
		if (vertexBuffer)
		{
			device.destroyBuffer(vertexBuffer);
			device.freeMemory(vertexBufferMemory);
			vertexBuffer = nullptr;
			vertexBufferMemory = nullptr;
		}

		if (indexBuffer)
		{
			device.destroyBuffer(indexBuffer);
			device.freeMemory(indexBufferMemory);
			indexBuffer = nullptr;
			indexBufferMemory = nullptr;
		}
	}
}

