#include <stdbool.h>

typedef struct _process_node {
    unsigned long pid;
    unsigned long ppid;
    bool defunct;
    struct _process_node *next;
} process_node;

process_node* build_process_tree(process_node *root, unsigned long pid, unsigned long ppid, bool defunct);
void add_child(process_node *parent, unsigned long pid, unsigned long ppid, bool defunct);
void free_process_tree(process_node *root);
bool process_in_tree(process_node *root, unsigned long pid);
process_node* find_process(process_node *root, unsigned long pid);
void print_info(process_node *root, unsigned long target_pid, const char *option);
bool is_defunct(process_node *process);

int main(int argc, char *argv[]) {
    if(argc < 3) {
        fprintf(stderr, "Usage: prcinfo [root_process] [process_id1] [process_id2]... [process_id(n)] [OPTION]\n");
        return 1;
    }

    process_node *root = NULL;
    DIR *proc_dir;
    struct dirent *dir;
    FILE *fp;
    unsigned long pid, ppid;
    bool defunct;
    char status, buffer[128];

    proc_dir = opendir("/proc");
    if(proc_dir == NULL) {
        perror("Cannot open /proc directory");
        return 1;
    }

    while((dir = readdir(proc_dir)) != NULL) {
        pid = strtoul(dir->d_name, NULL, 10);
        snprintf(buffer, sizeof(buffer), "/proc/%lu/status", pid);
        fp = fopen(buffer, "r");
        if (fp != NULL) {
            defunct = false;
            while(fscanf(fp, "%s", buffer) != EOF) {
                if(strcmp(buffer, "PPid:") == 0) {
                    fscanf(fp, "%lu", &ppid);
                } else if(strcmp(buffer, "State:") == 0) {
                    fscanf(fp, " %c", &status);
                    if(status == 'Z') {
                        defunct = true;
                    }
                }
            }
            root = build_process_tree(root, pid, ppid, defunct);
            fclose(fp);
        }
    }
    closedir(proc_dir);

    if(!process_in_tree(root, strtoul(argv[1], NULL, 10))) {
        printf("Invalid root process.\n");
    } else {
        for(int i = 2; i < argc - 1; i++) {
            if(process_in_tree(root, strtoul(argv[i], NULL, 10))) {
                print_info(root, strtoul(argv[i], NULL, 10), argv[argc-1]);
            } else {
                printf("Process %lu does not belong to the tree rooted at %s.\n", strtoul(argv[i], NULL, 10), argv[1]);
            }
        }
    }
    free_process_tree(root);
    return 0;
}

process_node* build_process_tree(process_node *root, unsigned long pid, unsigned long ppid, bool defunct) {
    if(root == NULL) {
        root = (process_node*) malloc(sizeof(process_node));
        root->pid = pid;
        root->ppid = ppid;
        root->defunct = defunct;
        root->next = NULL;
    } else {
        add_child(root, pid, ppid, defunct);
    }
    return root;
}

void add_child(process_node *parent, unsigned long pid, unsigned long ppid, bool defunct) {
    if(parent->pid == ppid) {
        process_node *child = (process_node*) malloc(sizeof(process_node));
        child->pid = pid;
        child->ppid = ppid;
        child->defunct = defunct;
        child->next = parent->next;
        parent->next = child;
    } else if(parent->next != NULL) {
        add_child(parent->next, pid, ppid, defunct);
    }
}

void free_process_tree(process_node *root) {
    if(root == NULL)
        return;
    free_process_tree(root->next);
    free(root);
}

bool process_in_tree(process_node *root, unsigned long pid) {
    if(root == NULL)
        return false;
    if(root->pid == pid)
        return true;
    return process_in_tree(root->next, pid);
}

process_node* find_process(process_node *root, unsigned long pid) {
    if(root->pid == pid)
        return root;
    if(root->next != NULL)
        return find_process(root->next, pid);
    return NULL;
}

void print_info(process_node *root, unsigned long target_pid, const char *option) {
    process_node *target = find_process(root, target_pid);
    if(target == NULL) {
        return;
    }
    printf("PID: %lu, PPID: %lu\n", target->pid, target->ppid);
    if(strcmp(option, "-nd") == 0) {
        // TODO: Print non-direct descendants
    } else if(strcmp(option, "-dd") == 0) {
        // TODO: Print immediate descendants
    } else if(strcmp(option, "-sb") == 0) {
        // TODO: Print sibling processes
    } else if(strcmp(option, "-sz") == 0) {
        // TODO: Print defunct siblings
    } else if(strcmp(option, "-gc") == 0) {
        //TODO: Print grandchildren
    } else if(strcmp(option, "-zz") == 0) {
        printf("Status: %s\n", is_defunct(target) ? "Defunct" : "Not Defunct");
    } else if(strcmp(option, "-zc") == 0) {
        // TODO: Print defunct direct descendants
    }
}

bool is_defunct(process_node *process) {
    return process->defunct;
}
