// Define a structure for process nodes
typedef struct ProcessNode {
    unsigned long pid;
    unsigned long ppid;
    int isDefunct;
    struct ProcessNode *next;
} ProcessNode;

// Function prototypes
ProcessNode *create_process(unsigned long pid, unsigned long ppid, int isDefunct);
void insert_process(ProcessNode **head, ProcessNode *new_process);
void read_processes(ProcessNode **head);
int process_exists(ProcessNode *head, unsigned long pid);
ProcessNode *get_process(ProcessNode *head, unsigned long pid);

// Main function
int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: prcinfo [root_process] [process_id1] [process_id2]... [process_id(n)] [OPTION]\n");
        return 1;
    }

    ProcessNode *head = NULL;

    read_processes(&head);

    for (int i = 2; i < argc - 1; i++) {
        if (process_exists(head, strtoul(argv[i], NULL, 10))) {
            ProcessNode *process = get_process(head, strtoul(argv[i], NULL, 10));
            printf("PID: %lu, PPID: %lu\n", process->pid, process->ppid);
            // Here you can call the functions for each option (e.g., print_siblings, print_descendants, etc.)
        } else {
            printf("Process %lu does not belong to the process tree.\n", strtoul(argv[i], NULL, 10));
        }
    }

    return 0;
}

// Function to create a process node
ProcessNode *create_process(unsigned long pid, unsigned long ppid, int isDefunct) {
    ProcessNode *process = malloc(sizeof(ProcessNode));
    process->pid = pid;
    process->ppid = ppid;
    process->isDefunct = isDefunct;
    process->next = NULL;
    return process;
}

// Function to insert a process node into the process list
void insert_process(ProcessNode **head, ProcessNode *new_process) {
    new_process->next = *head;
    *head = new_process;
}

// Function to read process information from the /proc directory
void read_processes(ProcessNode **head) {
    DIR *proc_dir;
    struct dirent *dir;
    FILE *fp;
    unsigned long pid, ppid;
    int isDefunct;
    char status, buffer[128];

    proc_dir = opendir("/proc");

    if (proc_dir == NULL) {
        perror("Cannot open /proc directory");
        return;
    }

    while ((dir = readdir(proc_dir)) != NULL) {
        pid = strtoul(dir->d_name, NULL, 10);

        snprintf(buffer, sizeof(buffer), "/proc/%lu/status", pid);
        fp = fopen(buffer, "r");
        if (fp != NULL) {
            isDefunct = 0;
            while (fscanf(fp, "%s", buffer) != EOF) {
                if (strcmp(buffer, "PPid:") == 0) {
                    fscanf(fp, "%lu", &ppid);
                } else if (strcmp(buffer, "State:") == 0) {
                    fscanf(fp, " %c", &status);
                    if (status == 'Z') {
                        isDefunct = 1;
                    }
                }
            }
            ProcessNode *new_process = create_process(pid, ppid, isDefunct);
            insert_process(head, new_process);
            fclose(fp);
        }
    }

    closedir(proc_dir);
}

// Function to check if a process exists in the process list
