    ProcessNode *current = head;
    printf("Descendants of PID %lu:\n", pid);
    while (current != NULL) {
        if ((!only_direct && process_exists(head, current->ppid)) || current->ppid == pid) {
            printf("%lu ", current->pid);
        }
        current = current->next;
    }
    printf("\n");
}

