    ProcessNode *current = get_process(head, pid);
    if (current == NULL) {
        printf("Process %lu not found.\n", pid);
        return;
    }

    unsigned long ppid = current->ppid;
    current = head;
    printf("Siblings of PID %lu:\n", pid);
    while (current != NULL) {
        if (current->ppid == ppid && current->pid != pid) {
            printf("%lu ", current->pid);
        }
        current = current->next;
