У меня есть такой метод и событие, заблокирует ли вызов ActivePlanChanged?.Invoke(this, plan); дальнейшее выполнение метода до выполнения всех методов-подписчиков??

Да, вызов `ActivePlanChanged?.Invoke(this, plan);` будет синхронно (последовательно) вызывать все методы-подписчики, зарегистрированные на это событие. Дальнейшее выполнение этого метода будет блокировано до тех пор, пока не закончится выполнение всех методов-подписчиков.

Если вам нужно выполнить операции с методами-подписчиками асинхронно, можете использовать следующий подход с использованием Task.Run():

```csharp
if (ActivePlanChanged != null)
{
    var subscribers = ActivePlanChanged.GetInvocationList();
    var tasks = subscribers.Select(subscriber => Task.Run(() => subscriber.DynamicInvoke(this, plan))).ToArray();
    await Task.WhenAll(tasks);
}
```

Это вызовет все подписанные методы асинхронно и дождется их окончания выполнения.

To demonstrate the process of migrating from DirectX 9 to DirectX 11, I will show parts of a sample code that creates a window and initializes DirectX 9 and 11. I will not cover all the details but focus on the significant changes in the initialization process.

First, let's look a code snippet with DirectX 9:

```cpp
#include <d3d9.h>

LPDIRECT3D9             g_pD3D = NULL;
LPDIRECT3DDEVICE9       g_pd3dDevice = NULL;

bool InitDX9(HWND hWnd)
{
    if( NULL == ( g_pD3D = Direct3DCreate9( D3D_SDK_VERSION ) ) )
        return false;

    D3DPRESENT_PARAMETERS d3dpp;
    ZeroMemory( &d3dpp, sizeof(d3dpp) );
    d3dpp.Windowed = TRUE;
    d3dpp.SwapEffect = D3DSWAPEFFECT_DISCARD;
    d3dpp.BackBufferFormat = D3DFMT_UNKNOWN;

    if( FAILED( g_pD3D->CreateDevice( D3DADAPTER_DEFAULT, D3DDEVTYPE_HAL, hWnd,
                                      D3DCREATE_HARDWARE_VERTEXPROCESSING,
                                      &d3dpp, &g_pd3dDevice ) ) )
    {
        return false;
    }

    return true;
}

void CleanupDX9()
{
    if(g_pd3dDevice) g_pd3dDevice->Release();
    if(g_pD3D) g_pD3D->Release();
}
```

Now, let's migrate it to DirectX 11:

```cpp
#include <d3d11.h>

ID3D11Device*           g_pd3dDevice = NULL;
ID3D11DeviceContext*    g_pd3dDeviceContext = NULL;
IDXGISwapChain*         g_pSwapChain = NULL;

bool InitDX11(HWND hWnd)
{
    DXGI_SWAP_CHAIN_DESC sd;
    ZeroMemory( &sd, sizeof(sd) );
    sd.BufferCount = 1;
    sd.BufferDesc.Width = 800;
    sd.BufferDesc.Height = 600;
    sd.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    sd.BufferDesc.RefreshRate.Numerator = 60;
    sd.BufferDesc.RefreshRate.Denominator = 1;
    sd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    sd.OutputWindow = hWnd;
    sd.SampleDesc.Count = 1;
    sd.SampleDesc.Quality = 0;
    sd.Windowed = TRUE;

    D3D_FEATURE_LEVEL FeatureLevelsRequested = D3D_FEATURE_LEVEL_11_0;
    uint32_t numFeatureLevelsRequested = 1;
    D3D_FEATURE_LEVEL FeatureLevelsSupported;

    if(FAILED(D3D11CreateDeviceAndSwapChain(NULL, D3D_DRIVER_TYPE_HARDWARE, NULL, 0, &FeatureLevelsRequested, 
        numFeatureLevelsRequested, D3D11_SDK_VERSION, &sd, &g_pSwapChain, &g_pd3dDevice, &FeatureLevelsSupported, &g_pd3dDeviceContext)))
    {
        return false;
    }

    return true;
}

void CleanupDX11()
{
    if(g_pSwapChain) g_pSwapChain->Release();
    if(g_pd3dDeviceContext) g_pd3dDeviceContext->Release();
    if(g_pd3dDevice) g_pd3dDevice->Release();
