function createBtn(element) {
  const listItems = Array.from(element.getElementsByTagName('li'));

  listItems.forEach(item => {
    const { width: elmWidth } = item.getBoundingClientRect();
    const listType = element.getAttribute('data-inset') !== null;
    const btnWidth = elmWidth < 300 && listType ? '35%' : elmWidth > 300 && !listType ? '25%' : '20%';

    const wrapper = document.createElement('div');
    wrapper.className = 'wrapper';

    const go = document.createElement('div');
    go.className = 'go';
    go.innerText = 'Save';
    go.style.width = btnWidth;

    const itemWrapper = document.createElement('div');
    itemWrapper.className = 'item';
    itemWrapper.innerText = item.innerText;

    const del = document.createElement('div');
    del.className = 'del';
    del.innerText = 'Delete';
    del.style.width = btnWidth;

    wrapper.appendChild(go);
    wrapper.appendChild(itemWrapper);
    wrapper.appendChild(del);
    item.appendChild(wrapper);
    item.style.left = `-${btnWidth}`;

    item.addEventListener('swipeleft', e => {
      revealBtn(e, item, btnWidth);
    });
    item.addEventListener('swiperight', e => {
      revealBtn(e, item, btnWidth);
    });
    item.addEventListener('vclick', e => {
      revealBtn(e, item, btnWidth);
    });
    item.addEventListener('tap', e => {
      revealBtn(e, item, btnWidth);
    });
  });
}

function revealBtn(event, item, btnWidth) {
  const check = checkPosition(item, btnWidth);
  const swipe = event.type;

  if (check === 'closed') {
    if (swipe === 'swiperight') {
      open(item, btnWidth, 'left');
    } else if (swipe === 'swipeleft') {
      open(item, btnWidth, 'right');
    } else {
      setTimeout(() => {
        close(item);
      }, 0);
    }
    event.stopImmediatePropagation();
  }

  if (check === 'right' || check === 'left') {
    if (swipe === 'swiperight') {
      open(item, btnWidth, 'left');
    } else if (swipe === 'swipeleft') {
      open(item, btnWidth, 'right');
    } else {
      setTimeout(() => {
        close(item);
      }, 0);
    }
    event.stopImmediatePropagation();
  }

  if (check !== 'closed' && event.isImmediatePropagationStopped() && (swipe === 'vclick' || swipe === 'tap')) {
    close(item);
  }
}

function close(item) {
  item.style.transform = 'translateX(0)';
}

function open(item, btnWidth, dir) {
  const posX = dir === 'left' ? btnWidth : `-${btnWidth}`;
  item.style.transform = `translateX(${posX})`;
}

function checkPosition(item, btnWidth) {
  const matrix = getComputedStyle(item).transform.split(' ');
  const posY = parseInt(matrix[matrix.length - 2], 10);
  const btnW = (item.offsetWidth * parseInt(btnWidth, 10)) / 100 / 1.1;

  if (isNaN(posY)) {
    return 'closed';
  }

  if (posY >= btnW) {
    return 'left';
  }

  if (posY <= `-${btnW}`) {
    return 'right';
  }

  return 'closed';
}

window.addEventListener('load', () => {
  const lists = Array.from(document.getElementsByTagName('ul'));
  lists.forEach(list => createBtn(list));
});
