public bool Create(IntPtr hInst, IntPtr hParent, uint uCallbackMessage, string szToolTip, IntPtr icon, uint uID, bool bHidden = false, string szBalloonTip = null, string szBalloonTitle = null, uint dwBalloonIcon = NIIF_NONE, uint uBalloonTimeout = 10)
{
    bool m_bEnabled;
    bool m_bHidden;
    bool m_bShowIconPending;
    bool m_bRemoved;
    int m_nMaxTooltipLength;
    IntPtr m_hInstance;
    IntPtr m_hWnd;
    IntPtr m_hTargetWnd;
    uint m_uCreationFlags;

    if (System.Environment.OSVersion.Platform == PlatformID.Win32NT)
    {
        m_bEnabled = true;
    }
    else
    {
        m_bEnabled = (System.Environment.OSVersion.Version.Major >= 4);
        if (!m_bEnabled) 
        {
            Debug.Assert(false);
            return false;
        }
    }

    m_nMaxTooltipLength = Marshal.SizeOf(new NOTIFYICONDATA().szTip) - 1;

    Debug.Assert(uCallbackMessage >= WM_APP);

    Debug.Assert(szToolTip.Length <= m_nMaxTooltipLength);

    m_hInstance = hInst;

    RegisterClass();

    m_hWnd = NativeMethods.CreateWindow(TRAYICON_CLASS, "", WS_POPUP, CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT, null, IntPtr.Zero, hInst, IntPtr.Zero);

    NOTIFYICONDATA m_tnd = new NOTIFYICONDATA();
    m_tnd.cbSize = NotifyIconDataSize.GETNOTIFYICONDATA_V2_SIZE();  // 2012-01-05 GONG Chen, XP compatibility
    m_tnd.hWnd = (hParent != IntPtr.Zero) ? hParent : m_hWnd;
    m_tnd.uID = uID;
    m_tnd.hIcon = icon;
    m_tnd.uFlags = NIF_MESSAGE | NIF_ICON | NIF_TIP;
    m_tnd.uCallbackMessage = uCallbackMessage;

    // 2007-11-14 GONG
    m_tnd.szTip = szToolTip.Substring(0, Math.Min(szToolTip.Length, m_nMaxTooltipLength));

    if (System.Environment.OSVersion.Version.Major >= 5 && szBalloonTip != null)
    {
        if (szBalloonTip.Length > 255)
            Debug.Assert(false);

        if (szBalloonTitle != null && szBalloonTitle.Length > 63)
            Debug.Assert(false);

        Debug.Assert(dwBalloonIcon == NIIF_NONE || dwBalloonIcon == NIIF_INFO || dwBalloonIcon == NIIF_WARNING || dwBalloonIcon == NIIF_ERROR);

        Debug.Assert(uBalloonTimeout >= 10 && uBalloonTimeout <= 30);

        m_tnd.uFlags |= NIF_INFO;

        m_tnd.szInfo = szBalloonTip.Substring(0, Math.Min(szBalloonTip.Length, 255));
        if (szBalloonTitle != null)
            m_tnd.szInfoTitle = szBalloonTitle.Substring(0, Math.Min(szBalloonTitle.Length, 63));
        else
            m_tnd.szInfoTitle = "";

        m_tnd.uTimeout = uBalloonTimeout * 1000;
        m_tnd.dwInfoFlags = dwBalloonIcon;
    }

    m_bHidden = bHidden;
    m_hTargetWnd = m_tnd.hWnd;

    if (System.Environment.OSVersion.Version.Major >= 5 && m_bHidden)
    {
        m_tnd.uFlags = NIF_STATE;
        m_tnd.dwState = NIS_HIDDEN;
        m_tnd.dwStateMask = NIS_HIDDEN;
    }

    bool bResult = true;
    if (!m_bHidden || System.Environment.OSVersion.Version.Major >= 5)
    {
        bResult = NativeMethods.Shell_NotifyIcon(NIM_ADD, ref m_tnd);
        m_bShowIconPending = m_bHidden = m_bRemoved = !bResult;
    }

    if (System.Environment.OSVersion.Version.Major >= 5 && szBalloonTip != null)
    {
        m_tnd.szInfo = "";
    }

    return bResult;
}

