// Define the Sudoku grid
let board = [
  [0,0,0,0,0,9,2,0,0],
  [0,0,0,5,0,0,0,9,0],
  [6,0,7,0,0,2,0,0,5],
  [0,0,0,0,3,0,0,0,0],
