  }

Statements are the building blocks of a program, and are executed one after the other in a specific order. They can be combined with expressions to create more complex operations.

The type of the array passed to a `vararg` parameter must match the expected type of the `vararg` parameter. For example, if you have a `vararg` parameter of type `String`, you can only pass an array of `String` values to that parameter.

So, if your function takes a `vararg` parameter of type `Int`, you can only pass an `IntArray` or a comma-separated list of `Int` arguments to that function. If you try to pass a `String` array to that parameter, you will get a compile-time error.

Here's an example:

```kotlin
fun printNumbers(vararg numbers: Int) {
    for (number in numbers) {
        println(number)
    }
}

fun printStrings(vararg strings: String) {
    for (string in strings) {
        println(string)
    }
}
```

In this example, the `printNumbers` function takes a `vararg` parameter of type `Int`, while the `printStrings` function takes a `vararg` parameter of type `String`. You can only pass an `IntArray` to the `printNumbers` function, and only a `Array<String>` to the `printStrings` function.

However, you could also use the `Any` type for the `vararg` parameter if you want to allow any type of argument to be passed. This way you don't need to know the expected type in advance. For example:

```kotlin
fun printValues(vararg values: Any) {
    for (value in values) {
        println(value)
    }
}
```

In this example, the `printValues` function takes a `vararg` parameter of type `Any`, which means any type of argument can be passed to this function. When you use `Any` as the type for the `vararg` parameter, you will be able to pass arguments of different types to the function.

#include "kdmapper.hpp"

HANDLE iqvw64e_device_handle;

LONG WINAPI SimplestCrashHandler(EXCEPTION_POINTERS* ExceptionInfo)
{
	if (ExceptionInfo && ExceptionInfo->ExceptionRecord)
		Log(L"[!!] Crash at addr 0x" << ExceptionInfo->ExceptionRecord->ExceptionAddress << L" by 0x" << std::hex << ExceptionInfo->ExceptionRecord->ExceptionCode << std::endl);
	else
		Log(L"[!!] Crash" << std::endl);

	if (iqvw64e_device_handle)
		intel_driver::Unload(iqvw64e_device_handle);

	return EXCEPTION_EXECUTE_HANDLER;
}

int paramExists(const int argc, wchar_t** argv, const wchar_t* param) {
	size_t plen = wcslen(param);
	for (int i = 1; i < argc; i++) {
		if (wcslen(argv[i]) == plen + 1ull && _wcsicmp(&argv[i][1], param) == 0 && argv[i][0] == '/') { // with slash
			return i;
		}
		else if (wcslen(argv[i]) == plen + 2ull && _wcsicmp(&argv[i][2], param) == 0 && argv[i][0] == '-' && argv[i][1] == '-') { // with double dash
			return i;
		}
	}
	return -1;
}

void help() {
	Log(L"\r\n\r\n[!] Incorrect Usage!" << std::endl);
	Log(L"[+] Usage: kdmapper.exe [--free][--mdl][--PassAllocationPtr] driver" << std::endl);
}

bool callbackExample(ULONG64* param1, ULONG64* param2, ULONG64 allocationPtr, ULONG64 allocationSize, ULONG64 mdlptr) {
	UNREFERENCED_PARAMETER(param1);
	UNREFERENCED_PARAMETER(param2);
	UNREFERENCED_PARAMETER(allocationPtr);
	UNREFERENCED_PARAMETER(allocationSize);
	UNREFERENCED_PARAMETER(mdlptr);
	Log("[+] Callback example called" << std::endl);

	/*
	This callback occurs before call driver entry and
	can be usefull to pass more customized params in 
	the last step of the mapping procedure since you 
	know now the mapping address and other things
	*/
	return true;
}

int wmain(const int argc, wchar_t** argv) {
	SetUnhandledExceptionFilter(SimplestCrashHandler);

	bool free = paramExists(argc, argv, L"free") > 0;
	bool mdlMode = paramExists(argc, argv, L"mdl") > 0;
	bool passAllocationPtr = paramExists(argc, argv, L"PassAllocationPtr") > 0;

	if (free) {
		Log(L"[+] Free pool memory after usage enabled" << std::endl);
	}

	if (mdlMode) {
		Log(L"[+] Mdl memory usage enabled" << std::endl);
	}

	if (passAllocationPtr) {
