В случае использования прерываний, вы можете убрать задержки в функции loop(). Вместо этого, заполните буфер, переключитесь на другой буфер и отправьте первый буфер в I2S.

Пример кода с прерываниями выглядит следующим образом:

```cpp
#include <soc/rtc.h>
#include "driver/i2s.h"

#define SAMPLE_RATE 2000000
#define BUFFER_SIZE 512
static const i2s_port_t i2s_num = (i2s_port_t)0; // i2s port number
static bool buffer_ready = false; // флаг готовности буфера

static const i2s_config_t i2s_config = {
  .mode = (i2s_mode_t)(I2S_MODE_MASTER | I2S_MODE_TX),
  .sample_rate = SAMPLE_RATE,
  .bits_per_sample = I2S_BITS_PER_SAMPLE_16BIT,
  .channel_format = I2S_CHANNEL_FMT_RIGHT_LEFT,
  .communication_format = I2S_COMM_FORMAT_I2S_MSB,
  .intr_alloc_flags = ESP_INTR_FLAG_LEVEL1,
  .dma_buf_count = 2,
  .dma_buf_len = BUFFER_SIZE * 2,
  .tx_desc_auto_clear = true,
  .use_apll = false
};

static intr_handle_t i2s_isr_handler;

void IRAM_ATTR i2s_isr(void *arg) {
  BaseType_t higher_priority_task_woken = pdFALSE;
  buffer_ready = true; // устанавливаем флаг готовности буфера
  i2s_clear_intr_status(i2s_num, I2S_TX_DSCR_EMPTY_INT_CLR_V); // очищаем флаг прерывания
  xTaskNotifyFromISR(NULL, 0, eNoAction, &higher_priority_task_woken); // уведомляем задачу
  if (higher_priority_task_woken)
    portYIELD_FROM_ISR();
}

void fill_buffer(uint8_t *buffer, size_t buffer_size) {
  for (size_t i = 0; i < buffer_size; i++) {
    if (i % 2 == 0)
      buffer[i] = 0x01; // генерируем сигнал '0 1'
    else
      buffer[i] = 0xFFFF;
  }
}

void setup() {
  i2s_driver_install(i2s_num, &i2s_config, 0, NULL); // запускаем драйвер i2s
  i2s_set_pin(i2s_num, NULL); // используем встроенный ЦАП

  // настраиваем прерывание на событие I2S_TX_DSCR_EMPTY_INT
  esp_intr_alloc(ETS_I2S0_INTR_SOURCE, ESP_INTR_FLAG_LEVEL1, i2s_isr, NULL, &i2s_isr_handler);
  esp_intr_enable(i2s_isr_handler);
}

void loop() {
  static uint8_t buffer1[BUFFER_SIZE];
  static uint8_t buffer2[BUFFER_SIZE];

  if (buffer_ready) { // если буфер готов, заполняем его и отправляем в I2S
    buffer_ready = false; // сбрасываем флаг готовности буфера
    fill_buffer(buffer1, BUFFER_SIZE);
    i2s_set_sample_rates(i2s_num, SAMPLE_RATE);
    i2s_write(i2s_num, buffer1, BUFFER_SIZE, NULL, portMAX_DELAY); // отправляем данные в I2S
    xTaskNotifyWait(0, 0, NULL, portMAX_DELAY); // ждем уведомления перед заполнением следующего буфера
    fill_buffer(buffer2, BUFFER_SIZE);
    i2s_set_sample_rates(i2s_num, SAMPLE_RATE);
    i2s_write(i2s_num, buffer2, BUFFER_SIZE, NULL, portMAX_DELAY); // отправляем данные в I2S
    xTaskNotifyWait(0, 0, NULL, portMAX_DELAY); // ждем уведомления перед заполнением следующего буфера
  }
}
```

Здесь используется прерывание I2S_TX_DSCR_EMPTY_INT, чтобы оповестить задачу о том, что один из буферов доступен для заполнения и отправки в I2S. После заполнения первого буфера, задача ждет уведомления о готовности второго буфера. В этот момент задача заполняет второй буфер и отправляет его в I2S. Процесс повторяется по кругу. 

Таким образом, вы можете убрать задержки в функции loop() и использовать прерывания для более эффективной работы с I2S.

