这些打印信息与`__hrtimer_start_range_ns()`函数有关。下面是`__hrtimer_start_range_ns()`函数的源代码（Linux 3.14.01.0.10-xilinx版本）：

```c
static inline void __hrtimer_start_range_ns(struct hrtimer *timer,
            ktime_t tim, const enum hrtimer_mode mode)
{
    struct hrtimer_clock_base *base;
    unsigned long flags;
    u64 expires;
    s64 delta;

    base = lock_hrtimer_base(timer);
    spin_lock_irqsave(&base->lock, flags);
    if (hrtimer_is_queued(timer)) {
        BUG_ON(timer->base != base);
        delta = __hrtimer_get_delta(timer);
        /*
         * If the timer had already expired and is still on the
         * clock's queue, we must first remove it before updating
         * expires. Otherwise, the timer can expire twice.
         */
        if (hrtimer_active(timer)) {
            struct tick_sched *ts = &__get_cpu_var(tick_cpu_sched);
            struct task_struct *curr = current;
            /*
             * If it is the current softirq context and the timer
             * was armed by the same context, we must not try to
             * remove it now because it will deadlock.
             * It will be done later on.
             */
            if (ts && atomic_read(&ts->inidle) == 0 &&
                    !((unsigned long)curr->journal_info & 1UL)) {
                /*
                 * If queued from task context we drop the
                 * lock to avoid lock inversion problems from
                 * the ->dequeue nesting.
                 */
                if (in_task())
                    spin_unlock_irqrestore(&base->lock, flags);
                /*
                 * Timer can't expire until it's reactivated
                 * But we'll test again in case an interrupt
                 * delivered after the end of tick woke us up.
                 */
                if (hrtimer_active(timer)) {
                    hrtimer_dequeue(timer);
                    if (in_task())
                        spin_lock_irqsave(&base->lock, flags);
                }
            } else {
                hrtimer_dequeue(timer);
            }
        }
        hrtimer_get_expires(timer, &expires);
        expires = ktime_to_ns(tim) + expires - timer->node.expires;
        hrtimer_set_expires(timer, expires);
        if (!(base->cpu_base->active_bases & HRTIMER_BASE_ACTIVE(timer->base)))
            hrtimer_set_mode(timer, mode);
        else
            __hrtimer_reprogram(timer, mode);
        if (hrtimer_callback_running(timer) &&
                base->next_timer && hrtimer_is_hres(base->next_timer) &&
                hrtimer_get_expires(timer, &expires) &&
                ktime_before(timer->node.expires,
                     ktime_sub(expires, base->cpu_base->resolution)))
            hrtimer_switch_to_hres();
        spin_unlock_irqrestore(&base->lock, flags);
        if (in_task())
            hrtimer_try_to_cancel(timer);
    } else {
        hrtimer_start_timer(timer, tim, mode);
        spin_unlock_irqrestore(&base->lock, flags);
    }
}
```

