typedef enum {
    ERROR_NONE = 0,
    ERROR_FILE_READ,
    ERROR_FILE_WRITE,
    ERROR_INVALID_ARGUMENTS
} ErrorCode;

typedef struct {
    ErrorCode code;
    char *message;
} Error;

Error create_error(ErrorCode code, const char *message) {
    Error error;
    error.code = code;
    error.message = malloc(strlen(message) + 1);
    if (error.message != NULL) {
        strcpy(error.message, message);
    }
    return error;
}

void free_error(Error *error) {
