  for (let i = 0; i < expandedWords.length; i++) {
    if (expandedWords[i] === originalWords[originalIndex]) {
      mapping.push(originalIndex);
      originalIndex++;
    } else {
      mapping.push(originalIndex - 1);
    }
  }
  return mapping;
}

