int main() {
    int n, cnt = 0;
    cin >> n;

    bool is_prime[2*n+1];
    fill(is_prime+2, is_prime+2*n+1, true);

    for (int i = 2; i*i <= 2*n; i++) {
        if (is_prime[i]) {
            for (int j = i*i; j <= 2*n; j += i) {
                is_prime[j] = false;
            }
        }
    }

    for (int i = n+1; i <= 2*n; i++) {
        if (is_prime[i]) {
            cnt++;
        }
    }

    cout << cnt << endl;

    return 0;
}
``` 

