#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct node
{
    int size;
    int start;
    int end;
    int status; // Status of the block (0 for free, 1 for allocated)
    struct node *next;
};

struct node *head = NULL; // Head of the linked list

void insert(int size)
{
    struct node *temp = (struct node *)malloc(sizeof(struct node)); // Allocate memory for a new node
    temp->size = size; // Set the size of the new block
    temp->start = 0; // Set the starting address of the new block
    temp->end = size - 1; // Set the ending address of the new block
    temp->status = 0; // Set the status of the new block to free
    temp->next = NULL; // Set the next pointer of the new block to NULL

    if (head == NULL) // If the linked list is empty
    {
        head = temp; // Set the new node as the head of the list
    }
    else // If the linked list is not empty
    {
        struct node *p = head; // Create a pointer to traverse the list
        while (p->next != NULL) // Traverse the list until the end is reached
        {
            p = p->next;
        }
        p->next = temp; // Add the new node to the end of the list
    }
}

void display()
{
    struct node *p = head; // Create a pointer to traverse the list
    while (p != NULL) // Traverse the list until the end is reached
    {
        printf("%d\t%d\t%d\t%d\n", p->size, p->start, p->end, p->status); // Print the information for the current node
        p = p->next; // Move to the next node
    }
}

void best_fit(int size)
{
    struct node *p = head; // Create a pointer to traverse the list
    int min = 9999; // Set an initial value for the minimum block size
    struct node *temp = NULL; // Create a temporary pointer to store the best-fit block
    while (p != NULL) // Traverse the list until the end is reached
    {
        if (p->status == 0 && p->size >= size) // If the current block is free and large enough to fit the process
        {
            if (p->size < min) // If the current block is smaller than the current minimum
            {
                min = p->size; // Update the minimum block size
                temp = p; // Set the best-fit block to the current block
            }
        }
        p = p->next; // Move to the next block
    }
    if (temp != NULL) // If a best-fit block was found
    {
        temp->status = 1; // Set the status of the best-fit block to allocated
        printf("Allocated memory of size %d at %d\n", size, temp->start); // Print the allocation message
    }
    else // If no best-fit block was found
    {
        printf("No memory available\n"); // Print the error message
    }
}

int main()
{
    int n, size;
    printf("Enter the number of memory blocks: ");
    scanf("%d", &n); // Read in the number of memory blocks
    printf("Enter the size of each block: ");
    for (int i = 0; i < n; i++) // Loop through each memory block
