}

func createToken(value string) (Token, error) {
	if _, err := strconv.ParseFloat(value, 64); err == nil {
		return Token{Type: Number, Value: value}, nil
	}

	if _, ok := variables[value]; ok {
		return Token{Type: Variable, Value: value}, nil
	}

	if value == "root" {
		return Token{Type: Function, Value: value}, nil
	}

	return Token{}, fmt.Errorf("неизвестный токен: %s", value)
}

type Parser struct {
	tokens       []Token
	currentToken int
}

func (p *Parser) Parse() (float64, error) {
	result, err := p.parseExpression(0)
	if err != nil {
		return 0, err
	}
	return result, nil
}

func (p *Parser) parseExpression(precedence int) (float64, error) {
	left, err := p.parsePrimary()
	if err != nil {
		return 0, err
	}

	for {
		operator := p.peekToken()
		if operator.Type != Operator || precedence >= getPrecedence(operator.Value) {
			break
		}

		p.nextToken()

		right, err := p.parseExpression(getPrecedence(operator.Value) + 1)
		if err != nil {
			return 0, err
		}

		switch operator.Value {
		case "+":
			left += right
		case "-":
			left -= right
		case "":
			left *= right
		case "/":
			left /= right
		case "^":
			left = math.Pow(left, right)
		default:
			return 0, fmt.Errorf("unexpected operator: %s", operator.Value)
		}
	}

	return left, nil
}

func (p *Parser) parsePrimary() (float64, error) {
	token := p.peekToken()

	switch token.Type {
	case Number:
		p.nextToken()
		value, _ := strconv.ParseFloat(token.Value, 64)
		return value, nil
	case Variable:
		p.nextToken()
		value := variables[token.Value]
		return value, nil
	case Operator:
		if token.Value == "(" {
			p.nextToken()
			value, err := p.parseExpression(0)
			if err != nil {
				return 0, err
			}
			if p.peekToken().Value != ")" {
				return 0, fmt.Errorf("ожидалась закрывающая скобка")
			}
			p.nextToken()
			return value, nil
		}
	case Function:
		if token.Value == "root" {
			if p.peekToken(1).Value != "(" {
				return 0, fmt.Errorf("ожидалась открывающая скобка")
			}
			p.nextToken()
			p.nextToken()

			base, err := p.parseExpression(0)
			if err != nil {
				return 0, err
			}
			if p.peekToken().Type != ArgumentSeparator {
				return 0, fmt.Errorf("ожидался разделитель аргументов ‘,’")
			}
			p.nextToken()

			exponent, err := p.parseExpression(0)
			if err != nil {
				return 0, err
			}

			if p.peekToken().Value != ")" {
				return 0, fmt.Errorf("ожидалась закрывающая скобка")
			}
			p.nextToken()

			return math.Pow(base, 1/exponent), nil
		}
	default:
		break
	}

	return 0, fmt.Errorf("необработанный токен: %v", token)
}

func (p *Parser) peekToken(n ...int) Token {
	index := p.currentToken
	if len(n) > 0 {
		index += n[0]
	}

	if index < len(p.tokens) {
		return p.tokens[index]
	}
	return Token{}
}

func (p *Parser) nextToken() {
	p.currentToken++
}

func getPrecedence(operator string) int {
	switch operator {
	case "+", "-":
		return 1
	case "", "/":
		return 2
	case "^":
		return 3
	default:
		return 0
	}
}

func main() {
	variables["x"] = 5

	expression := "3 ^ 2 + root(27, 3) + x"

	tokens, err := parseExpression(expression)
	if err != nil {
		fmt.Printf("Ошибка при парсинге выражения: %v\n", err)
		return
	}

	parser := Parser{tokens: tokens}
	result, err := parser.Parse()
	if err != nil {
		fmt.Printf("Ошибка при вычислении выражения: %v\n", err)
	} else {
		fmt.Printf("Результат вычисления: %.4f\n", result)
	}
}
