public boolean getIfMalicious(JsonNode rootNode) {
    JsonNode scanData = rootNode.path("data").path("attributes").path("results");

    int totalAntivirus = 0;
    int detectedMalicious = 0;

    for (Iterator<String> it = scanData.fieldNames(); it.hasNext(); ) {
        String fieldName = it.next();
        JsonNode scanResult = scanData.path(fieldName);

        // If "malicious" field exists, count it as an antivirus that supports the format used.
        if (scanResult.has("malicious")) {
            totalAntivirus++;

            // If malicious, increment detectedMalicious count
            if (!scanResult.path("malicious").isNull()) {
                detectedMalicious++;
            }
        }
    }

    if (totalAntivirus == 0) {
        return false; // No antivirus program supports the format, return false
    }

    double maliciousPercentage = (double) detectedMalicious / totalAntivirus;
    return maliciousPercentage > 0.25;
}
