```java
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

import javax.swing.ImageIcon;
import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;

public class DraggableLabels {
    public static void main(String[] args) {
        JFrame frame = new JFrame("Draggable Labels Example");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(800, 600);
        frame.setLocationRelativeTo(null);

        JPanel panel = new JPanel();
        panel.setLayout(null);
        panel.setBackground(Color.WHITE);

        JLabel label1 = new JLabel(new ImageIcon("path/to/image1.png"));
        label1.setHorizontalAlignment(SwingConstants.CENTER);
        label1.setVerticalAlignment(SwingConstants.CENTER);
        label1.setSize(label1.getPreferredSize());
        label1.setLocation(new Point(100, 100));

        JLabel label2 = new JLabel(new ImageIcon("path/to/image2.png"));
        label2.setHorizontalAlignment(SwingConstants.CENTER);
        label2.setVerticalAlignment(SwingConstants.CENTER);
        label2.setSize(label2.getPreferredSize());
        label2.setLocation(new Point(500, 200));

        panel.add(label1);
        panel.add(label2);

        panel.addMouseListener(new MouseAdapter() {
            public void mousePressed(MouseEvent e) {
                label1.getParent().setComponentZOrder(label1, 0); // Bring label to front
                label2.getParent().setComponentZOrder(label2, 0); // Bring label to front
            }
        });

        panel.addMouseMotionListener(new MouseAdapter() {
            public void mouseDragged(MouseEvent e) {
                label1.setLocation(e.getX() - label1.getWidth() / 2, e.getY() - label1.getHeight() / 2);
                label2.setLocation(e.getX() + label1.getWidth() / 2, e.getY() + label1.getHeight() / 2);
            }
        });

        frame.add(panel);
        frame.setVisible(true);
    }
}
```

