using static Tensorflow.Binding;

namespace TensorFlowNET_DeepLearning
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load MNIST dataset
            var mnist = tf.keras.datasets.mnist.load_data();

            // Preprocess data
            NDArray x_train = mnist.Item1.x_train / 255.0f;
            NDArray y_train = mnist.Item1.y_train;
            NDArray x_test = mnist.Item2.x_test / 255.0f;
            NDArray y_test = mnist.Item2.y_test;

            // Create a deep learning model
            var model = CreateModel();

            // Train the model
            TrainModel(model, x_train, y_train);

            // Evaluate the model
            EvaluateModel(model, x_test, y_test);
        }

        static tensorflow.keras.Sequential CreateModel()
        {
            // Define the layers for the deep learning model
            var model = new tensorflow.keras.Sequential();
            model.add(tf.keras.layers.Dense(128, activation: "relu"));
            model.add(tf.keras.layers.Dropout(0.2f));
            model.add(tf.keras.layers.Dense(10, activation: "softmax"));

            // Compile the model
            model.compile(optimizer: "adam",
                          loss: "sparse_categorical_crossentropy",
                          metrics: new[] { "accuracy" });

            return model;
        }

        static void TrainModel(tensorflow.keras.Sequential model, NDArray x_train, NDArray y_train)
        {
            // Train the model
            model.fit(x_train, y_train, epochs: 5);
