      userReactions.set(userID, [{ name: reaction.emoji.name, count: reaction.count }])
    } else {
      const reactions = userReactions.get(userID)
      reactions.push({ name: reaction.emoji.name, count: reaction.count })
      userReactions.set(userID, reactions)
    }
  })
})

