1. Center the sun:
To center the Sun, we can modify the projectTo2D function to take a position argument and subtract the position of the Sun from the x, y, and z coordinates before projecting to 2D. This will make the sun appear in the center of the canvas.

function projectTo2D(x, y, z, position) {
    const fov = 90; // Field of view angle in degrees
    const distance = canvas.width / 2 / Math.tan(fov / 2 * Math.PI / 180);

    const dx = x - position.x;
    const dy = y - position.y;
    const dz = z - position.z;

    const scale = distance / (distance + dz);
    const x2d = canvas.width / 2 + dx * scale;
    const y2d = canvas.height / 2 - dy * scale;

    return { x: x2d, y: y2d };
}

