                        _ = double.TryParse($"{ba[i + 10]:X2}{ba[i + 9]:X2}{ba[i + 8]:X2}{ba[i + 7]:X2}", out Pokaz);
                        Pokaz /= raw ? 1d : 1000d;
                    }
                }
            }
            else if (ba[i - 1] == 0x0c && (ba[i] == 0x14 || ba[i] == 0x15))
            {
                _ = double.TryParse($"{ba[i + 4]:X2}{ba[i + 3]:X2}{ba[i + 2]:X2}{ba[i + 1]:X2}", out Pokaz);
                Pokaz /= raw ? 1d : 100d;
                i += 19;

                if (ba[i - 1] == 0x0c && ba[i] == 0x78)
                {
                    _ = int.TryParse($"{ba[i + 4]:X2}{ba[i + 3]:X2}{ba[i + 2]:X2}{ba[i + 1]:X2}", out Nakl);
                }
            }

            return new(Nakl, Pokaz);
        }
    }

}
