let elbowL = NSPoint(x: shoulderL.x - imgSize.width * 0.3, y: shoulderL.y - imgSize.height * 0.3)
let elbowR = NSPoint(x: shoulderR.x + imgSize.width * 0.3, y: shoulderR.y - imgSize.height * 0.3)
let handL = NSPoint(x: elbowL.x - imgSize.width * 0.2, y: elbowL.y - imgSize.height * 0.2)
let handR = NSPoint(x: elbowR.x + imgSize.width * 0.2, y: elbowR.y - imgSize.height * 0.2)

// Draw your image at neck joint
