let armL = NSBezierPath()
armL.move(to: neck)
armL.line(to: shoulderL)
armL.line(to: elbowL)
armL.line(to: handL)

let armR = NSBezierPath()
armR.move(to: neck)
armR.line(to: shoulderR)
armR.line(to: elbowR)
armR.line(to: handR)

// Add armature to canvas as NSBezierPath objects
canvas.draw(armL)
canvas.draw(armR)

// Add gesture recognizer to manipulte the armature
let gestureRecognizer = NSPanGestureRecognizer(target: canvas, action: #selector(Canvas.panGesture(sender:)))
canvas.addGestureRecognizer(gestureRecognizer)

// Define function to handle pan gesture for armature
canvas.panGestureHandler = { (translation: NSPoint, velocity: NSPoint, recognizer: NSPanGestureRecognizer) in
    // Calculate new joint positions based on gesture translation
    let neckNew = neck + translation
    let shoulderLNew = shoulderL + translation
    let shoulderRNew = shoulderR + translation
    let elbowLNew = elbowL + translation
    let elbowRNew = elbowR + translation
    let handLNew = handL + translation
    let handRNew = handR + translation

    // Redraw armature and image based on new joint positions
    canvas.clear()
    armL.removeAllPoints()
    armR.removeAllPoints()
    armL.move(to: neckNew)
    armR.move(to: neckNew)
    armL.line(to: shoulderLNew)
    armR.line(to: shoulderRNew)
    armL.line(to: elbowLNew)
    armR.line(to: elbowRNew)
    armL.line(to: handLNew)
    armR.line(to: handRNew)
    canvas.draw(img, at: neckNew, anchorPoint: CGPoint(x: 0.5, y: 0.5))
    canvas.draw(armL)
    canvas.draw(armR)
}
```

