```java
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.Cache;
import org.springframework.cache.CacheManager;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.method.HandlerMethod;
import org.springframework.web.servlet.handler.HandlerInterceptorAdapter;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.time.Duration;
import java.util.concurrent.TimeUnit;

@Component
public class RateLimitingInterceptor extends HandlerInterceptorAdapter {

    private final Cache cache;

    @Autowired
    public RateLimitingInterceptor(CacheManager cacheManager) {
        this.cache = cacheManager.getCache("rateLimitCache");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {
        if (handler instanceof HandlerMethod) {
            HandlerMethod handlerMethod = (HandlerMethod) handler;
            RateLimited rateLimited = handlerMethod.getMethod().getAnnotation(RateLimited.class);

            if (rateLimited != null) {
                String key = request.getMethod() + ":" + request.getRequestURI();
                boolean allowed = cache.get(key) == null;

                if (!allowed) {
                    response.setStatus(HttpStatus.TOO_MANY_REQUESTS.value());
                    response.getWriter().write("Too many requests");

                    return false;
                }

                cache.put(key, key, Duration.ofSeconds(1));
                cache.getNativeCache().expire(key, 1, TimeUnit.SECONDS);
            }
        }

        return true;
    }
}
```

