import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.BlockingBucket;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.ConsumptionProbe;
import io.github.bucket4j.TimeMeter;
import io.github.bucket4j.grid.ProxyManager;
import io.github.bucket4j.grid.RecoveryStrategy;
import io.github.bucket4j.grid.jcache.JCache;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;

import javax.cache.Cache;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.time.Duration;
import java.util.Optional;
import java.util.concurrent.TimeUnit;

@Component
public class RateLimitInterceptor implements HandlerInterceptor {

    private final ProxyManager<String> buckets;
    private final Bucket defaultBucket;

    @Autowired
    public RateLimitInterceptor(Cache<String, Bucket> cache) {
        this.buckets = Bucket4j.extension(JCache.class).proxyManagerForCache(cache);
        this.defaultBucket = Bucket4j.builder()
                .addLimit(Bandwidth.simple(10, Duration.ofMinutes(1)))
                .build();
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {
        String apiKey = request.getHeader("X-API-Key");
        Optional<BlockingBucket> bucket = buckets.getProxy(apiKey);

        Bucket apiBucket = bucket.orElse(defaultBucket);

        ConsumptionProbe probe = apiBucket.tryConsumeAndReturnRemaining(1);
        if (probe.isConsumed()) {
            response.addHeader("X-Rate-Limit-Remaining", String.valueOf(probe.getRemainingTokens()));
            return true;
        }

        response.setStatus(HttpServletResponse.SC_TOO_MANY_REQUESTS);
        response.getWriter().write("Rate limit exceeded");
        response.getWriter().flush();
        return false;
    }

}
```

