                .build();
        buckets = new ProxyBucketBuilder<String>()
                .withRedis(redisTemplate, redisConnectionFactory)
                .buildProxyManager();
        buckets.addBucketIfAbsent("api-limits", bucket);
    }

    @PostConstruct
    public void recovery() {
        JCache<String> cache = JCache.create(
                redisConnectionFactory.getConnection().getNativeConnection(),
                "bucket-cache"
        );
        buckets.setProxyFactory(cache, RecoveryStrategy.RECONSTRUCT);
    }

    public boolean allowRequest(String apiKey) {
        BlockingBucket bucket = buckets.getProxy("api-limits", apiKey);
        return bucket.tryConsume(1);
    }
}
