import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import java.awt.image.ConvolveOp;
import java.awt.image.Kernel;
import java.awt.image.RescaleOp;
import javax.swing.JFrame;
import javax.swing.JPanel;

public class BlurCircleExample extends JPanel {

    private BufferedImage circleImage;

    public BlurCircleExample() {
        int circleSize = 100;
        int imageSize = circleSize * 10; // Increase image size for better roundness
        int x = imageSize / 2 - circleSize / 2;
        int y = imageSize / 2 - circleSize / 2;

        circleImage = new BufferedImage(imageSize, imageSize, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = circleImage.createGraphics();
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2d.setColor(Color.BLACK);
        g2d.fill(new Ellipse2D.Double(x, y, circleSize, circleSize));
        g2d.dispose(); // Dispose the graphics context to release resources
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2d = (Graphics2D) g;

        // Apply blur effect
        Kernel kernel20 = new Kernel(3, 3, new float[]{0.1f, 0.2f, 0.1f,
                                                        0.2f, 0.4f, 0.2f,
                                                        0.1f, 0.2f, 0.1f});
        Kernel kernel50 = new Kernel(3, 3, new float[]{0.05f, 0.1f, 0.05f,
                                                        0.1f, 0.5f, 0.1f,
                                                        0.05f, 0.1f, 0.05f});

        ConvolveOp convolve20 = new ConvolveOp(kernel20);
        ConvolveOp convolve50 = new ConvolveOp(kernel50);

        BufferedImage blurredCircle20 = new BufferedImage(circleImage.getWidth(), circleImage.getHeight(), circleImage.getType());
        BufferedImage blurredCircle50 = new BufferedImage(circleImage.getWidth(), circleImage.getHeight(), circleImage.getType());

        convolve20.filter(circleImage, blurredCircle20);
        convolve50.filter(circleImage, blurredCircle50);

        int x = getWidth() / 2 - circleImage.getWidth() / 2;
        int y = getHeight() / 2 - circleImage.getHeight() / 2;

        g2d.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);

        // Scale down the image for better roundness of small circles
        int scaledSize = circleImage.getWidth() / 10; // Scale factor of 10
        BufferedImage scaledCircle20 = new BufferedImage(scaledSize, scaledSize, BufferedImage.TYPE_INT_ARGB);
        BufferedImage scaledCircle50 = new BufferedImage(scaledSize, scaledSize, BufferedImage.TYPE_INT_ARGB);

        Graphics2D scaledGraphics20 = scaledCircle20.createGraphics();
        Graphics2D scaledGraphics50 = scaledCircle50.createGraphics();

        scaledGraphics20.drawImage(blurredCircle20, 0, 0, scaledSize, scaledSize, null);
        scaledGraphics50.drawImage(blurredCircle50, 0, 0, scaledSize, scaledSize, null);

        scaledGraphics20.dispose();
        scaledGraphics50.dispose();

        // Draw the scaled blurred circles with different levels of blur
        g2d.drawImage(scaledCircle20, x - scaledSize - 20, y, null);
        g2d.drawImage(scaledCircle50, x + 20, y, null);
    }

    public static void main(String[] args) {
        JFrame frame = new JFrame("Blur Circle Example");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(600, 400);
        frame.setLocationRelativeTo(null);

        BlurCircleExample blurCircle = new BlurCircleExample();
        frame.add(blurCircle);

        frame.setVisible(true);
    }
}
```

