If you are looking for an alternative to set the text at the bottom of a `JButton` without using HTML, you can achieve this by customizing the button's UI using the `setUI()` method. Here's an example:

```java
import javax.swing.*;
import java.awt.*;

public class BottomTextButton {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame frame = new JFrame("Bottom Text Button");
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.setLayout(new FlowLayout());

            JButton button = new JButton("Button Text") {
                @Override
                public void setUI(ButtonUI ui) {
                    super.setUI(new BasicButtonUI() {
                        @Override
                        public void paint(Graphics g, JComponent c) {
                            super.paint(g, c);
                            FontMetrics fm = g.getFontMetrics();
                            int textHeight = fm.getHeight();
                            int textWidth = fm.stringWidth(getText());
                            int x = (getWidth() - textWidth) / 2;
                            int y = getHeight() - fm.getDescent();
                            g.drawString(getText(), x, y);
                        }
                    });
                }
            };
            button.setPreferredSize(new Dimension(200, 100));

            frame.getContentPane().add(button);
            frame.pack();
            frame.setVisible(true);
        });
    }
}
```

