   {
       Task SendEmailAsync(string toEmail, string subject, string body);
   }
   ```

3. Implement the email service using MailKit:
   ```csharp
   using MailKit.Net.Smtp;
   using MimeKit;

   public class EmailService : IEmailService
   {
       private readonly string _smtpServer = "smtp.example.com"; // replace with your SMTP server
       private readonly int _smtpPort = 587; // replace with your SMTP port
       private readonly string _emailAddress = "info@cryptotasky.com"; // your chosen email address
       private readonly string _password = "your-email-password"; // replace with your email password

       public async Task SendEmailAsync(string toEmail, string subject, string body)
       {
           var message = new MimeMessage();
           message.From.Add(new MailboxAddress(_emailAddress));
           message.To.Add(new MailboxAddress(toEmail));
           message.Subject = subject;
           message.Body = new TextPart("plain") { Text = body };

           using (var client = new SmtpClient())
           {
               await client.ConnectAsync(_smtpServer, _smtpPort, false);
               await client.AuthenticateAsync(_emailAddress, _password);
               await client.SendAsync(message);
               await client.DisconnectAsync(true);
           }
       }
   }
   ```

