    private Button btnExtractText;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        imageView = findViewById(R.id.imageView);
        btnExtractText = findViewById(R.id.btnExtractText);

        btnExtractText.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                extractTextFromImage();
            }
        });
    }

    private void extractTextFromImage() {
        Bitmap bitmap = BitmapFactory.decodeResource(getResources(), R.drawable.your_image);
        FirebaseVisionImage firebaseVisionImage = FirebaseVisionImage.fromBitmap(bitmap);

        FirebaseVisionTextRecognizer recognizer = FirebaseVision.getInstance().getOnDeviceTextRecognizer();
        Task<FirebaseVisionText> task = recognizer.processImage(firebaseVisionImage);

        task.addOnSuccessListener(new OnSuccessListener<FirebaseVisionText>() {
            @Override
            public void onSuccess(FirebaseVisionText firebaseVisionText) {
                String extractedText = firebaseVisionText.getText();
                Toast.makeText(MainActivity.this, extractedText, Toast.LENGTH_SHORT).show();
            }
        });
    }
}
