Here is an example C++ program that can parse each formula from the file and calculate the corresponding values based on user input:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <sstream>

using namespace std;

// Function to parse and calculate the value of a given formula
string parseFormula(string formula, vector<pair<string, string>> variables) {
    stringstream ss;
    string result;
    ss << formula;

    string token;
    while (getline(ss, token, ' ')) {
        bool found = false;
        for (const auto& variable : variables) {
            if (token == variable.first) {
                token = variable.second;
                found = true;
                break;
            }
        }
        if (!found)
            break;
    }

    try {
        result = to_string(eval(token));
    }
    catch (...) {
        result = "Invalid formula";
    }

    return result;
}

// Function to evaluate a mathematical expression
double eval(string expr) {
    stringstream ss(expr);
    double result;
    ss >> result;
    char op;
    double operand;

    while (ss >> op >> operand) {
        switch (op) {
        case '+':
            result += operand;
            break;
        case '-':
            result -= operand;
            break;
        case '*':
            result *= operand;
            break;
        case '/':
            result /= operand;
            break;
        }
    }

    return result;
}

int main() {
    string inputFile = "formula.txt";
    ifstream file(inputFile);
    string line;
    vector<pair<string, string>> formulas;

    // Read formulas into a vector
    while (getline(file, line)) {
        size_t pos = line.find("=");
        if (pos != string::npos) {
            string formula = line.substr(pos + 1);
            string keywords = line.substr(0, pos - 1);
            formulas.push_back(make_pair(keywords, formula));
        }
    }
    file.close();

    // Prompt user for input
    string input;
    cout << "Enter the required calculation (e.g., work in Joules, if voltage=5V, I=1A, t=10 seconds): ";
    getline(cin, input);

    // Extract formula keywords and variable values
    vector<pair<string, string>> variables;
    stringstream ss(input);
    string keywords;
    string variable;
    while (getline(ss, variable, ',')) {
        size_t pos = variable.find("=");
        if (pos != string::npos) {
            string keyword = variable.substr(0, pos);
            string value = variable.substr(pos + 1);
            variables.push_back(make_pair(keyword, value));
        }
        else {
            keywords += variable;
        }
    }

    // Find matching formula and calculate the result
    for (const auto& formula : formulas) {
        if (formula.first.find(keywords) != string::npos) {
            string result = parseFormula(formula.second, variables);
            cout << formula.first << ": " << result << endl;
        }
    }

    return 0;
}
```

To use this program, create a file named "formula.txt" with the provided formulas. Then, compile and run the C++ program. The program will prompt the user for input in the format mentioned. It will parse the formula, substitute the variable values, and calculate the result. The program will display the calculated values for each matching formula.

