#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PROCESS_IDS 5
#define MAX_COMMAND_SIZE 100

int isProcessIDValid(int pid) {
    if (pid <= 0) {
        printf("Invalid process ID: %d\n", pid);
        return 0;
    }
    return 1;
}

int getParentProcessID(int pid) {
    char command[MAX_COMMAND_SIZE];
    snprintf(command, sizeof(command), "ps -o ppid= -p %d", pid);

    FILE* fp = popen(command, "r");
    if (fp == NULL) {
        printf("Failed to execute command\n");
        return -1;
    }

    int ppid = 0;
    if (fscanf(fp, "%d", &ppid) != 1) {
        printf("Failed to retrieve parent process ID for: %d\n", pid);
        ppid = -1;
    }

    pclose(fp);

    return ppid;
}

void listNonDirectDescendants(int rootPID, int processID) {
    if (!isProcessIDValid(processID)) {
        return;
    }

    char command[MAX_COMMAND_SIZE];
    snprintf(command, sizeof(command), "pstree -p %d | grep -oE '\\(([0-9]+)\\)' | grep -oE '[0-9]+' | grep -v '%d'", rootPID, processID);
    printf("Listing non-direct descendants of %d\n", processID);
    system(command);
}

void listImmediateDescendants(int processID) {
    char command[MAX_COMMAND_SIZE];
    snprintf(command, sizeof(command), "ps -o pid --ppid %d --no-headers", processID);
    printf("Listing immediate descendants of %d\n", processID);
    system(command);
}

void listSiblingProcesses(int processID) {
    char command[MAX_COMMAND_SIZE];
    snprintf(command, sizeof(command), "ps -o pid --ppid $(ps -o ppid= -p %d) --no-headers", processID);
    printf("Listing sibling processes of %d\n", processID);
    system(command);
}

void listDefunctSiblingProcesses(int processID) {
    char command[MAX_COMMAND_SIZE];
    snprintf(command, sizeof(command), "ps -o pid,state --ppid $(ps -o ppid= -p %d) --no-headers | awk '$2 == \"Z\" {print $1}'", processID);
    printf("Listing defunct sibling processes of %d\n", processID);
    system(command);
}

void listGrandchildren(int processID) {
    char command[MAX_COMMAND_SIZE];
    snprintf(command, sizeof(command), "pgrep -P %d", processID);
    printf("Listing grandchildren of %d\n", processID);
    system(command);
}

void checkProcessStatus(int processID) {
    char command[MAX_COMMAND_SIZE];
    snprintf(command, sizeof(command), "ps -o state --pid %d --no-headers | awk '{print $1}'", processID);
    printf("Checking status of process %d: ", processID);
    fflush(stdout);

    FILE* fp = popen(command, "r");
    if (fp == NULL) {
        printf("Failed to execute command\n");
        return;
    }

    char status[10];
    if (fgets(status, sizeof(status), fp) != NULL) {
        status[strcspn(status, "\n")] = '\0';
        if (strcmp(status, "Z") == 0) {
            printf("Defunct\n");
        } else {
            printf("Not Defunct\n");
        }
    }

    pclose(fp);
}

void listDefunctDescendants(int processID) {
    char command[MAX_COMMAND_SIZE];
    snprintf(command, sizeof(command), "ps -o pid,state --ppid %d --no-headers | awk '$2 == \"Z\" {print $1}'", processID);
    printf("Listing defunct descendants of %d\n", processID);
    system(command);
}

void processOption(int rootPID, int* processIDs, int numProcessIDs, char* option) {
    if (numProcessIDs < 1) {
        printf("Invalid number of process IDs\n");
        return;
    }

    int processID = processIDs[0];

    if (!isProcessIDValid(processID)) {
        return;
    }

    if (strcmp(option, "-nd") == 0) {
        listNonDirectDescendants(rootPID, processID);
    } else if (strcmp(option, "-dd") == 0) {
        listImmediateDescendants(processID);
    } else if (strcmp(option, "-sb") == 0) {
        listSiblingProcesses(processID);
    } else if (strcmp(option, "-sz") == 0) {
        listDefunctSiblingProcesses(processID);
    } else if (strcmp(option, "-gc") == 0) {
        listGrandchildren(processID);
    } else if (strcmp(option, "-st") == 0) {
        checkProcessStatus(processID);
    } else if (strcmp(option, "-fd") == 0) {
        listDefunctDescendants(processID);
    } else {
        printf("Invalid option: %s\n", option);
    }
}

