当使用Linux的C语言编写UDP的select多线程程序时，可以按照以下步骤进行编写：

1. 导入必要的头文件：
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <pthread.h>
```

2. 定义全局变量：
```c
#define PORT 8888
#define MAX_CLIENTS 10

int server_socket;
fd_set read_fds;
int clients[MAX_CLIENTS];
pthread_t threads[MAX_CLIENTS];
pthread_mutex_t mutex;
```

3. 初始化服务器套接字、客户端列表和互斥锁：
```c
void init_server_socket() {
    struct sockaddr_in server_addr;
    if ((server_socket = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        exit(1);
    }
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    server_addr.sin_port = htons(PORT);
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind failed");
        exit(1);
    }
    FD_ZERO(&read_fds);
    FD_SET(server_socket, &read_fds);
    memset(clients, 0, sizeof(clients));
    pthread_mutex_init(&mutex, NULL);
}
```

4. 定义接收和发送线程函数：
```c
void* receive_thread(void* arg) {
    int client_socket = *(int*)arg;
    char buffer[1024];
    int recv_len;
    while (1) {
        fd_set tmp_fds = read_fds;
        if (select(client_socket + 1, &tmp_fds, NULL, NULL, NULL) < 0) {
            perror("select error");
            exit(1);
        }
        if (FD_ISSET(client_socket, &tmp_fds)) {
            recv_len = recvfrom(client_socket, buffer, sizeof(buffer), 0, NULL, NULL);
            if (recv_len < 0) {
                perror("recvfrom error");
                exit(1);
            }
            // 处理接收到的数据
            pthread_mutex_lock(&mutex);
            for (int i = 0; i < MAX_CLIENTS; i++) {
                if (clients[i] != 0 && clients[i] != client_socket) {
                    sendto(clients[i], buffer, recv_len, 0, NULL, 0);
                }
            }
            pthread_mutex_unlock(&mutex);
        }
    }
    return NULL;
}

void* send_thread(void* arg) {
    int client_socket = *(int*)arg;
    char buffer[1024];
    while (1) {
        fgets(buffer, sizeof(buffer), stdin);
        // 发送数据
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < MAX_CLIENTS; i++) {
            if (clients[i] != 0 && clients[i] != client_socket) {
                sendto(clients[i], buffer, strlen(buffer) + 1, 0, NULL, 0);
            }
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}
```

5. 启动服务器和客户端线程：
```c
void start_threads() {
    struct sockaddr_in client_addr;
    socklen_t addrlen;
    addrlen = sizeof(client_addr);
    while (1) {
        int client_socket = accept(server_socket, (struct sockaddr*)&client_addr, &addrlen);
        if (client_socket == -1) {
            perror("accept error");
            exit(1);
        }
        FD_SET(client_socket, &read_fds);
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < MAX_CLIENTS; i++) {
            if (clients[i] == 0) {
                clients[i] = client_socket;
                pthread_create(&threads[i], NULL, receive_thread, (void*)&clients[i]);
                pthread_create(&threads[i + MAX_CLIENTS], NULL, send_thread, (void*)&clients[i]);
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
    }
    pthread_mutex_destroy(&mutex);
}
```

6. 编写main函数并调用初始化和启动函数：
```c
int main() {
    init_server_socket();
    start_threads();
    return 0;
}
