        double[][] centroids = new double[k][2];
        for (int i = 0; i < k; i++) {
            centroids[i][0] = dataPoints[i][0]; // x-coordinate
            centroids[i][1] = dataPoints[i][1]; // y-coordinate
        }

        int[] clusters = new int[n];
        boolean isChanged = true;

        while (isChanged) {
            isChanged = false;

            for (int i = 0; i < n; i++) {
                double x = dataPoints[i][0];
                double y = dataPoints[i][1];

                // Find the nearest centroid
                int nearestCentroid = 0;
                double minDistance = getDistance(x, y, centroids[0][0], centroids[0][1]);

                for (int j = 1; j < k; j++) {
                    double distance = getDistance(x, y, centroids[j][0], centroids[j][1]);
                    if (distance < minDistance) {
                        nearestCentroid = j;
                        minDistance = distance;
                    }
                }

                // Assign the data point to the nearest cluster
                if (clusters[i] != nearestCentroid) {
                    clusters[i] = nearestCentroid;
                    isChanged = true;
                }
            }

            // Update the centroids
            for (int i = 0; i < k; i++) {
                double sumX = 0;
                double sumY = 0;
                int count = 0;

                for (int j = 0; j < n; j++) {
                    if (clusters[j] == i) {
                        sumX += dataPoints[j][0];
                        sumY += dataPoints[j][1];
                        count++;
                    }
                }

                if (count > 0) {
                    centroids[i][0] = sumX / count;
                    centroids[i][1] = sumY / count;
                }
            }
        }

        // Print the clustering result
        System.out.println("\nClustering result:");
        for (int i = 0; i < n; i++) {
            System.out.println("(" + dataPoints[i][0] + ", " + dataPoints[i][1] + ") belongs to cluster " + clusters[i]);
        }
    }

    public static double getDistance(double x1, double y1, double x2, double y2) {
        double xDiff = x2 - x1;
        double yDiff = y2 - y1;
        return Math.sqrt(xDiff * xDiff + yDiff * yDiff);
    }
