            String[] values = input.split(",");
            double x = Double.parseDouble(values[0]);
            double y = Double.parseDouble(values[1]);
            points.add(new Point(x, y));
        }

        List<Cluster> clusters = kMeansClustering(points, k);

        System.out.println("Cluster centers:");

        for (Cluster cluster : clusters) {
            System.out.println(cluster.getCenter());
        }

        scanner.close();
    }

    private static List<Cluster> kMeansClustering(List<Point> points, int k) {
        List<Cluster> clusters = initializeClusters(points, k);

        boolean isChanged;
        do {
            assignPointsToClusters(clusters, points);
            isChanged = updateClusterCenters(clusters);
        } while (isChanged);

        return clusters;
    }

    private static List<Cluster> initializeClusters(List<Point> points, int k) {
        List<Cluster> clusters = new ArrayList<>();
        Random random = new Random();

        for (int i = 0; i < k; i++) {
            Point randomPoint = points.get(random.nextInt(points.size()));
            clusters.add(new Cluster(randomPoint));
        }

        return clusters;
    }

    private static void assignPointsToClusters(List<Cluster> clusters, List<Point> points) {
        for (Cluster cluster : clusters) {
            cluster.clearPoints();
        }

        for (Point point : points) {
            Cluster closestCluster = clusters.get(0);

            for (Cluster cluster : clusters) {
                if (point.distanceTo(cluster.getCenter()) < point.distanceTo(closestCluster.getCenter())) {
                    closestCluster = cluster;
                }
            }

            closestCluster.addPoint(point);
        }
    }

    private static boolean updateClusterCenters(List<Cluster> clusters) {
        boolean isChanged = false;

        for (Cluster cluster : clusters) {
            Point oldCenter = cluster.getCenter();
            Point newCenter = cluster.calculateCenter();

            if (!oldCenter.equals(newCenter)) {
                isChanged = true;
                cluster.setCenter(newCenter);
            }
        }

        return isChanged;
    }
}

class Point {
    private final double x;
    private final double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double distanceTo(Point other) {
        double dx = x - other.x;
        double dy = y - other.y;
        return Math.sqrt(dx * dx + dy * dy);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }

        if (obj == null || getClass() != obj.getClass()) {
            return false;
        }

        Point other = (Point) obj;
        return x == other.x && y == other.y;
    }

    @Override
    public int hashCode() {
        return Double.hashCode(x) * 31 + Double.hashCode(y);
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

class Cluster {
    private Point center;
    private List<Point> points;

    public Cluster(Point center) {
        this.center = center;
        this.points = new ArrayList<>();
    }

    public Point getCenter() {
        return center;
    }

    public void setCenter(Point center) {
        this.center = center;
    }

    public void addPoint(Point point) {
        points.add(point);
    }

    public void clearPoints() {
        points.clear();
    }

    public Point calculateCenter() {
        double sumX = 0;
        double sumY = 0;

        for (Point point : points) {
            sumX += point.x;
            sumY += point.y;
        }

        double avgX = sumX / points.size();
        double avgY = sumY / points.size();

        return new Point(avgX, avgY);
    }
}
