class Cluster {
    double centroidX;
    double centroidY;
    List<DataPoint> points;

    public Cluster(double centroidX, double centroidY) {
        this.centroidX = centroidX;
        this.centroidY = centroidY;
        this.points = new ArrayList<>();
    }

    public void clearPoints() {
        points.clear();
    }

