        for (DataPoint point : points) {
            newCentroidX += point.x;
            newCentroidY += point.y;
        }

        if (points.size() > 0) {
            newCentroidX /= points.size();
            newCentroidY /= points.size();
        }

        boolean hasCentroidMoved = centroidX != newCentroidX || centroidY != newCentroidY;
        centroidX = newCentroidX;
        centroidY = newCentroidY;
        return hasCentroidMoved;
    }
}

public class KMeansClustering {
    private static final int NUM_CLUSTERS = 3;
    private static final int MAX_ITERATIONS = 100;

    private static List<DataPoint> dataPoints;
    private static List<Cluster> clusters;

    public static void main(String[] args) {
