        String filePath = "data.txt";
        dataPoints = readDataFromFile(filePath);

        // Initialize clusters with random centroids
        initializeClusters();

        // Perform K-means clustering
        int iteration = 1;
        boolean hasCentroidsMoved = true;

        while (iteration <= MAX_ITERATIONS && hasCentroidsMoved) {
            hasCentroidsMoved = assignDataPointsToClusters();
            updateClusterCentroids();
            iteration++;
        }

        // Print final clustering result
        System.out.println("Final Clustering:");
        for (Cluster cluster : clusters) {
            System.out.println("Cluster Centroid: (" + cluster.centroidX + ", " + cluster.centroidY + ")");
            for (DataPoint point : cluster.points) {
                System.out.println("Point: (" + point.x + ", " + point.y + ") - Cluster: " + point.cluster);
            }
            System.out.println();
        }
    }

    private static List<DataPoint> readDataFromFile(String filePath) {
        List<DataPoint> dataPoints = new ArrayList<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] values = line.split(",");
                double x = Double.parseDouble(values[0].trim());
                double y = Double.parseDouble(values[1].trim());
                dataPoints.add(new DataPoint(x, y));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        return dataPoints;
    }

    private static void initializeClusters() {
        clusters = new ArrayList<>();

        Random random = new Random();
        for (int i = 0; i < NUM_CLUSTERS; i++) {
            double centroidX = random.nextDouble() * 10;
            double centroidY = random.nextDouble() * 10;
            clusters.add(new Cluster(centroidX, centroidY));
        }
    }

    private static boolean assignDataPointsToClusters() {
        boolean hasCentroidsMoved = false;

        for (DataPoint point : dataPoints) {
            double minDistance = Double.MAX_VALUE;
            int closestCluster = -1;

            for (int i = 0; i < NUM_CLUSTERS; i++) {
                double distance = calculateDistance(point, clusters.get(i));
                if (distance < minDistance) {
                    minDistance = distance;
                    closestCluster = i;
                }
            }

            if (point.cluster != closestCluster) {
                hasCentroidsMoved = true;
                if (point.cluster != -1) {
                    clusters.get(point.cluster).points.remove(point);
                }
                clusters.get(closestCluster).assignPoint(point);
            }
        }

        return hasCentroidsMoved;
    }

    private static double calculateDistance(DataPoint point, Cluster cluster) {
        double distX = Math.pow(point.x - cluster.centroidX, 2);
        double distY = Math.pow(point.y - cluster.centroidY, 2);
        return Math.sqrt(distX + distY);
    }

    private static void updateClusterCentroids() {
        for (Cluster cluster : clusters) {
            cluster.updateCentroid();
        }
    }
}
