Certainly! Here's an example in C++ that demonstrates how to use a TCP socket for blocking read on the client side:

```cpp
#include <iostream>
#include <string>
#include <cstring>
#include <sys/socket.h>
#include <arpa/inet.h>

#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 1234

int main() {
    // Create TCP socket
    int clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket == -1) {
        std::cerr << "Failed to create socket." << std::endl;
        return 1;
    }

    // Set up server details
    sockaddr_in serverAddress{};
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &(serverAddress.sin_addr)) <= 0) {
        std::cerr << "Failed to set server address." << std::endl;
        return 1;
    }

    // Connect to the server
    if (connect(clientSocket, (struct sockaddr*)&serverAddress, sizeof(serverAddress)) < 0) {
        std::cerr << "Failed to connect to the server." << std::endl;
        return 1;
    }

    // Receive data from the server
    char buffer[1024] = {0};
    int bytesRead = recv(clientSocket, buffer, sizeof(buffer) - 1, 0);
    if (bytesRead == -1) {
        std::cerr << "Failed to receive data from the server." << std::endl;
        return 1;
    }

    // Print the received data
    std::cout << "Received data: " << buffer << std::endl;

    // Close the socket
    close(clientSocket);

    return 0;
}
```

In this example, we use the `socket()` function to create a TCP socket. The `connect()` function is used to establish a connection to the server. The `recv()` function is then used to read data from the socket in a blocking manner. The received data is stored in the `buffer` variable and printed to the console.

Remember to replace the `SERVER_IP` and `SERVER_PORT` with the appropriate values for your server.

