                        ImageButton card2 = findViewById(flippedCardIndex2);

                        card1.setImageResource(R.drawable.back_image);
                        card2.setImageResource(R.drawable.back_image);

                        flippedCardIndex1 = -1;
                        flippedCardIndex2 = -1;
                    }
                }, 1000); // Delay in milliseconds (adjust as needed)
            }
        }
    }
}
