import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

public class DotStream extends JPanel implements ActionListener {
    private static final int DOT_SIZE = 10;
    private static final int PANEL_WIDTH = 600;
    private static final int PANEL_HEIGHT = 400;
    private static final Color DOT_COLOR = Color.RED;
    private static final long DOT_INTERVAL = 20_000_000;  // Change this for different dot interval (in nanoseconds)

    private double dotX = -DOT_SIZE;
    private long lastUpdateTime = System.nanoTime();

    public DotStream() {
        Timer timer = new Timer(1, this);
        timer.start();
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        setBackground(Color.GREEN);
        g.setColor(DOT_COLOR);
        g.fillOval((int) dotX, (PANEL_HEIGHT - DOT_SIZE) / 2, DOT_SIZE, DOT_SIZE);
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        long currentTime = System.nanoTime();
        long elapsedTime = currentTime - lastUpdateTime;

        if (elapsedTime >= DOT_INTERVAL) {
            int movementSteps = (int) (elapsedTime / DOT_INTERVAL);

            for (int i = 0; i < movementSteps; i++) {
                dotX += 1;  // Fixed increment value for dot movement

                if (dotX > PANEL_WIDTH) {
                    dotX = -DOT_SIZE;
                }
            }

            lastUpdateTime = currentTime;
            repaint();
        }
    }

    @Override
    public Dimension getPreferredSize() {
        return new Dimension(PANEL_WIDTH, PANEL_HEIGHT);
    }

    public static void main(String[] args) {
