public class CardioMonitor extends JPanel {

    private int[] heartbeatData; // Heartbeat data array
    private int currentX = 0; // Current x-coordinate for drawing the curve

    public CardioMonitor() {
        setPreferredSize(new Dimension(800, 300));
        setOpaque(true);
        setBackground(Color.WHITE);
        heartbeatData = generateHeartbeatData();

        // Start animating the heartbeat curve
        Timer timer = new Timer(30, new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                if (currentX < getWidth()) {
                    currentX++;
                    repaint();
                }
            }
        });
        timer.start();
    }

    private int[] generateHeartbeatData() {
        int[] data = new int[getWidth()]; // Array with size equal to the panel width
        int maxY = getHeight() / 2; // Maximum y-coordinate for the curve

        // Generate heartbeat data using a sine wave
        for (int i = 0; i < getWidth(); i++) {
            data[i] = (int) (maxY + Math.sin(Math.toRadians(i * 360.0 / getWidth())) * maxY);
        }

        return data;
    }

