            boardGridLayout.addView(button);
            buttons.add(button);
        }
    }

    private void shuffleButtons() {
        List<Integer> numbers = new ArrayList<>(Arrays.asList(1, 1, 2, 2, 3, 3, 4, 4));
        Collections.shuffle(numbers);

        for (int i = 0; i < NUM_BUTTONS; i++) {
            buttons.get(i).setText(String.valueOf(numbers.get(i)));
        }
    }

    private void createListeners() {
        for (final Button button : buttons) {
            button.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View view) {
                    if (button.getVisibility() == View.INVISIBLE) {
                        return;
                    }

                    button.setBackgroundResource(android.R.drawable.btn_default);
                    button.setEnabled(false);

                    if (isMatchPairSelected()) {
                        moves++;
                        movesTextView.setText("Moves: " + moves);
                        Button selectedButton = getSelectedButton();

                        if (button.getText().equals(selectedButton.getText())) {
                            button.setVisibility(View.INVISIBLE);
                            selectedButton.setVisibility(View.INVISIBLE);

                            matchedPairs++;

                            if (matchedPairs == NUM_BUTTONS / 2) {
                                showGameOverDialog();
                            }
                        } else {
                            selectedButton.setEnabled(true);
                        }
                    } else {
                        button.setEnabled(true);
                    }
                }
            });
        }

        continueButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                resetGame();
            }
        });
    }

    private boolean isMatchPairSelected() {
        int count = 0;

        for (Button button : buttons) {
            if (!button.isEnabled()) {
                count++;
            }
        }

        return count == 2;
    }

    private Button getSelectedButton() {
        for (Button button : buttons) {
            if (!button.isEnabled()) {
                return button;
            }
        }

        return null;
    }

    private void showGameOverDialog() {
        AlertDialog.Builder builder = new AlertDialog.Builder(this);
        builder.setMessage("Congratulations! You won in " + moves + " moves!")
                .setCancelable(false)
                .setPositiveButton("Ok", null);
        AlertDialog alert = builder.create();
        alert.show();

        continueButton.setVisibility(View.VISIBLE);
    }

    private void resetGame() {
        for (Button button : buttons) {
            button.setVisibility(View.VISIBLE);
            button.setEnabled(true);
            button.setText("");
        }

        shuffleButtons();

        moves = 0;
        matchedPairs = 0;
        movesTextView.setText("Moves: 0");

        continueButton.setVisibility(View.INVISIBLE);
    }
}
```

Run the app and when the player touches the "Play" button, the game will start. The game board will have 4x2 buttons, each randomly assigned a number from 1 to 4. The player can touch the buttons to find matching pairs. When a match is found, the corresponding buttons will be set to invisible. The number of moves will be displayed at the top of the screen. Once all matching pairs are found, a dialog box will appear showing the number of moves taken to win the game. The "Continue" button at the bottom can be clicked to start a new game.

