import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bucket4j;
import io.github.bucket4j.Configuration;
import io.github.bucket4j.local.LocalBucketBuilder;
import io.lettuce.core.RedisClient;
import io.lettuce.core.RedisException;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.api.sync.RedisCommands;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;

public class RateLimiterExample {

    private static Map<String, Bucket> rateLimitBuckets = new HashMap<>();

    public static void main(String[] args) throws IOException {
        // Read rate limit configuration from Excel file or any other source
        Map<String, Integer> rateLimitConfig = readRateLimitConfigFromFile("rate_limits.xlsx");

        // Initialize Redis connection
        RedisClient redisClient = RedisClient.create("redis://localhost");
        try (StatefulRedisConnection<String, String> connection = redisClient.connect()) {
            RedisCommands<String, String> syncCommands = connection.sync();

            // Dynamically create rate limiter instances for each API
            for (Map.Entry<String, Integer> limit : rateLimitConfig.entrySet()) {
                String apiName = limit.getKey();
                int rateLimit = limit.getValue();

                // Create a local bucket using Bucket4j
                Configuration configuration = Bucket4j.configurationBuilder()
                        .addLimit(Bandwidth.simple(rateLimit, java.time.Duration.ofMinutes(1)))
                        .build();

                LocalBucketBuilder builder = Bucket4j.builder().addConfiguration(configuration);
                Bucket rateLimitBucket = builder.build();

                // Store rate limit bucket in Redis
                try {
                    syncCommands.set(apiName, String.valueOf(rateLimit));
                } catch (RedisException e) {
                    // Handle Redis connection or command exception
                }

                // Cache rate limit bucket in memory
                rateLimitBuckets.put(apiName, rateLimitBucket);
            }
        }

        // Simulate API requests
        for (int i = 0; i < 20; i++) {
            simulateApiRequest("api-1");
            simulateApiRequest("api-2");
            simulateApiRequest("api-3");
        }

        // Close Redis connection
        redisClient.shutdown();
    }

    private static Map<String, Integer> readRateLimitConfigFromFile(String filePath) throws IOException {
        Properties properties = new Properties();
        properties.load(new FileInputStream(new File(filePath)));

        Map<String, Integer> rateLimitConfig = new HashMap<>();
        for (String api : properties.stringPropertyNames()) {
            rateLimitConfig.put(api, Integer.parseInt(properties.getProperty(api)));
        }

        return rateLimitConfig;
    }

    private static void simulateApiRequest(String apiName) {
        // Retrieve rate limit bucket for the API
        Bucket rateLimitBucket = rateLimitBuckets.get(apiName);

        // Perform rate limiting checks
        if (rateLimitBucket.tryConsume(1)) {
            System.out.println("API request for " + apiName + " processed successfully");
        } else {
            System.out.println("API request for " + apiName + " exceeded rate limit");
        }
    }
}
```

