#include <stdlib.h>
#include <pthread.h>

#define MAX_THREADS 4

int* input_array;
int* prefix_sum;
int num_elements;
int num_threads;
pthread_barrier_t barrier;

void* prefix_sum_thread(void* arg) {
    int thread_id = *((int*) arg);

    // Compute the prefix sum of the assigned subarray
    int elements_per_thread = num_elements / num_threads;
    int start_index = thread_id * elements_per_thread;
    int end_index = start_index + elements_per_thread - 1;

    for (int i = start_index + 1; i <= end_index; i++) {
        prefix_sum[i] += prefix_sum[i - 1];
    }

    // Wait for all threads to finish before proceeding to the next step
    pthread_barrier_wait(&barrier);

    // Adjust the prefix sum for the next subarray
    if (thread_id > 0) {
        int offset = prefix_sum[start_index - 1];
        for (int i = start_index; i <= end_index; i++) {
            prefix_sum[i] += offset;
        }
    }

    return NULL;
}

void compute_prefix_sum(int* array, int length, int num_threads) {
    input_array = array;
    num_elements = length;
    prefix_sum = malloc(sizeof(int) * num_elements);

    // Initialize the prefix sum array with the input array
    for (int i = 0; i < num_elements; i++) {
        prefix_sum[i] = input_array[i];
    }

    // Initialize the barrier
    pthread_barrier_init(&barrier, NULL, num_threads);

    // Create the threads
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];
    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, prefix_sum_thread, &thread_ids[i]);
    }

    // Join the threads
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the barrier resources
    pthread_barrier_destroy(&barrier);

    // Print the prefix sum array
    printf("Prefix Sum Array: ");
    for (int i = 0; i < num_elements; i++) {
        printf("%d ", prefix_sum[i]);
    }
    printf("\n");

    // Free the allocated memory
    free(prefix_sum);
}

