import 'package:flutter/material.dart';
import 'package:flutter_color_gradient/flutter_color_gradient.dart';

class CascadingText extends StatefulWidget {
  @override
  _CascadingTextState createState() => _CascadingTextState();
}

class _CascadingTextState extends State<CascadingText> with SingleTickerProviderStateMixin {
  AnimationController _animationController;

  @override
  void initState() {
    super.initState();
    // Set up the animation controller
    _animationController = AnimationController(
      vsync: this,
      duration: Duration(seconds: 3),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    // Dispose of the animation controller
    _animationController.dispose();
    super.dispose();
  }

