    return Scaffold(
      appBar: AppBar(
        title: Text('Cascading Text'),
      ),
      body: Center(
        child: AnimatedBuilder(
          animation: _animationController,
          builder: (context, child) {
            return ShaderMask(
              shaderCallback: (bounds) {
                return LinearGradient(
                  colors: [
                    Colors.red,
                    Colors.green,
                    Colors.blue,
                  ],
                  tileMode: TileMode.clamp,
                  transform: GradientRotation(_animationController.value * 2 * 3.14159), // Rotate the gradient
                ).createShader(bounds);
              },
              child: Text(
                'Cascading Text',
                style: TextStyle(
                  fontSize: 24,
                  fontWeight: FontWeight.bold,
                ),
              ),
            );
          },
        ),
      ),
    );
  }
}

void main() {
