    TaskHandle_t taskHandle;
    QueueHandle_t notificationQueue;
} WaitQueueHead_t;

void init_waitqueue_head(WaitQueueHead_t *q) {
    q->taskHandle = xTaskGetCurrentTaskHandle();
    q->notificationQueue = xQueueCreate(1, sizeof(uint32_t));
}

int wait_event_interruptible(WaitQueueHead_t *q, int condition) {
    int ret = pdFALSE;

    if (condition) {
