    struct TaskListNode* taskList;
    QueueHandle_t notificationQueue;
} WaitQueueHead_t;

typedef struct TaskListNode {
    TaskHandle_t taskHandle;
    struct TaskListNode* next;
} TaskListNode_t;

void init_waitqueue_head(WaitQueueHead_t *q) {
    q->taskList = NULL;
    q->notificationQueue = xQueueCreate(1, sizeof(uint32_t));
}

int wait_event_interruptible(WaitQueueHead_t *q, int condition) {
    int ret = pdFALSE;

    if (condition) {
        TaskListNode_t node;
        node.taskHandle = xTaskGetCurrentTaskHandle();
        node.next = NULL;

        xQueueReset(q->notificationQueue);

        // Add the current task to the task list
        if (q->taskList == NULL) {
            q->taskList = &node;
        } else {
            TaskListNode_t* curr = q->taskList;
            while (curr->next != NULL) {
                curr = curr->next;
            }
            curr->next = &node;
        }

        // Wait for a notification
        ret = xTaskNotifyWait(0, ULONG_MAX, NULL, portMAX_DELAY);

        // Remove the current task from the task list
        if (q->taskList == &node) {
            q->taskList = node.next;
        } else {
            TaskListNode_t* curr = q->taskList;
            while (curr->next != &node) {
                curr = curr->next;
            }
            curr->next = node.next;
        }
    }

    return ret == pdTRUE ? 0 : -1;
}

void wake_up_all(WaitQueueHead_t *q) {
    BaseType_t xHigherPriorityTaskWoken;
    xTaskNotifyGiveFromISR(q->taskList->taskHandle, &xHigherPriorityTaskWoken);
    xQueueSendFromISR(q->notificationQueue, NULL, &xHigherPriorityTaskWoken);
    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}
```

