```cpp
#include <iostream>
#include <vector>
#include <string>

// Database Access Object (DAO) interface
class UserDao {
public:
    virtual void saveUser(const std::string& username, const std::string& password) = 0;
    virtual void deleteUser(const std::string& username) = 0;
    virtual std::vector<std::string> getAllUsers() = 0;
};

// Database Access Object (DAO) implementation for MySQL
class MySqlUserDao : public UserDao {
public:
    void saveUser(const std::string& username, const std::string& password) override {
        // MySQL specific code to save user in database
        std::cout << "Saved user " << username << " in MySQL" << std::endl;
    }

    void deleteUser(const std::string& username) override {
        // MySQL specific code to delete user from database
        std::cout << "Deleted user " << username << " from MySQL" << std::endl;
    }

    std::vector<std::string> getAllUsers() override {
        // MySQL specific code to retrieve all users from database
        std::vector<std::string> users = {"User1", "User2", "User3"};
        return users;
    }
};

// Application class
class Application {
private:
    UserDao* dao;

public:
    Application(UserDao* userDao) : dao(userDao) {}

    void registerUser(const std::string& username, const std::string& password) {
        // Business logic to validate and register user
        dao->saveUser(username, password);
    }

    void deleteUser(const std::string& username) {
        // Business logic to delete user
        dao->deleteUser(username);
    }

    void displayAllUsers() {
        // Business logic to display all users
        std::vector<std::string> users = dao->getAllUsers();
        std::cout << "All Users: ";
        for (const std::string& user : users) {
            std::cout << user << " ";
        }
        std::cout << std::endl;
    }
};

int main() {
    UserDao* userDao = new MySqlUserDao();
    Application app(userDao);

    app.registerUser("John", "12345");
    app.registerUser("Jane", "54321");
    app.displayAllUsers();
    app.deleteUser("Jane");

    delete userDao;
    return 0;
}
```

