Certainly! Here are a few examples of encapsulated database access in C++:

Example 1: Using SQLite

```cpp
#include <iostream>
#include <sqlite3.h>

class Database {
private:
    sqlite3* db;

public:
    Database(const std::string& filename) {
        int rc = sqlite3_open(filename.c_str(), &db);
        if (rc != SQLITE_OK) {
            std::cout << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
            sqlite3_close(db);
        }
    }

    ~Database() {
        sqlite3_close(db);
    }

    void executeQuery(const std::string& query) {
        char* errorMsg = nullptr;
        int rc = sqlite3_exec(db, query.c_str(), nullptr, nullptr, &errorMsg);
        if (rc != SQLITE_OK) {
            std::cout << "Query execution failed: " << errorMsg << std::endl;
            sqlite3_free(errorMsg);
        }
    }
};

int main() {
    Database db("example.db");

    // Execute SQL query
    db.executeQuery("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)");
    db.executeQuery("INSERT INTO users (name) VALUES ('John')");

    return 0;
}
```

In this example, the `Database` class encapsulates the SQLite database connection and provides a `executeQuery` method to execute SQL queries. When creating an instance of `Database`, a connection to the database file "example.db" is established. The `executeQuery` method allows you to pass SQL queries as strings and executes them. Proper error handling is included to handle any query execution failures.

Example 2: Using PostgreSQL (libpq)

```cpp
#include <iostream>
#include <libpq-fe.h>

class Database {
private:
    PGconn* conn;

public:
    Database(const std::string& host, const std::string& port, const std::string& dbname, const std::string& user, const std::string& password) {
        std::string connString = "host=" + host + " port=" + port + " dbname=" + dbname + " user=" + user + " password=" + password;
        conn = PQconnectdb(connString.c_str());
        if (PQstatus(conn) != CONNECTION_OK) {
            std::cout << "Connection failed: " << PQerrorMessage(conn) << std::endl;
            PQfinish(conn);
        }
    }

    ~Database() {
        PQfinish(conn);
    }

    void executeQuery(const std::string& query) {
        PGresult* result = PQexec(conn, query.c_str());
        if (PQresultStatus(result) != PGRES_COMMAND_OK && PQresultStatus(result) != PGRES_TUPLES_OK) {
            std::cout << "Query execution failed: " << PQresultErrorMessage(result) << std::endl;
        }
        PQclear(result);
    }
};

int main() {
    Database db("localhost", "5432", "mydb", "myuser", "mypassword");

    // Execute SQL query
    db.executeQuery("CREATE TABLE users (id SERIAL PRIMARY KEY, name VARCHAR(50))");
    db.executeQuery("INSERT INTO users (name) VALUES ('John')");

    return 0;
}
```

In this example, the `Database` class encapsulates the database connection using the libpq library for PostgreSQL. It establishes a connection to the PostgreSQL database using the provided credentials. The `executeQuery` method executes SQL queries using the connection and properly handles any query execution failures.

These examples demonstrate encapsulated database access with different database systems (SQLite and PostgreSQL). The database-specific code is encapsulated within the `Database` class, allowing the application to interact with the database using a simplified interface without exposing the implementation details.

