import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Rectangle;
import javafx.stage.Stage;

public class PianoKeyboard extends Application {

    private static final int NUM_KEYS = 88;
    private static final int WHITE_KEY_WIDTH = 30;
    private static final int WHITE_KEY_HEIGHT = 120;
    private static final int BLACK_KEY_WIDTH = 20;
    private static final int BLACK_KEY_HEIGHT = 80;

    @Override
    public void start(Stage primaryStage) {
        Pane root = new Pane();

        // Create white keys
        for (int i = 0; i < NUM_KEYS; i++) {
            Rectangle whiteKey = new Rectangle(i * WHITE_KEY_WIDTH, 0, WHITE_KEY_WIDTH, WHITE_KEY_HEIGHT);
            whiteKey.setFill(Color.WHITE);
            whiteKey.setStroke(Color.BLACK);
            root.getChildren().add(whiteKey);
        }

        // Create black keys
        int[] blackKeyIndices = {1, 3, 6, 8, 10};
        for (int i : blackKeyIndices) {
            Rectangle blackKeyLeft = new Rectangle(i * WHITE_KEY_WIDTH - BLACK_KEY_WIDTH / 2, 0, BLACK_KEY_WIDTH, BLACK_KEY_HEIGHT);
            Rectangle blackKeyRight = new Rectangle(i * WHITE_KEY_WIDTH + WHITE_KEY_WIDTH - BLACK_KEY_WIDTH / 2, 0, BLACK_KEY_WIDTH, BLACK_KEY_HEIGHT);
            blackKeyLeft.setFill(Color.BLACK);
            blackKeyRight.setFill(Color.BLACK);
            root.getChildren().addAll(blackKeyLeft, blackKeyRight);
        }

