public class MidiScoreSheet extends JFrame {
    private static final int NOTE_SIZE = 10;
    private static final int LINE_SPACING = 50;
    private static final int BAR_SPACING = 100;
    private static final int OCTAVE_3_OFFSET = 150;
    private static final int OCTAVE_5_OFFSET = 50;

    private Sequence sequence;
    private Track track;

    public MidiScoreSheet(Sequence sequence) {
        this.sequence = sequence;
        this.track = sequence.getTracks()[0]; // Assuming only one track for simplicity

        setTitle("MIDI Score Sheet");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(800, 400);
        setLocationRelativeTo(null);
        setVisible(true);
    }

    @Override
    public void paint(Graphics g) {
        super.paint(g);

        Graphics2D g2d = (Graphics2D) g;
        g2d.setStroke(new BasicStroke(2));

        drawScoreSheet(g2d, OCTAVE_3_OFFSET);
        drawScoreSheet(g2d, OCTAVE_5_OFFSET);

        for (int i = 0; i < track.size(); i++) {
            MidiEvent event = track.get(i);
            MidiMessage message = event.getMessage();

            if (message instanceof ShortMessage) {
                ShortMessage shortMessage = (ShortMessage) message;

                if (shortMessage.getCommand() == ShortMessage.NOTE_ON) {
                    int octaveOffset = (shortMessage.getData1() > 60) ? OCTAVE_5_OFFSET : OCTAVE_3_OFFSET;
                    int lineIndex = (shortMessage.getData1() % 12) / 2; // Assuming equal temperament scale

                    int x = (i + 1) * BAR_SPACING;
                    int y = octaveOffset - (lineIndex * LINE_SPACING);

                    drawNote(g2d, x, y);
                }
            }
        }
    }

    private void drawScoreSheet(Graphics2D g2d, int yOffset) {
        for (int i = 0; i < 5; i++) {
            int y = yOffset - (i * LINE_SPACING);
            g2d.drawLine(0, y, getWidth(), y);
        }
    }

    private void drawNote(Graphics2D g2d, int x, int y) {
        g2d.fillOval(x, y, NOTE_SIZE, NOTE_SIZE);
    }

    public static void main(String[] args) throws Exception {
        Sequence sequence = new Sequence(Sequence.PPQ, 24);
        Track track = sequence.createTrack();

        // Add MIDI events to the track (Example)
        track.add(createNoteOnEvent(60, 100, 0));
        track.add(createNoteOnEvent(64, 100, 96));
        track.add(createNoteOnEvent(67, 100, 192));
        track.add(createNoteOnEvent(72, 100, 288));

        MidiScoreSheet scoreSheet = new MidiScoreSheet(sequence);
    }

    private static MidiEvent createNoteOnEvent(int note, int velocity, long tick) throws InvalidMidiDataException {
        ShortMessage message = new ShortMessage();
        message.setMessage(ShortMessage.NOTE_ON, 0, note, velocity);
        return new MidiEvent(message, tick);
    }
}
