package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

func ForkReader(r io.Reader, w1, w2 io.Writer) error {
	scanner := bufio.NewScanner(r)

	// Read the input from the scanner
	scanner.Scan()
	input := scanner.Text()

	// Iterate over the input and split into two characters
	for i := 0; i < len(input); i += 2 {
		if i+2 <= len(input) {
			_, err := fmt.Fprintf(w1, "%s ", input[i:i+2])
			if err != nil {
				return err
			}
		} else {
			_, err := fmt.Fprintf(w1, "%s", input[i:])
			if err != nil {
				return err
			}
		}
	}

	// Write the whitespace separator
	_, err := fmt.Fprint(w1, " ")
	if err != nil {
		return err
	}

	// Iterate over the input and split into two characters
	for i := 1; i < len(input); i += 2 {
		if i+2 <= len(input) {
			_, err := fmt.Fprintf(w2, "%s ", input[i:i+2])
			if err != nil {
				return err
			}
		} else {
			_, err := fmt.Fprintf(w2, "%s", input[i:])
			if err != nil {
				return err
			}
		}
	}

	return nil
}

