            startCropSelection();
        } catch (Exception e) {
            System.err.println(e.getMessage());
        }
    }

    private static void startCropSelection() {
        try {
            // Create a transparent panel over the screenshot to enable selection
            final JPanel panel = new JPanel() {
                @Override
                protected void paintComponent(Graphics g) {
                    super.paintComponent(g);
                    g.setColor(new Color(255, 255, 255, 128));
                    g.fillRect(0, 0, getWidth(), getHeight());
                    if (selectRect != null) {
                        g.setColor(Color.RED);
                        ((Graphics2D) g).draw(selectRect);
                    }
                }
            };
            panel.setOpaque(false);

            // Add the panel to the frame and set content pane
            frame.setContentPane(panel);
            frame.invalidate();
            frame.validate();

            // Configure mouse listener for selection
            MouseAdapter mouseAdapter = new MouseAdapter() {
                private Point startPoint;

                @Override
                public void mousePressed(MouseEvent e) {
                    startPoint = e.getPoint();
                }

                @Override
                public void mouseReleased(MouseEvent e) {
                    startPoint = null;
                }

                @Override
                public void mouseDragged(MouseEvent e) {
                    Point currentPoint = e.getPoint();
                    int x = Math.min(startPoint.x, currentPoint.x);
                    int y = Math.min(startPoint.y, currentPoint.y);
                    int width = Math.abs(startPoint.x - currentPoint.x);
                    int height = Math.abs(startPoint.y - currentPoint.y);
                    selectRect = new Rectangle(x, y, width, height);

                    panel.repaint();
                }
            };

            // Add mouse listener to the panel
            panel.addMouseListener(mouseAdapter);
            panel.addMouseMotionListener(mouseAdapter);
        } catch (Exception e) {
            System.err.println(e.getMessage());
        }
    }

    private static void cropAndPerformOCR(Rectangle selectRect, ITesseract instance) {
        try {
            if (selectRect != null) {
                // Crop the selected region from the screenshot
                BufferedImage croppedImage = screenshot.getSubimage(selectRect.x, selectRect.y, selectRect.width, selectRect.height);

                // Perform OCR on the cropped region
                String result = instance.doOCR(croppedImage);

                // Print the result
                JOptionPane.showMessageDialog(frame, result, "OCR Result", JOptionPane.PLAIN_MESSAGE);
            } else {
                JOptionPane.showMessageDialog(frame, "Please select a region to crop.", "Error", JOptionPane.ERROR_MESSAGE);
            }
        } catch (Exception e) {
            JOptionPane.showMessageDialog(frame, e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
        }
    }
}
