import org.springframework.cloud.gateway.filter.GatewayFilter;
import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.core.Ordered;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

@Component
public class SoapGatewayFilter implements GatewayFilter, Ordered {

    private final SoapService soapService;

    public SoapGatewayFilter(SoapService soapService) {
        this.soapService = soapService;
    }

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        // Get the REST request from the exchange
        ServerHttpRequest request = exchange.getRequest();

        // Extract relevant information from the request (URL, headers, body)
        String url = request.getURI().toString();
        HttpHeaders headers = request.getHeaders();
        String body = extractRequestBody(request);

        // Make the SOAP call and get the response
        String soapResponse = soapService.invokeSoapEndpoint(url, headers, body);

        // Convert the SOAP response to HTTP
        ServerHttpResponse response = exchange.getResponse();
        response.setStatusCode(HttpStatus.OK);
        response.getHeaders().setContentType(MediaType.APPLICATION_JSON);
        response.writeWith(Mono.just(response.bufferFactory().wrap(soapResponse.getBytes())));

        // Continue processing the request
        return chain.filter(exchange);
    }

    @Override
    public int getOrder() {
        return -1; // Set the filter order
    }

    private String extractRequestBody(ServerHttpRequest request) {
        // implement logic to extract request body or payload
        // e.g., using request.getBody()
    }
