    public float tractorBeamActivationTime = 1f;

    // Reference to the tractor beam
    public TractorBeam tractorBeam;

    // Ground layer mask for checking if the player touches the ground
    public LayerMask groundLayerMask;

    // Reference to the rigidbody component
    private Rigidbody rb;

