using UnityEngine;

public class Item : MonoBehaviour
{
    public Transform destination; // The destination to drop the item off
    private bool isPickedUp = false; // Flag to track if the item is picked up

    private void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player") && !isPickedUp)
        {
            // Pick up the item
            transform.SetParent(other.transform);
            transform.localPosition = Vector3.zero;
            isPickedUp = true;
        }
    }

    private void Update()
    {
        if (isPickedUp && Input.GetKeyDown(KeyCode.Space))
        {
            DropItem();
        }
    }

    private void DropItem()
    {
        // Set the item's position to the destination
        transform.position = destination.position;
        transform.SetParent(null);
        isPickedUp = false;
    }
}
