```

5. Create a hyperlink for the image link:
```csharp
XSSFCreationHelper helper = workbook.GetCreationHelper() as XSSFCreationHelper;
IXSSFFormulaEvaluator evaluator = helper.CreateFormulaEvaluator() as XSSFFormulaEvaluator;

XSSFDrawing drawing = worksheet.CreateDrawingPatriarch() as XSSFDrawing;
XSSFClientAnchor anchor = helper.CreateClientAnchor() as XSSFClientAnchor;
anchor.AnchorType = AnchorType.MoveAndResize;

anchor.Col1 = 0; // Replace with the column index where you want the image link
anchor.Row1 = 0; // Replace with the row index where you want the image link

IDrawingPicture picture = drawing.CreatePicture(anchor, LoadPicture("path_to_your_image.png", workbook)) as IDrawingPicture;
IPictureData pictureData = picture.PictureData;

XSSFHyperlink hyperlink = helper.CreateHyperlink(HyperlinkType.Url) as XSSFHyperlink;
hyperlink.Address = "https://example.com"; // Replace with the actual URL

picture.Hyperlink = hyperlink;
```

6. Define the `LoadPicture` method to load the image file into the workbook:
```csharp
private static XSSFPictureData LoadPicture(string imagePath, XSSFWorkbook workbook)
{
    byte[] imageData = File.ReadAllBytes(imagePath);
    string pictureName = workbook.AddPicture(imageData, PictureType.PNG);

    return workbook.GetAllPictures().FirstOrDefault(x => x.PictureName == pictureName) as XSSFPictureData;
}
```

7. Save the modified workbook:
```csharp
using (FileStream file = new FileStream("path_to_save_workbook.xlsx", FileMode.Create, FileAccess.Write))
{
    workbook.Write(file);
}
