To use ExcelJS in a browser and export data to an Excel file, follow these steps:

1. Install ExcelJS using npm or download the library from a CDN. You can include it in your HTML file using a script tag:

```html
<script src="https://unpkg.com/exceljs/dist/exceljs.min.js"></script>
```

2. Create a JavaScript function that exports the data to an Excel file. Here's an example:

```javascript
function exportToExcel(data) {
  // Create a new workbook
  var workbook = new ExcelJS.Workbook();

  // Add a worksheet
  var worksheet = workbook.addWorksheet('Sheet 1');

  // Define the columns
  worksheet.columns = [
    { header: 'Name', key: 'name', width: 20 },
    { header: 'Email', key: 'email', width: 30 },
    { header: 'Age', key: 'age', width: 10 }
  ];

  // Add data to the worksheet
  data.forEach(function(row) {
    worksheet.addRow(row);
  });

  // Save the workbook as an Excel file
  workbook.xlsx.writeBuffer().then(function(buffer) {
    var blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

    // Create a download link
    var url = window.URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'data.xlsx';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  });
}
```

