Вот пример кода на C#, который реализует процедуру для подключения к SQL Server, заполнения полей структуры и выполнения отбора данных:

```csharp
public void LoadData(Parameters parameters)
{
    string connectionString = "your_connection_string_here";

    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        string query = "SELECT * FROM ADDNEWUSERS WHERE USEREMAIL = @USEREMAIL AND TELEFONE1 = @TELEFONE1 AND " +
                       "PASPORT = @PASPORT AND SERIA = @SERIA AND NOMBER = @NOMBER AND DATEOFISSUE = @DATEOFISSUE " +
                       "AND KODEP = @KODEP AND DATEOFBIRTH = @DATEOFBIRTH AND PLACEOFBIRTH = @PLACEOFBIRTH AND " +
                       "SEX = @SEX AND LASTNAME = @LASTNAME AND FIRSTNAME = @FIRSTNAME AND PATRONYMIC = @PATRONYMIC " +
                       "AND INN = @INN AND SNILS = @SNILS AND POSITION = @POSITION AND REGION = @REGION";

        SqlCommand command = new SqlCommand(query, connection);
        command.Parameters.AddWithValue("@USEREMAIL", parameters.userEmail);
        command.Parameters.AddWithValue("@TELEFONE1", parameters.telephone1);
        command.Parameters.AddWithValue("@PASPORT", parameters.passport);
        command.Parameters.AddWithValue("@SERIA", parameters.seria);
        command.Parameters.AddWithValue("@NOMBER", parameters.nomber);
        command.Parameters.AddWithValue("@DATEOFISSUE", parameters.dateOfIssue);
        command.Parameters.AddWithValue("@KODEP", parameters.kodep);
        command.Parameters.AddWithValue("@DATEOFBIRTH", parameters.dateOfBirth);
        command.Parameters.AddWithValue("@PLACEOFBIRTH", parameters.placeOfBirth);
        command.Parameters.AddWithValue("@SEX", parameters.sex);
        command.Parameters.AddWithValue("@LASTNAME", parameters.lastName);
        command.Parameters.AddWithValue("@FIRSTNAME", parameters.firstName);
        command.Parameters.AddWithValue("@PATRONYMIC", parameters.patronymic);
        command.Parameters.AddWithValue("@INN", parameters.inn);
        command.Parameters.AddWithValue("@SNILS", parameters.snils);
        command.Parameters.AddWithValue("@POSITION", parameters.position);
        command.Parameters.AddWithValue("@REGION", parameters.region);

        try
        {
            connection.Open();
            SqlDataReader reader = command.ExecuteReader();

            while (reader.Read())
            {
                // Заполнение полей структуры для найденных данных
                parameters.userEmail = reader["USEREMAIL"].ToString();
                parameters.telephone1 = reader["TELEFONE1"].ToString();
                parameters.passport = reader["PASPORT"].ToString();
                parameters.seria = reader["SERIA"].ToString();
                parameters.nomber = reader["NOMBER"].ToString();
                parameters.dateOfIssue = reader["DATEOFISSUE"].ToString();
                parameters.kodep = reader["KODEP"].ToString();
                parameters.dateOfBirth = reader["DATEOFBIRTH"].ToString();
                parameters.placeOfBirth = reader["PLACEOFBIRTH"].ToString();
                parameters.sex = reader["SEX"].ToString();
                parameters.lastName = reader["LASTNAME"].ToString();
                parameters.firstName = reader["FIRSTNAME"].ToString();
                parameters.patronymic = reader["PATRONYMIC"].ToString();
                parameters.inn = reader["INN"].ToString();
                parameters.snils = reader["SNILS"].ToString();
                parameters.position = reader["POSITION"].ToString();
                parameters.region = reader["REGION"].ToString();
            }

            reader.Close();
        }
        catch (Exception ex)
        {
            MessageBox.Show("Error: " + ex.Message);
        }
    }
}
```

