function calculateScoreGPA(score) {
  if (score >= 90) {
    return 4.0;
  } else if (score >= 85) {
    return 3.7;
  } else if (score >= 82) {
    return 3.3;
  } else if (score >= 78) {
    return 3.0;
  } else if (score >= 75) {
    return 2.7;
  } else if (score >= 72) {
    return 2.3;
  } else if (score >= 68) {
    return 2.0;
  } else if (score >= 66) {
    return 1.7;
  } else if (score >= 64) {
    return 1.3;
  } else if (score >= 60) {
    return 1.0;
  } else {
    return 0.0;
  }
}

function updateAverageGPA() {
  var courseGPAs = document.querySelectorAll("[id^='gpa_course']");
  var totalGPA = 0;
  var count = 0;

  for (var i = 0; i < courseGPAs.length; i++) {
    if (courseGPAs[i].innerText !== "") {
      totalGPA += parseFloat(courseGPAs[i].innerText);
      count++;
    }
  }

  var averageGPA = totalGPA / count;
  document.getElementById("average_gpa").innerText = averageGPA.toFixed(2);
}

