可以使用C语言的Socket库来开发一个简单的问服务器下载文件的函数。以下是一个示例代码：

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>

#define BUFFER_SIZE 1024

void downloadFile(const char* serverIP, int serverPort, const char* filePath) {
    // 创建套接字
    int clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket == -1) {
        perror("Failed to create socket");
        return;
    }

    // 设置服务器信息
    struct sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(serverPort);
    if (inet_pton(AF_INET, serverIP, &(serverAddress.sin_addr)) <= 0) {
        perror("Invalid server IP address");
        return;
    }

    // 连接服务器
    if (connect(clientSocket, (struct sockaddr*)&serverAddress, sizeof(serverAddress)) == -1) {
        perror("Failed to connect to server");
        return;
    }

    // 发送文件下载请求
    char request[BUFFER_SIZE];
    sprintf(request, "GET /%s HTTP/1.1\r\nHost: %s\r\n\r\n", filePath, serverIP);
    if (send(clientSocket, request, strlen(request), 0) == -1) {
        perror("Failed to send download request");
        return;
    }

    // 接收响应并保存文件
    FILE* file = fopen(filePath, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    char buffer[BUFFER_SIZE];
    int bytesRead;
    while ((bytesRead = recv(clientSocket, buffer, BUFFER_SIZE, 0)) > 0) {
        fwrite(buffer, 1, bytesRead, file);
    }

    fclose(file);
    close(clientSocket);
}

int main() {
    const char* serverIP = "127.0.0.1";  // 服务器IP地址
    int serverPort = 80;  // 服务器端口
    const char* filePath = "myfile.txt";  // 文件路径

    downloadFile(serverIP, serverPort, filePath);

    return 0;
}
```

