#include <atlstr.h>
#include <afxinet.h>

// 第一个参数为下载地址，第二个参数为保存在本地的文件路径
bool DownloadFile(const CString& url, const CString& filePath)
{
    CInternetSession internetSession;
    CStdioFile file;

    // 打开HTTP连接
    CInternetConnection* pConnection = internetSession.GetHttpConnection(url);
    if (pConnection == NULL) {
        return false;
    }

    // 发送GET请求
    CHttpFile* pHttpFile = pConnection->OpenRequest("GET", _T("/"), NULL, 1, NULL, NULL, INTERNET_FLAG_EXISTING_CONNECT);
    if (pHttpFile == NULL) {
        internetSession.Close();
        return false;
    }

    // 发送请求并接收响应
    if (!pHttpFile->SendRequest()) {
        pHttpFile->Close();
        internetSession.Close();
        return false;
    }

    // 获取响应状态码
    DWORD dwHttpStatus;
    pHttpFile->QueryInfoStatusCode(dwHttpStatus);
    if (dwHttpStatus != HTTP_STATUS_OK) {
        pHttpFile->Close();
        internetSession.Close();
        return false;
    }

    // 创建本地文件
    if (!file.Open(filePath, CFile::modeCreate | CFile::modeWrite | CFile::typeBinary)) {
        pHttpFile->Close();
        internetSession.Close();
        return false;
    }

    // 从HTTP响应中读取数据并写入本地文件
    char buffer[1024];
    DWORD bytesRead;
    while ((bytesRead = pHttpFile->Read(buffer, sizeof(buffer))) > 0) {
        file.Write(buffer, bytesRead);
    }

    // 关闭文件和连接
    file.Close();
    pHttpFile->Close();
    internetSession.Close();

    return true;
}
