```csharp
using System;

public class BandPassFilter
{
    // options
    private float a0;
    private float a1;
    private float a2;
    private float b1;
    private float b2;
    // state
    private float x1;
    private float x2;
    private float y1;
    private float y2;

    public void Filter(float[] signal)
    {
        for (int i = 0; i < signal.Length; i++)
        {
            float x = signal[i];
            signal[i] = a0 * x + a1 * x1 + a2 * x2 - b1 * y1 - b2 * y2;
            x2 = x1;
            x1 = x;
            y2 = y1;
            y1 = signal[i];
        }
    }

    public BandPassFilter(float sampleRate, float lowCutoff, float highCutoff)
    {
        float omegaLow = 2.0f * (float)Math.PI * lowCutoff / sampleRate;
        float omegaHigh = 2.0f * (float)Math.PI * highCutoff / sampleRate;
        float cosOmegaLow = (float)Math.Cos(omegaLow);
        float cosOmegaHigh = (float)Math.Cos(omegaHigh);
        float alphaLow = (float)Math.Sin(omegaLow) / 2.0f;
        float alphaHigh = (float)Math.Sin(omegaHigh) / 2.0f;
        a0 = 1.0f / (1.0f + alphaHigh - alphaLow);
        a1 = -2.0f * cosOmegaLow * a0;
        a2 = (1.0f - alphaHigh - alphaLow) * a0;
        b1 = -2.0f * cosOmegaHigh * a0;
        b2 = (1.0f - alphaHigh + alphaLow) * a0;
        x1 = 0.0f;
        x2 = 0.0f;
        y1 = 0.0f;
        y2 = 0.0f;
    }
}

