Это примерный код, который демонстрирует, как использовать функции из библиотеки stb_truetype.h для отображения текста на экране с использованием OpenGL. Помимо этого, вы также можете настроить масштаб, цвет и другие атрибуты рисуемого текста по своему усмотрению. Не забудьте добавить флаг `-lstb_image` при компиляции для связывания с библиотекой stb_image и флаг `-lfreetype` для связывания с библиотекой freetype.

Для изменения цвета пикселя загруженной картинки вам понадобится доступ к пиксельному буферу изображения. После изменения цвета пикселя, вы можете обновить текстуру в OpenGL с помощью функции glTexSubImage2D.

Вот пример кода, показывающий, как изменить цвет пикселя в загруженной картинке:

```cpp
#include <GL/glut.h>
#include "stb_image.h"

GLuint textureId;
int imageWidth, imageHeight, imageChannels;
unsigned char* imagePixels;

void loadImage(const char* filename) {
    imagePixels = stbi_load(filename, &imageWidth, &imageHeight, &imageChannels, 0);
    if (!imagePixels) {
        printf("Error loading image: %s\n", filename);
        return;
    }

    glGenTextures(1, &textureId);
    glBindTexture(GL_TEXTURE_2D, textureId);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);

    if (imageChannels == 3)
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGB, imageWidth, imageHeight, 0, GL_RGB, GL_UNSIGNED_BYTE, imagePixels);
    else if (imageChannels == 4)
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, imageWidth, imageHeight, 0, GL_RGBA, GL_UNSIGNED_BYTE, imagePixels);

    stbi_image_free(imagePixels);
}

void updatePixelColor(int x, int y, unsigned char r, unsigned char g, unsigned char b) {
    int index = (y * imageWidth + x) * imageChannels;
    imagePixels[index] = r;
    imagePixels[index + 1] = g;
    imagePixels[index + 2] = b;

    glBindTexture(GL_TEXTURE_2D, textureId);
    glTexSubImage2D(GL_TEXTURE_2D, 0, x, y, 1, 1, (imageChannels == 3) ? GL_RGB : GL_RGBA, GL_UNSIGNED_BYTE, imagePixels);
}

void display() {
    glClear(GL_COLOR_BUFFER_BIT);
    glEnable(GL_TEXTURE_2D);
    glBindTexture(GL_TEXTURE_2D, textureId);

    glBegin(GL_QUADS);

    glTexCoord2f(0.0f, 0.0f);
    glVertex2f(-1.0f, -1.0f);

    glTexCoord2f(1.0f, 0.0f);
    glVertex2f(1.0f, -1.0f);

    glTexCoord2f(1.0f, 1.0f);
    glVertex2f(1.0f, 1.0f);

    glTexCoord2f(0.0f, 1.0f);
    glVertex2f(-1.0f, 1.0f);

    glEnd();

    glutSwapBuffers();
    glDisable(GL_TEXTURE_2D);
}

int main(int argc, char** argv) {
    glutInit(&argc, argv);
    glutInitDisplayMode(GLUT_DOUBLE | GLUT_RGB);
    glutInitWindowSize(500, 500);
    glutCreateWindow("OpenGL Texture");
    glutDisplayFunc(display);

    loadImage("image.png");

    // Изменение цвета пикселя (x = 100, y = 100) на красный
    updatePixelColor(100, 100, 255, 0, 0);

    glutMainLoop();

    return 0;
}
```

В этом примере функция `updatePixelColor` позволяет изменять цвет пикселя в массиве `imagePixels` по указанным координатам (x, y). Затем она обновляет текстуру в OpenGL с помощью `glTexSubImage2D`, чтобы отобразить изменения на экране.

Обратите внимание, что изменения цвета пикселя происходят в массиве `imagePixels`, и эти изменения могут быть видны только после обновления текстуры в OpenGL.

