To disable verification when using libcurl, you can use the CURLOPT_SSL_VERIFYPEER and CURLOPT_SSL_VERIFYHOST options with the curl_easy_setopt() function. Here's an example:

```c++
#include <iostream>
#include <curl/curl.h>

int main() {
    CURL* curl = curl_easy_init();
    if (curl) {
        // Disable peer verification
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);

        // Disable hostname verification
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);

        // Rest of the curl_easy_setopt() calls

        // Execute the request
        CURLcode res = curl_easy_perform(curl);

        // Check for errors
        if (res != CURLE_OK) {
