    // Create a CURL object
    CURL* curl = curl_easy_init();
    if (curl)
    {
        std::string url = "https://idfs.gs.com/as/token.oauth2";
        std::string grantType = "grant_type=client_credentials";
        std::string clientId = "client_id=YOUR_CLIENT_ID";
        std::string clientSecret = "client_secret=YOUR_CLIENT_SECRET";
        std::string scope = "scope=read_content read_financial_data read_product_data read_user_profile";

        // Set the request URL
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());

        // Set the request headers
        struct curl_slist* headers = nullptr;
        headers = curl_slist_append(headers, "Content-Type: application/x-www-form-urlencoded");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Set the request method to POST
        curl_easy_setopt(curl, CURLOPT_POST, 1L);

        // Set the request data
        std::string requestData = grantType + "&" + clientId + "&" + clientSecret + "&" + scope;
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, requestData.c_str());
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, requestData.length());

        // Perform the request
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK)
        {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
        }

        // Cleanup
