    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2d = (Graphics2D) g;

        // Draw a black background
        g2d.setColor(Color.BLACK);
        g2d.fillRect(0, 0, getWidth(), getHeight());

        // Draw health bar
        drawBar(g2d, "Health", health, maxHealth, 20);

        // Draw mana bar
        drawBar(g2d, "Mana", mana, maxMana, 60);

        // Draw energy bar
        drawBar(g2d, "Energy", energy, maxEnergy, 100);

        // Draw strength
        drawStat(g2d, "Strength", strength, 20, 140);

        // Draw dexterity
        drawStat(g2d, "Dexterity", dexterity, 20, 160);

        // Draw intelligence
        drawStat(g2d, "Intelligence", intelligence, 180, 140);

        // Draw luck
        drawStat(g2d, "Luck", luck, 180, 160);
    }

    private void drawBar(Graphics2D g2d, String text, int value, int maxValue, int y) {
