        int fillWidth = (int) ((double) value / maxValue * getWidth() * 0.8);

        // Draw the text
        g2d.setColor(Color.WHITE);
        g2d.drawString(text, 20, y + 10);

        // Draw the empty bar
        g2d.setColor(Color.GRAY);
        g2d.fillRect(120, y, getWidth() - 140, 20);

        // Draw the filled bar
        g2d.setColor(Color.GREEN);
        g2d.fillRect(120, y, fillWidth, 20);
    }

    private void drawStat(Graphics2D g2d, String text, int value, int x, int y) {
        // Draw the text
        g2d.setColor(Color.WHITE);
        g2d.drawString(text + ": " + value, x, y);
