import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.reactive.function.client.ExchangeFilterFunction;
import org.springframework.web.reactive.function.client.WebClient;

@Configuration
public class WebClientConfig {

    @Autowired
    private JmsTemplate jmsTemplate;

    @Bean
    public WebClient jmsWebClient() {
        return WebClient.builder()
                .baseUrl("jms:/") // Configure the base URL for JMS requests
                .filter(jmsExchangeFilterFunction()) // Register the custom ExchangeFilterFunction
                .build();
    }

    @Bean
    public ExchangeFilterFunction jmsExchangeFilterFunction() {
        return (request, next) -> {
            String soapRequest = request.bodyToMono(String.class).block();
            jmsTemplate.send(session -> session.createTextMessage(soapRequest));
            return next.exchange(request);
        };
    }
}
```

