В этом коде мы добавляем локальную переменную `model`, которая ссылается на модель данных, чтобы вызвать метод `setData`. Это необходимо, потому что `index.model()` возвращает константный указатель на `QAbstractItemModel`, и `setData` не может быть вызван на константной модели данных. Переменная `model` является неконстантной и позволяет вызвать неконстантный метод `setData`.

Для реализации выбора файлов с использованием `QFileSystemModel` и `QTableView` с колонкой флажков (QCheckBox), вам понадобится создать кастомную модель для таблицы и добавить колонку с флажками. 

Вот пример кода, который демонстрирует реализацию этой функциональности:

```cpp
#include <QtWidgets>

class FileTableModel : public QAbstractTableModel
{
public:
    FileTableModel(QObject *parent = nullptr)
        : QAbstractTableModel(parent)
    {
    }

    void setFileSystemModel(QFileSystemModel *fileSystemModel)
    {
        beginResetModel();
        m_fileSystemModel = fileSystemModel;
        endResetModel();
    }

    int rowCount(const QModelIndex &parent = QModelIndex()) const override
    {
        Q_UNUSED(parent);
        return m_fileSystemModel ? m_fileSystemModel->rowCount() : 0;
    }

    int columnCount(const QModelIndex &parent = QModelIndex()) const override
    {
        Q_UNUSED(parent);
        return m_fileSystemModel ? m_fileSystemModel->columnCount() + 1 : 0;
    }

    QVariant data(const QModelIndex &index, int role = Qt::DisplayRole) const override
    {
        if (!index.isValid())
            return QVariant();

        if (index.column() == 0 && role == Qt::CheckStateRole) {
            return m_selectedFiles.contains(m_fileSystemModel->filePath(index))
                    ? Qt::Checked : Qt::Unchecked;
        }

        if (index.column() > 0)
            return m_fileSystemModel->data(index.sibling(index.row(), index.column() - 1), role);

        return QVariant();
    }

    QVariant headerData(int section, Qt::Orientation orientation, int role = Qt::DisplayRole) const override
    {
        if (section == 0 && orientation == Qt::Horizontal && role == Qt::DisplayRole)
            return "";

        if (section > 0) {
            return m_fileSystemModel->headerData(section - 1, orientation, role);
        }

        return QVariant();
    }

    Qt::ItemFlags flags(const QModelIndex &index) const override
    {
        if (!index.isValid())
            return Qt::NoItemFlags;

        Qt::ItemFlags flags = Qt::ItemIsEnabled;

        if (index.column() == 0)
            flags |= Qt::ItemIsUserCheckable;

        return flags;
    }

    bool setData(const QModelIndex &index, const QVariant &value, int role = Qt::EditRole) override
    {
        if (!index.isValid())
            return false;

        if (index.column() == 0 && role == Qt::CheckStateRole) {
            if (value == Qt::Checked)
                m_selectedFiles.insert(m_fileSystemModel->filePath(index));
            else
                m_selectedFiles.remove(m_fileSystemModel->filePath(index));

            emit dataChanged(index, index, {role});
            return true;
        }

        return false;
    }

    QStringList getSelectedFiles() const
    {
        return m_selectedFiles.toList();
    }

private:
    QFileSystemModel *m_fileSystemModel = nullptr;
    QSet<QString> m_selectedFiles;
};

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    QFileSystemModel fileSystemModel;

    FileTableModel tableModel;
    tableModel.setFileSystemModel(&fileSystemModel);

    QTableView tableView;
    tableView.setModel(&tableModel);
    tableView.setSelectionBehavior(QAbstractItemView::SelectRows);
    tableView.setShowGrid(false);
    tableView.horizontalHeader()->setStretchLastSection(true);
    tableView.verticalHeader()->setVisible(false);
    tableView.verticalHeader()->setDefaultSectionSize(tableView.fontMetrics().height());
    tableView.setSortingEnabled(true);

    QMainWindow mainWindow;
    mainWindow.setCentralWidget(&tableView);
    mainWindow.resize(800, 600);
    mainWindow.show();

    return app.exec();
}
```

В этом коде мы создаем класс `FileTableModel`, который наследуется от `QAbstractTableModel` и предоставляет модель данных для таблицы

