#include <iostream>

double calculatePower(double a, int n) {
    double result = 1.0;

    if (n == 0)
        return result;

    if (n > 0) {
        while (n > 0) {
            if (n & 1)
                result *= a;
            a *= a;
            n >>= 1;
        }
    } else {
        while (n < 0) {
            if (n & 1)
                result /= a;
            a *= a;
            n >>= 1;
        }
    }

