```rust
use mysql::*;
use mysql::prelude::*;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create a MySQL connection pool
    let pool = Pool::new(
        // MySQL connection options
        mysql::Opts::from_url("mysql://user:password@localhost:3306/database")?,
    )?;

