#include <stdbool.h>
#include <unistd.h>
#include <pthread.h>

// Structure representing a task
typedef struct task {
    int id;
    bool condition_met;
    struct task* next;
} task_t;

// Structure representing a wait queue entry
typedef struct wait_queue_entry {
    task_t* task;
    struct wait_queue_entry* next;
} wait_queue_entry_t;

// Structure representing the head of a wait queue
typedef struct wait_queue_head {
    wait_queue_entry_t* head;
    pthread_mutex_t lock;
} wait_queue_head_t;

// Initialize a wait queue head
void init_waitqueue_head(wait_queue_head_t* wq_head) {
    wq_head->head = NULL;
    pthread_mutex_init(&(wq_head->lock), NULL);
}

// Initialize a wait queue entry
void init_waitqueue_entry(wait_queue_entry_t* wq_entry, task_t* task) {
    wq_entry->task = task;
    wq_entry->next = NULL;
}

// Add a task to the wait queue
void add_wait_queue(wait_queue_head_t* wq_head, wait_queue_entry_t* wq_entry) {
    pthread_mutex_lock(&(wq_head->lock));

    if (wq_head->head == NULL) {
        wq_head->head = wq_entry;
    } else {
        wait_queue_entry_t* current = wq_head->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = wq_entry;
    }

    pthread_mutex_unlock(&(wq_head->lock));
}

// Wake up a waiting task in the wait queue
void wake_up(wait_queue_head_t* wq_head) {
    pthread_mutex_lock(&(wq_head->lock));

    if (wq_head->head != NULL) {
        task_t* task = wq_head->head->task;
        wq_head->head = wq_head->head->next;
        printf("Task with ID %d woken up.\n", task->id);
        free(task);
    }

    pthread_mutex_unlock(&(wq_head->lock));
}

// Wake up all waiting tasks in the wait queue
void wake_up_all(wait_queue_head_t* wq_head) {
    pthread_mutex_lock(&(wq_head->lock));

    while (wq_head->head != NULL) {
        task_t* task = wq_head->head->task;
        wq_head->head = wq_head->head->next;
        printf("Task with ID %d woken up.\n", task->id);
        free(task);
    }

    pthread_mutex_unlock(&(wq_head->lock));
}

// Wait until the specified condition is met
void wait_event(wait_queue_head_t* wq_head, bool* condition) {
    task_t* task = (task_t*)malloc(sizeof(task_t));
    task->id = getpid();
    task->condition_met = *condition;
    task->next = NULL;

    wait_queue_entry_t* wq_entry = (wait_queue_entry_t*)malloc(sizeof(wait_queue_entry_t));
    init_waitqueue_entry(wq_entry, task);

    add_wait_queue(wq_head, wq_entry);

    while (!task->condition_met) {
        sleep(1);
    }

    printf("Task with ID %d resumed.\n", task->id);

    free(wq_entry);
    free(task);
}

// Wait until the specified condition is met or timeout occurs
void wait_event_timeout(wait_queue_head_t* wq_head, bool* condition, int timeout_ms) {
    task_t* task = (task_t*)malloc(sizeof(task_t));
    task->id = getpid();
    task->condition_met = *condition;
    task->next = NULL;

    wait_queue_entry_t* wq_entry = (wait_queue_entry_t*)malloc(sizeof(wait_queue_entry_t));
    init_waitqueue_entry(wq_entry, task);

    add_wait_queue(wq_head, wq_entry);

    int timeout = timeout_ms / 1000;
    int remaining = timeout_ms % 1000;
    while (!task->condition_met && timeout > 0) {
        sleep(1);
        timeout--;
    }
    usleep(remaining);

    if (!task->condition_met) {
        printf("Task with ID %d timed out.\n", task->id);
    } else {
        printf("Task with ID %d resumed.\n", task->id);
    }

    free(wq_entry);
    free(task);
}

// Example usage
bool condition = false;
wait_queue_head_t wq_head;

void* task1(void* arg) {
    usleep(2000);
    condition = true;
    wake_up_all(&wq_head);
    return NULL;
}

int main() {
    init_waitqueue_head(&wq_head);

    pthread_t task_thread;
    pthread_create(&task_thread, NULL, task1, NULL);

    printf("Main thread waiting...\n");
    wait_event(&wq_head, &condition);

    pthread_join(task_thread, NULL);

    return 0;
}
```

Here, we create a wait queue with the `wait_queue_head_t` structure. The wait queue holds `wait_queue_entry_t` structures, each containing a reference to a task that is waiting. The functions `init_waitqueue_head()`, `init_waitqueue_entry()`, `add_wait_queue()`, `wake_up()`, and `wake_up_all()` are implemented to initialize and manipulate the wait queue.

The `wait_event()` and `wait_event_timeout()` functions are provided to allow a task to wait until a condition is met or a timeout occurs. The tasks are put to sleep using the `sleep()` and `usleep()` functions, depending on whether a timeout is specified or not. Once the condition is met or the timeout occurs, the task is awakened using `wake_up()` or `wake_up_all()`.

In the example usage, we have a main thread waiting for the `condition` to change. Another thread (`task1`) changes the `condition` after a delay and then wakes up all the tasks waiting on the wait queue. The main thread resumes execution and the program terminates.

Please note that this is a simplified implementation and that in a real Linux kernel, the wait queue functionality is more complex and tightly integrated with the overall kernel architecture.

