```c
#include <stdio.h>
#include <stdbool.h>
#include "FreeRTOS.h"
#include "task.h"
#include "semphr.h"

// Structure representing a task
typedef struct task {
    int id;
    bool condition_met;
} task_t;

// Binary semaphore to control access to the wait queue
SemaphoreHandle_t wait_queue_mutex;

// Binary semaphore to wait for a condition to be met
SemaphoreHandle_t condition_sem;

// Wait queue entry
task_t* wait_queue_entry;

// Initialize the wait queue
void init_wait_queue() {
    wait_queue_mutex = xSemaphoreCreateMutex();
    condition_sem = xSemaphoreCreateBinary();
    wait_queue_entry = NULL;
}

// Add a task to the wait queue
void add_wait_queue(task_t* task) {
    xSemaphoreTake(wait_queue_mutex, portMAX_DELAY);

    task_t* current = wait_queue_entry;

    if (current == NULL) {
        wait_queue_entry = task;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = task;
    }

    xSemaphoreGive(wait_queue_mutex);
}

// Wake up a waiting task from the wait queue
void wake_up() {
    xSemaphoreTake(wait_queue_mutex, portMAX_DELAY);

    if (wait_queue_entry != NULL) {
        task_t* task = wait_queue_entry;
        wait_queue_entry = wait_queue_entry->next;
        printf("Task with ID %d woken up.\n", task->id);
        vPortFree(task);
    }

    xSemaphoreGive(wait_queue_mutex);
}

// Wait until the specified condition is met
void wait_event(bool* condition) {
    xSemaphoreTake(wait_queue_mutex, portMAX_DELAY);

    task_t* task = (task_t*)pvPortMalloc(sizeof(task_t));
    task->id = uxTaskPriorityGet(NULL);  
    task->condition_met = *condition;
    task->next = NULL;

    add_wait_queue(task);

    xSemaphoreGive(wait_queue_mutex);

    while (!task->condition_met) {
        xSemaphoreTake(condition_sem, portMAX_DELAY);
    }

    printf("Task with ID %d resumed.\n", task->id);

    vPortFree(task);
}

// Set the condition and wake up all waiting tasks
void set_condition_and_wake_up_all(bool* condition) {
    xSemaphoreTake(wait_queue_mutex, portMAX_DELAY);

    *condition = true;

    while (wait_queue_entry != NULL) {
        task_t* task = wait_queue_entry;
        wait_queue_entry = wait_queue_entry->next;
        printf("Task with ID %d woken up.\n", task->id);
        xSemaphoreGive(condition_sem);
        vPortFree(task);
    }

    xSemaphoreGive(wait_queue_mutex);
}

// Example task that waits for a condition
void task1(void* pvParameters) {
    bool condition = false;

    printf("Task 1 waiting...\n");
    wait_event(&condition);

    // Continue with other operations
    printf("Task 1 continues...\n");

    vTaskDelete(NULL);
}

// Example task that sets the condition and wakes up waiting tasks
void task2(void* pvParameters) {
    // Simulate some delay before setting the condition
    vTaskDelay(2000 / portTICK_PERIOD_MS);

    printf("Task 2 sets condition and wakes up waiting tasks.\n");
    set_condition_and_wake_up_all(&condition);

    vTaskDelete(NULL);
}

int main(void) {
    init_wait_queue();

    xTaskCreate(task1, "Task 1", configMINIMAL_STACK_SIZE, NULL, tskIDLE_PRIORITY + 1, NULL);
    xTaskCreate(task2, "Task 2", configMINIMAL_STACK_SIZE, NULL, tskIDLE_PRIORITY + 2, NULL);

    vTaskStartScheduler();

    return 0;
}
```

In this example, we create a wait queue using a binary semaphore (`wait_queue_mutex`) to control access to the queue. We also create a binary semaphore (`condition_sem`) to allow waiting tasks to suspend and wait for a condition to be met.

The `add_wait_queue()` function adds a task to the wait queue, and the `wake_up()` function wakes up the first task in the wait queue.

The `wait_event()` function waits for a condition to be met. It creates a task structure, adds it to the wait queue, and then waits on the `condition_sem` until the condition is set by another task.

The `set_condition_and_wake_up_all()` function sets the condition and wakes up all waiting tasks. It iterates through the wait queue, waking up each task by giving a `condition_sem` semaphore.

Finally, we have `task1` and `task2` that demonstrate the usage of the wait queue. `task1` waits for the condition to be met using `wait_event()`, and `task2` sets the condition and wakes up the waiting tasks using `set_condition_and_wake_up_all()`.

Please note that this implementation assumes you have FreeRTOS properly configured and running on your target device. Adjustments may be required to match your specific environment and configuration.

