int motorSpeed = 1000;           

// Define the step sequence for the stepper motor
int stepSequence[][4] = {
  {HIGH, LOW, LOW, LOW},
  {LOW, HIGH, LOW, LOW},
  {LOW, LOW, HIGH, LOW},
  {LOW, LOW, LOW, HIGH}
};

void setup() {
  // Configure the stepper motor pins as outputs
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);
}

void loop() {
  // Rotate the stepper motor clockwise for one revolution
  for (int i = 0; i < stepsPerRevolution; i++) {
    stepForward();
    delay(motorSpeed);
  }
  delay(1000);  // Pause for one second

  // Rotate the stepper motor counterclockwise for one revolution
  for (int i = 0; i < stepsPerRevolution; i++) {
    stepBackward();
    delay(motorSpeed);
  }
  delay(1000);  // Pause for one second
}

// Function to perform one step forward sequence
