  for (int i = 0; i < 4; i++) {
    digitalWrite(IN1, stepSequence[i][0]);
    digitalWrite(IN2, stepSequence[i][1]);
    digitalWrite(IN3, stepSequence[i][2]);
    digitalWrite(IN4, stepSequence[i][3]);
  }
}

// Function to perform one step backward sequence
void stepBackward() {
  for (int i = 3; i >= 0; i--) {
    digitalWrite(IN1, stepSequence[i][0]);
    digitalWrite(IN2, stepSequence[i][1]);
    digitalWrite(IN3, stepSequence[i][2]);
    digitalWrite(IN4, stepSequence[i][3]);
  }
}
