class Program
{
    static void Main(string[] args)
    {
        // Example usage
        var lineSegment = new List<Point>
        {
            new Point { X = 1, Y = 1 },
            new Point { X = 2, Y = 3 },
            new Point { X = 4, Y = 5 },
            new Point { X = 7, Y = 4 },
