        {
            Console.WriteLine($"X: {point.X}, Y: {point.Y}");
        }
    }

    static List<Point> ConvertToSmoothCurve(List<Point> lineSegment, double precision)
    {
        if (lineSegment.Count < 2)
        {
            return lineSegment;
        }

        var smoothCurve = new List<Point>();

        var points = lineSegment;

        while (CalculateAverageDistance(points) > precision)
        {
            var newPoints = new List<Point>();

            for (int i = 0; i < points.Count - 1; i++)
            {
                var p0 = points[i];
                var p1 = points[i + 1];

                var q0 = new Point
                {
                    X = (3 * p0.X + p1.X) / 4,
                    Y = (3 * p0.Y + p1.Y) / 4
                };

                var q1 = new Point
                {
                    X = (p0.X + 3 * p1.X) / 4,
                    Y = (p0.Y + 3 * p1.Y) / 4
                };

                newPoints.Add(q0);
                newPoints.Add(q1);
            }

            newPoints.Add(points[points.Count - 1]);

            points = newPoints;
        }

        smoothCurve.AddRange(points);
        return smoothCurve;
    }

    static double CalculateDistance(Point p1, Point p2)
    {
        double deltaX = p2.X - p1.X;
        double deltaY = p2.Y - p1.Y;
        return Math.Sqrt(deltaX * deltaX + deltaY * deltaY);
    }

    static double CalculateAverageDistance(List<Point> points)
    {
        double totalDistance = 0;

        for (int i = 0; i < points.Count - 1; i++)
        {
            var p1 = points[i];
            var p2 = points[i + 1];
            totalDistance += CalculateDistance(p1, p2);
