        {
            new Point { X = 1, Y = 1 },
            new Point { X = 2, Y = 3 },
            new Point { X = 4, Y = 5 },
            new Point { X = 7, Y = 4 },
            new Point { X = 9, Y = 2 }
        };

        var smoothCurve = ConvertToSmoothCurve(lineSegment, 0.5); // Specify the curve precision

        Console.WriteLine("Smooth Curve:");
        foreach (var point in smoothCurve)
        {
            Console.WriteLine($"X: {point.X}, Y: {point.Y}");
        }
    }

    static List<Point> ConvertToSmoothCurve(List<Point> lineSegment, double precision)
    {
        if (lineSegment.Count < 2)
        {
            return lineSegment;
        }

        var smoothCurve = new List<Point>();

        var points = lineSegment;

        while (CalculateAverageDistance(points) > precision)
        {
            var newPoints = new List<Point>();

            for (int i = 0; i < points.Count - 1; i++)
            {
                var p0 = points[i];
                var p1 = points[i + 1];

                if (CanConvertToBezier(p0, p1))
                {
                    var controlPoint1 = new Point
                    {
                        X = (2 * p0.X + p1.X) / 3,
                        Y = (2 * p0.Y + p1.Y) / 3
                    };

                    var controlPoint2 = new Point
                    {
                        X = (p0.X + 2 * p1.X) / 3,
                        Y = (p0.Y + 2 * p1.Y) / 3
                    };

                    newPoints.Add(p0);
                    newPoints.Add(controlPoint1);
                    newPoints.Add(controlPoint2);
                    newPoints.Add(p1);
                }
                else
                {
                    newPoints.Add(p0);
                    newPoints.Add(p1);
                }
            }

            newPoints.Add(points[points.Count - 1]);

            points = newPoints;
        }

        smoothCurve.AddRange(points);
        return smoothCurve;
    }

    static bool CanConvertToBezier(Point p0, Point p1)
    {
        return Math.Abs(p1.X - p0.X) >= 2 || Math.Abs(p1.Y - p0.Y) >= 2;
    }

    static double CalculateDistance(Point p1, Point p2)
    {
        double deltaX = p2.X - p1.X;
        double deltaY = p2.Y - p1.Y;
        return Math.Sqrt(deltaX * deltaX + deltaY * deltaY);
    }

    static double CalculateAverageDistance(List<Point> points)
    {
        double totalDistance = 0;

        for (int i = 0; i < points.Count - 1; i++)
        {
            var p1 = points[i];
            var p2 = points[i + 1];
            totalDistance += CalculateDistance(p1, p2);
        }

        return totalDistance / (points.Count - 1);
    }
}

class Point
{
    public double X { get; set; }
    public double Y { get; set; }
}
