В этом коде атрибут `onsubmit="return false;"` добавлен к форме с `id="myForm"`. Теперь при отправке формы, данные сохраняются в `localStorage` и форма не отправляется на сервер, предотвращая обновление страницы.

Да, можно установить время действия данных в `localStorage`, после которого они будут исчезать. Для этого можно использовать метод `setTimeout` для задержки выполнения кода и метод `localStorage.removeItem` для удаления данных из `localStorage`.

Вот обновленный код, который удалит сохраненные данные через определенное время:

```javascript
window.onload = function() {
  var savedData = localStorage.getItem("savedData");
  if (savedData) {
    savedData = JSON.parse(savedData);
    document.getElementById("name").value = savedData["ФИО"];
    document.getElementById("age").value = savedData["Возраст"];
    document.getElementById("city").value = savedData["Город"];
    document.getElementById("company").value = savedData["Компания"];
    document.getElementById("email").value = savedData["Электронная почта"];
    document.getElementById("tel").value = savedData["Телефон"];
    document.getElementById("comment").value = savedData["Описание компетенций и опыта"];
  }

  document.getElementById("myForm").onsubmit = function() {
    var name = document.getElementById("name").value;
    var age = document.getElementById("age").value;
    var city = document.getElementById("city").value;
    var company = document.getElementById("company").value;
    var email = document.getElementById("email").value;
    var tel = document.getElementById("tel").value;
    var comment = document.getElementById("comment").value;

    if (name === "" || age === "" || city === "" || company === "" || email === "" || tel === "" || comment === "") {
      alert("Пожалуйста, заполните все поля.");
    } else {
      alert("Данные успешно сохранены");
      var savedData = {
        "ФИО": name,
        "Возраст": age,
        "Город": city,
        "Компания": company,
        "Электронная почта": email,
        "Телефон": tel,
        "Описание компетенций и опыта": comment
      };
      localStorage.setItem("savedData", JSON.stringify(savedData));

      // Устанавливаем время действия данных (в данном примере - 1 минута)
      var expirationTime = 1 * 60 * 1000; // 1 минута
      setTimeout(function() {
        localStorage.removeItem("savedData");
      }, expirationTime);
    }
    return false;
  };
