    res := 0

    for i := range height {
        if len(stack) == 0 {
            stack = append(stack, i)
            continue
        }

        curValue := height[i]

        for len(stack) != 0 && curValue >= height[stack[len(stack)-1]] {
            popValue := height[stack[len(stack)-1]]
            stack = stack[:len(stack)-1]

            if len(stack) == 0 {
                break
            }

            res += (min(height[stack[len(stack)-1]], curValue) - popValue) * (i - stack[len(stack)-1] - 1)
        }

        stack = append(stack, i)
    }

