public int trap(int[] height) {
    int res = 0;
    int[] stack = new int[height.length];
    int top = -1;

    for (int i = 0; i < height.length; i++) {
        if (top == -1) {
            stack[++top] = i;
            continue;
        }

        int curValue = height[i];

        while (top != -1 && curValue >= height[stack[top]]) {
            int popValue = height[stack[top--]];

            if (top == -1) {
                break;
            }

            res += (Math.min(height[stack[top]], curValue) - popValue) * (i - stack[top] - 1);
        }

        stack[++top] = i;
    }

    return res;
}

