import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
import org.springframework.context.annotation.Scope;

@Configuration
@EnableConfigurationProperties(SentryProperties.class)
public class SentryConfig {

    @Value("${sentry.environment}")
    private String sentryEnvironment;

    @Value("${sentry.dsn}")
    private String sentryDsn;

    @Bean
    @Profile("stand1")
    @Scope(ConfigurableBeanFactory.SCOPE_SINGLETON)
    public io.sentry.config.Config stand1SentryConfig(SentryProperties sentryProperties) {
        sentryProperties.setEnvironment(sentryEnvironment);
        sentryProperties.setDsn(sentryDsn);
        return sentryProperties.get();
    }

