	hr = pITask->SetApplicationName(TEXT("path\\to\\your\\application.exe"));
	if (FAILED(hr))
	{
		pITask->Release();
		pITaskScheduler->Release();
		return 0;
	}

	WORD triggerIndex;
	hr = pITask->CreateTrigger(&triggerIndex, NULL);
	if (FAILED(hr))
	{
		pITask->Release();
		pITaskScheduler->Release();
		return 0;
