```cpp
#include <shlwapi.h>

// Функция для чтения значения из ключа реестра автозагрузки
std::wstring ReadAutorunValue()
{
    HKEY hKey;
    LPCWSTR subKey = L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Run";
    LPCWSTR valueName = L"MyApp";
    WCHAR valueData[MAX_PATH];
    DWORD dataSize = sizeof(valueData);

    // Открытие ключа реестра
    if (RegOpenKeyEx(HKEY_CURRENT_USER, subKey, 0, KEY_QUERY_VALUE, &hKey) == ERROR_SUCCESS)
    {
        // Чтение значения из ключа реестра
        if (RegQueryValueEx(hKey, valueName, 0, NULL, (BYTE*)valueData, &dataSize) == ERROR_SUCCESS)
        {
            RegCloseKey(hKey);
            return std::wstring(valueData);
        }
        else
        {
            RegCloseKey(hKey);
        }
    }

    return L"";
}

