        this.name = name;
        this.maxSize = maxSize;
        this.customers = new Customer[maxSize];
        this.size = 0;
    }

    public String getName() {
        return name;
    }

    public boolean isFull() {
        return size == maxSize;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public void addCustomer(Customer customer) {
        if (!isFull()) {
            customers[size] = customer;
            size++;
            System.out.println("Customer added to " + name + " queue.");
        } else {
            System.out.println(name + " queue is already full.");
        }
    }

    public void removeCustomer(int index) {
        if (index >= 0 && index < size) {
            for (int i = index; i < size - 1; i++) {
                customers[i] = customers[i + 1];
            }
            customers[size - 1] = null;
            size--;
            System.out.println("Customer removed from " + name + " queue.");
        } else {
            System.out.println("Invalid customer index.");
        }
    }

    public int getLength() {
        return size;
    }

    public double getIncome() {
        double income = 0;
        for (int i = 0; i < size; i++) {
