```javascript
// Variables
const dropArea = document.getElementById('drop-area');
const inputElem = document.getElementById('fileElem');
const imagePreview = document.getElementById('image-preview');
const uploadButton = document.getElementById('upload-button');
let images = [];

// Drag and Drop functionality
dropArea.addEventListener('dragover', (e) => {
  e.preventDefault();
  dropArea.classList.add('highlight');
});

dropArea.addEventListener('dragleave', () => {
  dropArea.classList.remove('highlight');
});

dropArea.addEventListener('drop', (e) => {
  e.preventDefault();
  dropArea.classList.remove('highlight');
  const files = Array.from(e.dataTransfer.files);
  handleFiles(files);
});

// Image Selection functionality
inputElem.addEventListener('change', () => {
  const files = Array.from(inputElem.files);
  handleFiles(files);
});

// Handle selected files
function handleFiles(files) {
  files.forEach((file) => {
    if (file.type.match('image.*')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const image = new Image();
        image.src = e.target.result;
        image.classList.add('preview-image');
        image.addEventListener('click', () => {
          replaceImage(image);
        });
        const order = document.createElement('div');
        order.classList.add('order');
        order.innerHTML = images.length + 1;
        image.appendChild(order);
        const deleteIcon = document.createElement('div');
        deleteIcon.classList.add('delete-icon');
        deleteIcon.addEventListener('click', () => {
          deleteImage(image);
        });
        image.appendChild(deleteIcon);
        images.push(image);
        imagePreview.appendChild(image);
      }
      reader.readAsDataURL(file);
    }
  });
}

// Replace Image
function replaceImage(image) {
  const fileElem = document.createElement('input');
  fileElem.type = 'file';
  fileElem.accept = 'image/*';
  fileElem.addEventListener('change', () => {
    const file = fileElem.files[0];
    if (file.type.match('image.*')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        image.src = e.target.result;
      }
      reader.readAsDataURL(file);
    }
  });
  fileElem.click();
}

// Delete Image
function deleteImage(image) {
  const index = images.indexOf(image);
  images.splice(index, 1);
  image.remove();
}

// Upload Images
uploadButton.addEventListener('click', () => {
  if (images.length < 1 || images.length > 12) {
    alert('Please select minimum 1 and maximum 12 images.');
    return;
  }
  // Implement PHP backend to handle image upload and MySQL database insertion.
});
