using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;

namespace CalendarApp
{
    public partial class MainWindow : Window
    {
        private DateTime currentDate;

        public MainWindow()
        {
            InitializeComponent();
            currentDate = DateTime.Now;
            UpdateCalendar();
        }

        private void PreviousButton_Click(object sender, RoutedEventArgs e)
        {
            currentDate = currentDate.AddMonths(-1);
            UpdateCalendar();
        }

        private void NextButton_Click(object sender, RoutedEventArgs e)
        {
            currentDate = currentDate.AddMonths(1);
            UpdateCalendar();
        }

        private void DayButton_Click(object sender, RoutedEventArgs e)
        {
            Button clickedButton = (Button)sender;
            MessageBox.Show(clickedButton.Content.ToString(), "Selected Date");
        }

        private void UpdateCalendar()
        {
            List<string> calendarData = new List<string>();

            // Get the first day of the month
            DateTime firstDayOfMonth = new DateTime(currentDate.Year, currentDate.Month, 1);
            int daysInMonth = DateTime.DaysInMonth(currentDate.Year, currentDate.Month);

            // Add empty strings for days before the first day of the month
            for (int i = 1; i < (int)firstDayOfMonth.DayOfWeek; i++)
            {
                calendarData.Add("");
            }

            // Add days of the month
            for (int day = 1; day <= daysInMonth; day++)
            {
                calendarData.Add(day.ToString());
            }

            // Update the month and year displayed in the text block
            MonthYearTextBlock.Text = currentDate.ToString("MMMM, yyyy");
            CalendarListView.ItemsSource = calendarData;
        }
    }
}
