using System.Windows;
using System.Windows.Input;
using System.Windows.Media.Media3D;

namespace Parallax3D
{
    public partial class MainWindow : Window
    {
        private double mouseX;
        private double mouseY;

        public MainWindow()
        {
            InitializeComponent();
        }

        private void Window_MouseMove(object sender, MouseEventArgs e)
        {
            mouseX = e.GetPosition(Canvas3D).X;
            mouseY = e.GetPosition(Canvas3D).Y;

            UpdateLayers();
        }

        private void UpdateLayers()
        {
            // Calculate parallax effect for each layer
            double centerX = Canvas3D.ActualWidth / 2;
            double centerY = Canvas3D.ActualHeight / 2;

            TransformLayer(Layer1, mouseX / centerX - 0.5, mouseY / centerY - 0.5, 0);
            TransformLayer(Layer2, mouseX / centerX - 0.2, mouseY / centerY - 0.2, -100);
            TransformLayer(Layer3, mouseX / centerX - 0.1, mouseY / centerY - 0.1, -200);
        }

        private void TransformLayer(UIElement layer, double translateX, double translateY, double translateZ)
        {
            layer.Transform = new Transform3DGroup
            {
                Children = new Transform3DCollection
                {
                    new TranslateTransform3D(translateX, translateY, translateZ)
                }
            };
        }
    }
}
```

In this version, I simplified the update of layers by directly calculating the parallax effect for the translation values. It reduces the repetitive variable declarations and improves readability. Additionally, I simplified the `TransformLayer` method by directly creating and assigning the `Transform3DGroup` with a single `TranslateTransform3D`.

