using UnityEngine;

public class VoxelTerrain : MonoBehaviour
{
    public int chunkSize = 16;
    public int viewDistance = 4;
    public float noiseScale = 0.1f;

    private Vector3Int currentPlayerChunk;
    private Dictionary<Vector3Int, Chunk> chunks = new Dictionary<Vector3Int, Chunk>();

    private void Start()
    {
        currentPlayerChunk = GetChunkPositionFromWorldPosition(transform.position);
        GenerateChunksAroundPlayer();
    }

    private void Update()
    {
        Vector3Int newPlayerChunk = GetChunkPositionFromWorldPosition(transform.position);

        if (newPlayerChunk != currentPlayerChunk)
        {
            currentPlayerChunk = newPlayerChunk;
            GenerateChunksAroundPlayer();
        }
    }

    private void GenerateChunksAroundPlayer()
    {
        int halfDistance = Mathf.FloorToInt(viewDistance / 2);
        for (int x = -halfDistance; x <= halfDistance; x++)
        {
            for (int z = -halfDistance; z <= halfDistance; z++)
            {
                Vector3Int chunkPos = currentPlayerChunk + new Vector3Int(x, 0, z);
                if (!chunks.ContainsKey(chunkPos))
                {
                    GenerateChunk(chunkPos);
                }
            }
        }
    }

    private void GenerateChunk(Vector3Int chunkPos)
    {
        Chunk chunk = new Chunk(chunkSize, noiseScale, chunkPos);
        chunks.Add(chunkPos, chunk);
        chunk.Generate();
    }

    private Vector3Int GetChunkPositionFromWorldPosition(Vector3 position)
    {
        int x = Mathf.FloorToInt(position.x / chunkSize);
        int y = Mathf.FloorToInt(position.y / chunkSize);
        int z = Mathf.FloorToInt(position.z / chunkSize);
        return new Vector3Int(x, y, z);
    }
}

