    irq_handler_t handler;
    irq_handler_t thread_fn;
    const char* devname;
    void* dev_id;
} ThreadedIRQ;

SemaphoreHandle_t irqSemaphore;

void irqHandler(void* param)
{
    ThreadedIRQ* threadedIRQ = (ThreadedIRQ*)param;
    unsigned int irq = threadedIRQ->irq;
    irq_handler_t handler = threadedIRQ->handler;
    irq_handler_t thread_fn = threadedIRQ->thread_fn;
    const char* devname = threadedIRQ->devname;
    void* dev_id = threadedIRQ->dev_id;

    // Primary interrupt handler
    if (handler)
    {
        handler(dev_id);
    }

    // Threaded interrupt handler
    if (thread_fn)
    {
        ThreadedIRQ threadedIRQ = {
            .irq = irq,
            .handler = handler,
            .thread_fn = NULL,
            .devname = devname,
            .dev_id = dev_id
        };
        xTaskCreate(thread_fn, devname, configMINIMAL_STACK_SIZE, &threadedIRQ, tskIDLE_PRIORITY + 1, NULL);
    }

    // Give the semaphore to notify the task
    xSemaphoreGive(irqSemaphore);
}

int request_threaded_irq(unsigned int irq, irq_handler_t handler, irq_handler_t thread_fn, unsigned long irqflags, const char* devname, void* dev_id)
{
    ThreadedIRQ threadedIRQ = {
        .irq = irq,
        .handler = handler,
        .thread_fn = thread_fn,
        .devname = devname,
        .dev_id = dev_id
    };

    // Create a binary semaphore
    irqSemaphore = xSemaphoreCreateBinary();
    if (irqSemaphore == NULL)
    {
        return -1;
    }

    // Enable the interrupt
    // ...

    // Register the ISR
    // ...

    // Wait for the interrupt event
    while (1)
    {
        xSemaphoreTake(irqSemaphore, portMAX_DELAY);
        irqHandler(&threadedIRQ);
    }

    return 0;
}
