Certainly! Here's a C program that uses an array to store the unique elements from the given input:

```
#include <stdio.h>

int main() {
  int N;
  printf("Enter the number of elements: ");
  scanf("%d", &N);

  int A[N], unique[N];
  printf("Enter the elements: ");
  for (int i = 0; i < N; i++) {
    scanf("%d", &A[i]);
    unique[i] = -1;  // initializing all elements of unique array to -1
  }

  int uniqueCount = 0;
  for (int i = 0; i < N; i++) {
    int isUnique = 1;
    for (int j = 0; j < N; j++) {
      if (A[i] == A[j] && i != j) {
        isUnique = 0;
        break;
      }
    }
    if (isUnique) {
      unique[uniqueCount] = A[i];
      uniqueCount++;
    }
  }

  printf("Unique elements in the array: ");
  for (int i = 0; i < uniqueCount; i++) {
    printf("%d ", unique[i]);
  }

  return 0;
}
