private void UpdateElementRotation()
{
    // Calculate the angle based on the selected ranges of the sliders
    double angle = 0;

    // Get the value from slider1 for the range 15 to 70
    double slider1Value = slider1.Value;
    if (slider1Value >= 15 && slider1Value <= 70)
