public class Slider1ValueConverter : IValueConverter
{
    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
    {
        // Convert the combined value to Slider1's value range (40-80)
        double combinedValue = (double)value;
        double minimum = 40;
        double maximum = 80;
        double slider1Value = minimum + (combinedValue - minimum) * (maximum - minimum) / 100;
        return slider1Value;
    }

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
    {
        // Convert Slider1's value back to the combined value (0-100)
        double slider1Value = (double)value;
        double minimum = 40;
        double maximum = 80;
        double combinedValue = (slider1Value - minimum) * 100 / (maximum - minimum);
        return combinedValue;
    }
}

public class Slider2ValueConverter : IValueConverter
{
    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
    {
        // Convert the combined value to Slider2's value range (90-180)
        double combinedValue = (double)value;
        double minimum = 90;
        double maximum = 180;
        double slider2Value = minimum + (combinedValue - minimum) * (maximum - minimum) / 100;
        return slider2Value;
    }

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
    {
        // Convert Slider2's value back to the combined value (0-100)
        double slider2Value = (double)value;
        double minimum = 90;
        double maximum = 180;
        double combinedValue = (slider2Value - minimum) * 100 / (maximum - minimum);
        return combinedValue;
    }
}
