To download a video and add text watermark using .NET Core, you can use the following code:

1. Install the `FFmpegCore` NuGet package to interact with FFmpeg:

```shell
dotnet add package FFmpegCore
```

2. Import the required namespaces:

```csharp
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.Drawing.Processing;
using SixLabors.ImageSharp.PixelFormats;
using FFmpegCore;
```

3. Define a method to download the video:

```csharp
public async Task DownloadVideoAsync(string videoUrl, string destinationPath)
{
    using (var ffmpeg = new Engine())
    {
        var inputFile = new MediaFile(videoUrl);
        var outputFile = new MediaFile(destinationPath);

        var conversionOptions = new ConversionOptions { OutputFormat = "mp4" };
        await ffmpeg.ConvertAsync(inputFile, outputFile, conversionOptions);
    }
}
```

4. Define a method to add text watermark to the video:

```csharp
public void AddTextWatermarkToVideo(string videoPath, string watermarkText, string outputFilePath)
{
    using (var ffmpeg = new Engine())
    {
        var input = new MediaFile(videoPath);
        var output = new MediaFile(outputFilePath);

        var filterSettings = new TextWatermarkFilter(watermarkText)
        {
            Position = TextWatermarkPosition.BottomRight
        };

        var conversionOptions = new ConversionOptions { Filters = filterSettings };

        ffmpeg.Convert(input, output, conversionOptions);
    }
}
```

5. Usage example:

```csharp
public async Task Main()
{
    var videoUrl = "https://example.com/video.mp4";
    var destinationPath = "video.mp4";

    // Download the video
    await DownloadVideoAsync(videoUrl, destinationPath);

    // Add text watermark
    var watermarkText = "Your watermark text";
    var outputFilePath = "output.mp4";
    AddTextWatermarkToVideo(destinationPath, watermarkText, outputFilePath);
}
```

Make sure to replace `videoUrl` with the actual URL of the video you want to download, and customize the watermark text and output file paths as needed.

