```java
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

@Service
public class GraphQLService {

    private final RestTemplate restTemplate;

    public GraphQLService(RestTemplate restTemplate) {
        this.restTemplate = restTemplate;
    }

    public ResponseEntity<String> executeGraphQLQuery(String graphqlEndpoint, String query) {

        // Set headers
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);

        // Set request body
        String requestBody = "{\"query\":\"" + query + "\"}";
        HttpEntity<String> request = new HttpEntity<>(requestBody, headers);

        // Send POST request to GraphQL endpoint
        ResponseEntity<String> response = restTemplate.exchange(graphqlEndpoint, HttpMethod.POST, request, String.class);

        return response;
    }
}
```

In this code, we create a `GraphQLService` class that takes a `RestTemplate` instance as a constructor argument. It has a method `executeGraphQLQuery` that takes the GraphQL endpoint URL and the GraphQL query as parameters.

Inside the method, we set the headers for the request to indicate that we are sending JSON data. We then create a request body with the GraphQL query, and make a POST request to the GraphQL endpoint using `restTemplate.exchange` method.

