```cpp
#include <iostream>
#include <vector>
#include <array>
#include <cmath>

// Function for cubic interpolation
float cubicInterpolation(float x0, float x1, float x2, float x3, float t) {
    float p = (x3 - x2) - (x0 - x1);
    float q = (x0 - x1) - p;
    float r = x2 - x0;
    float s = x1;

    return p * std::pow(t, 3) + q * std::pow(t, 2) + r * t + s;
}

int main() {
    int N = 10;

    // Generate input data
    std::vector<float> input(N);
    for (int i = 0; i < N; i++) {
        input[i] = i;
    }

    // Perform interpolation
    int interpolationFactor = 5;
    std::vector<float> interpolated;

    for (int i = 0; i < N - 3; i++) {
        for (int j = 0; j < interpolationFactor; j++) {
            float t = (float)j / interpolationFactor;
            float interpolatedValue = cubicInterpolation(input[i], input[i+1], input[i+2], input[i+3], t);
            interpolated.push_back(interpolatedValue);
        }
    }

    // Print interpolated values
    std::cout << "Interpolated Values:" << std::endl;
    for (float value : interpolated) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    return 0;
}
```

